window.__D("text/zohar/c028",{"p":[[9520012085,"<p>רִבִּי יִצְחָק הֲוָה אָזִיל לְקַטְפוּרֵי דַּאֲבוֹי. חָמָא חַד בַּר נָשׁ, דְּסַאטֵי בְּקוּטְרָא דְּמָטוּלָא אֲכַתְפוֹי. אָמַר לֵיהּ, שׁוּרְטָא דְּקִישְׁטָא בְּכַתְפָךְ אֲמַאי, לָא אָמַר לֵיהּ מִדִי. אָזַל אֲבַתְרֵיהּ, חָמָא דְּעַיִּיל בִּמְעַרְתָּא חֲדָא, עָאל אֲבַתְרֵיהּ, חָמָא קְטוּרָא דִּתְנָנָא דְּהֲוָה סָלִיק מִתְּחוֹת אַרְעָא, וְעָאל הַהוּא בַּר נָשׁ בְּנוּקְבָּא חַד, וְאִתְכַּסְיָא מִנֵּיהּ. דָּחִיל רִבִּי יִצְחָק, וְנָפַק לְפוּם מְעַרְתָּא.</p>\n<p>עַד דְּהֲוָה יָתִיב, אַעְבְּרוּ רִבִּי יְהוּדָה וְרִבִּי חִזְקִיָּה, חָמָא לוֹן, וְקָרִיב גַּבֵּיהוֹן, סַח לוֹן עוֹבָדָא. אָמַר רִבִּי יְהוּדָה, בְּרִיךְ רַחֲמָנָא דְּשֵׁזְבָךְ. הַאי מְעַרְתָּא דְּסָגִיר, דִּסְרוֹנְיָא הִיא, וְכָל יַתְבֵי הַהִיא קַרְתָּא, חַרְשִׁין אִינּוּן, וְאַתְיָין לְמַדְבְּרָא לְחִוְויָין אוּכָמִין, דְּאִינּוּן בְּנֵי עֶשֶׂר שְׁנִין, אוֹ יַתִּיר, לְמֶעְבַּד חַרְשִׁין, וְלָא מְנַטְרָא מִנַּיְיהוּ, וְאִתְעָבִידוּ סְגִירִין וְכָל זַיְינֵי חַרְשִׁין דִּלְהוֹן בְּהַאי מְעַרְתָּא אִינּוּן.</p>\n<p>אָזְלוּ, עַד דַּהֲווֹ אָזְלֵי, אִעְרָעְרוּ בְּחַד בַּר נָשׁ דְּהֲוָה אָתֵי, וּבְרֵיהּ דְּהֲוָה מְרַע, קָטִיר עַל חֲמָרָא. אָמְרוּ לֵיהּ מַאן אַתְּ. אָמַר לְהוֹ יוּדָאי, וְדָא הוּא בְּרִי דְּאִיהוּ קָטִיר עַל חֲמָרָא. אָמְרוּ לֵיהּ, אֲמַאי הוּא קָטִיר. אָמַר לוֹן דִּיוּרִי הוּא בְּחַד כְּפַר, דְּאִיהוּ מִבְּנֵי רוֹמָאֵי, וְהַאי בְּרִי הֲוָה אוֹלִיף אוֹרַיְיתָא בְּכָל יוֹמָא, וַהֲוָה אַהְדָּר לְבֵיתָא, וְלָעֵי לוֹן לְאִינּוּן מִלִּין. וְג' שְׁנִין הֲוָה דִּיוּרִי בְּהַהוּא בֵּיתָא, וְלָא חֲמֵינָא מִדִי. וְהַשְׁתָּא יוֹמָא חַד עָאל בְּרִי לְבֵיתָא לְאָהַדְּרָא מִלִּין, אַעְבָּר חַד רוּחָא קָמֵיהּ, וְנָזִיק לֵיהּ, אַעֲקָם פּוּמֵיהּ וְעֵינוֹי, וִידוֹי אִתְעַקָמוּ, וְלָא יָכִיל לְמַלְּלָא. וַאֲתֵינָא לְגַבֵּי מְעַרְתָּא דִּסְגִירוּ דִּסְרוֹנְיָא דִּלְמָא יִלְּפוּן לִי מִלָּה דְּאַסוּותָא.</p>\n<p>אָמַר לֵיהּ רִבִּי יְהוּדָה, וּבְהַהוּא <Nonei></i>בֵּיתָא יַדְעַת מִן קַדְמַת דְּנָא, דְּאִתְנְזַק בֵּיהּ בַּר נָשׁ אָחֳרָא. אָמַר לֵיהּ יְדַעְנָא, דְּהָא מִכַּמָּה יוֹמִין אִתְנְזַק בֵּיהּ חַד בַּר נָשׁ, וַהֲווּ אַמְרֵי דְּמַרְעָא הֲוָה, וּמִנַּיְיהוּ אַמְרֵי דְּרוּחָא דְּבֵיתָא, וּלְבָתַר עָאלוּ בֵּיהּ כַּמָה בְּנֵי נָשָׁא, וְלָא אִתְנְזִיקוּ. אָמְרוּ, הַיְינוּ דְּאַמְרֵי חַבְרַיָּיא, וַוי לְאִינוּן דְּעַבְרִין עַל מִלַּיְיהוּ.</p>\n<p>פָּתַח רִבִּי יְהוּדָה וְאָמַר, (ירמיהו כ״ב:י״ג) הוֹי בּוֹנֶה בֵיתוֹ בְּלֹא צֶדֶק, דְּהָא בְּכָל אֲתַר דְּאִשְׁתְּכַח בֵּיהּ צֶדֶק, כָּל רוּחִין וְכָל מַזִּיקֵי עָלְמָא עַרְקֵי מִנֵּיהּ, וְלָא מִשְׁתַּכְּחֵי קַמֵּיהּ. וְעִם כָּל דָּא, מַאן דְּאַקְדִים וְנָטִיל אֲתַר, אָחִיד בֵּיהּ. אָמַר לֵיהּ רִבִּי חִזְקִיָּה, אִי הָכִי שָׁקִיל שְׁמָא קַדִּישָׁא כְּרוּחַ מִסְאֲבָא.</p>\n<p>אָמַר לֵיהּ, לָאו הָכִי, אֶלָּא שְׁמָא קַדִּישָׁא לָא שַׁרְיָא בַּאֲתַר מִסְאֲבָא, וּבְגִין כַּךְ, אִי שְׁמָא קַדִּישָׁא נָטִיל אֲתַר מִקַּדְמַת דְּנָא, כָּל רוּחִין וְכָל מַזִּיקִין דְּעָלְמָא לָא יַכְלִין לְאִתְחֲזָאָה בֵּיהּ, כָּל שֶׁכֵּן לְקָרְבָא בַּהֲדֵיהּ. אִי רוּחַ מִסְאֲבָא קָדִים, נָטִיל אֲתַר. שְׁמָא קַדִּישָׁא לָא שַׁרְיָא בֵּיהּ, דְּהָא לָאו אַתְרֵיהּ.</p>\n<p>וְכַד הֲוָה נָחִית נֶגַע צָרַעַת, הֲוָה מַדְכֵּי אַתְרָא, וְאַפִּיק לְרוּחַ מִסְאֲבָא מֵאַתְרֵיהּ, וּלְבָתַר מְנַתְּצֵי בֵּיתָא, אֲבָנִין וְאָעִין וְכֹלָּא, וּבָנֵי לָהּ כְּמִלְּקַדְּמִין, בִּסְטָר קַדִּישָׁא בְּצֶדֶק, דְּדָכִיר לֵיהּ לִשְׁמָא קַדִּישָׁא, וְלִשְׁרֵי עָלֵיהּ קְדוּשָּׁה, וְעִם כָּל דָּא בְּעַפְרָא אָחֳרָא, וְיַרְחִיק בֵּיתָא מֵאַתְרֵיהּ, מִיְּסוֹדָא קַדְמָאָה תְּרֵי טְפָחִים.</p>\n<p>הַשְׁתָּא דְּלָא אִתְחֲזֵי, וְלָא נָחִית מַאן דִּמְקַטְרֵג בֵּיהּ בְּהַהוּא רוּחַ מִסְאֲבָא, לְאַפָּקָא לֵיהּ מֵאַתְרֵיהּ, מַאי תָּקַנְתֵּיה. אִי יָכִיל לְנָפְקָא מֵהַאי בֵּיתָא שַׁפִּיר. וְאִי לָאו יִבְנֶה לֵיהּ כְּמִלְּקַדְּמִין, בַּאֲבָנִין אָחֳרָנִין, וְאָעִין וְכֹלָּא, וְיַפִּיק וְיַרְחִיק לֵיהּ מֵאֲתַר קַדְמָאָה, וְיִבְנֵי לֵיהּ עַל שְׁמָא קַדִּישָׁא.</p>\n<p>וְעִם כָּל דָּא, לָא נָפִיק הַהוּא רוּחָא מִן אֲתַר קַדְמָאָה, בְּגִין דִּקְדוּשָּׁה לָא שַׁרְיָא עַל אֲתַר מִסְאֲבָא. אָמַר רִבִּי יִצְחָק לָמָּה לֵיהּ לְאַטְרְחָא כּוּלֵי הַאי, בְּזִמְנָא דָּא כְּתִיב, (קהלת א׳:ט״ו) מְעֻוָּות לֹא יוּכַל לִתְקוֹן וְגוֹ'. מִיּוֹמָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא, לָא אִשְׁתְּכַח אַסוּותָא בְּעָלְמָא, בְּגִינֵי כַּךְ בָּעֵי בַּר נָשׁ לְאִזְדַּהֲרָא, כִּי הֵיכִי דְּלִהֱוִי נָטִיר.</p>\n<p>אַמְרֵי נְזִיל בַּהֲדֵי הַאי בַּר נָשׁ וְנֶחֱמֵי. אָמַר רִבִּי יִצְחָק, אָסִיר לָן. אִי הֲוָה אָזִיל לְגַבֵּי גַּבְרָא רַבָּא דָּחִיל חַטָּאָה, כְּגוֹן נַעֲמָן לְגַבֵּי אֱלִישָׁע, נֵזִיל אֲבַתְרֵיהּ. הַשְׁתָּא דְּאִיהוּ אָזִיל לְגַבֵּי רְחִיקֵי עָלְמָא, רְחִיקֵי אוֹרַיְיתָא, גַּעֲלֵי מִכֹּלָּא, אָסִיר לָן לְאִתְחֲזָאָה קָמַיְיהוּ. בְּרִיךְ רַחֲמָנָא דִּי שֵׁזִיב לָן מִנַּיְיהוּ. וְהַאי בַּר נָשׁ אָסִיר לֵיהּ. אָמַר רִבִּי יְהוּדָה, וְהָא תָּנֵינָן בַּכֹּל מִתְרַפְּאִין, חוּץ מֵעֲצֵי אֲשֵׁרָה וְכוּ'. אָמַר לֵיהּ, וְדָא עֲבוֹדָה זָרָה אִיהוּ, וְלָא עוֹד, אֶלָּא דְּהָא כְּתִיב (דברים י״ח:י׳) לֹא יִמָּצֵא בְךָ מַעֲבִיר בְּנוֹ וּבִתּוֹ בָּאֵשׁ וְגוֹ'. אַזְלוּ לְאָרְחַיְיהוּ.</p>\n<p>אָזַל הַהוּא בַּר נָשׁ לְהַהִיא מְעַרְתָּא, הוּא וּבְרֵיהּ, שָׁרֵי לֵיהּ בִּמְעַרְתָּא. עַד דְּנָפַק אֲבוֹי לְקַטְרָא לַחֲמָרֵיהּ, נָפַק קִיטוּרָא דְּאֶשָּׁא, וּמָחָא לֵיהּ בְּרֵישָׁא, וְקַטְלֵיהּ. אַדְּהָכִי עָאל אֲבוֹי, וְאַשְׁכְּחֵיהּ מִית. נָטַל לֵיהּ וְלַחֲמָרֵיהּ, וְאָזַל לֵיהּ. וְאַשְׁכַּח לְהוּ לְבָתַר יוֹמָא חַד, לְרִבִּי יִצְחָק, וּלְרִבִּי יְהוּדָה, וְרִבִּי חִזְקִיָּה, דַּהֲווֹ אַזְלֵי. בָּכָה קָמַיְיהוּ, וְסָח לוֹן עוֹבָדָא. אָמַר רִבִּי יִצְחָק, וְלָא זִמְנִין סַגִּיאִין אֲמֵינָא לָךְ, דְּאָסִיר לְמֵיהַךְ תַּמָּן. בְּרִיךְ רַחֲמָנָא, (דניאל ד׳:ל״ד) דִּי כָל מַעֲבָדוֹהִי קְשׁוֹט, וְאֹרְחָתֵיהּ דִּין. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּאַזְלִין בְּאֹרַח קְשׁוֹט, בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, וְעָלַיְיהוּ כְּתִיב, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ וְגוֹ'.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, בְּכָל עוֹבָדוֹי דְּבַּר נָשׁ, לִבְעֵי לֵיהּ דְּלִהֱווֹן כֻּלְּהוּ לִשְׁמָא קַדִּישָׁא. מַאי לִשְׁמָא קַדִּישָׁא. לְאַדְכְּרָא בְּפוּמֵיהּ שְׁמָא קַדִּישָׁא עַל כָּל מַה דְּאִיהוּ עָבִיד, דְּכֹלָּא הוּא לְפוּלְחָנֵיהּ, וְלָא יִשְׁרֵי עֲלוֹי סִטְרָא אָחֳרָא. בְּגִין דְּאִיהוּ זַמִּין תְּדִירָא לְגַבֵּי בְּנֵי נָשָׁא, וְיָכִיל לְאַשְׁרָאָה עַל הַהוּא עֲבִידְתָּא. וְעַל דָּא, הַשְּׁתִּי אוֹ הָעֵרֶב הֲוָה אִסְתְּאַב, וְשַׁרְיָא <Nonei></i>עָלֵיהּ רוּחַ מִסְאֲבָא. וּמַה בְּהַאי כַּךְ, מַאן דְּפָקִיד מִלּוֹי לְסִטְרָא אָחֳרָא דְּלָא אִצְטְרִיךְ, עַל אַחַת כַּמָּה וְכַמָּה. וּבְגִין כָּךְ כְּתִיב (דברים כ״ג:י׳) וְנִשְׁמַרְתָּ מִכָּל דָּבָר רָע.</p>"],[9520012086,"<p>רִבִּי אֶלְעָזָר הֲוָה אָזִיל לְמֵחֱמֵי לַאֲבוֹי (ס\"א לחמוי) וַהֲוָה עִמֵּיהּ רִבִּי אַבָּא. אָמַר רִבִּי אַבָּא נֵימָא מִלִּין דְּאוֹרַיְיתָא וְנֵזִיל. פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (בראשית י״ב:י״ג) אִמְרִי נָא אֲחוֹתִי אָתְּ, הַאי קְרָא קַשְׁיָא. וְכִי אַבְרָהָם דְּאִיהוּ דָּחִיל חַטָּאָה, רְחִימוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, הֲוָה אָמַר הָכִי עַל אִתְּתֵיהּ, בְּגִין דְּיוֹטְבִין לֵיהּ. אֶלָּא אַבְרָהָם, אַף עַל גַּב דְּהֲוָה דָּחִיל חַטָּאָה, לָא סָמִיךְ עַל זְכוּתָא דִּילֵיהּ, וְלָא בָּעָא מִן קוּדְשָׁא בְּרִיךְ הוּא לְאַפָּקָא זְכוּתֵיהּ, אֶלָּא עַל זְכוּתָא דְּאִתְּתֵיהּ, דְּיִרְוַוח בְּגִינָהּ מָמוֹנָא דִּשְׁאָר עַמִּין, דְּהָא מָמוֹנָא בְּאִתְּתֵיהּ זָכֵי לֵיהּ בַּר נָשׁ, הֲדָא הוּא דִכְתִיב, (משלי י״ט:י״ד) בַּיִת וָהוֹן נַחֲלַת אָבוֹת וּמֵיְיָ' אִשָּׁה מַשְׂכָּלֶת. מַאן דְּזָכֵי בְּאִשָּׁה מַשְׂכָּלֶת, זוֹכֶה בְּכֹלָּא. וּכְתִיב, (משלי ל״א:י״א) בָּטַח בָּהּ לֵב בַּעְלָהּ וְשָׁלָל לֹא יֶחְסָר.</p>\n<p>וְאַבְרָהָם הֲוָה אָזִיל בְּגִינָהּ, לְמֵיכַל שְׁלָלָא מִשְּׁאַר עַמִּין, וְסָמִיךְ עַל זְכוּתָא דִּילָהּ, דְּלָא יֵכְלוּן לְאַעְנְשָׁא לֵיהּ, וּלְחַיְיכָא בָּהּ. וּבְגִּינֵי כַּךְ לָא יָהִיב מִדִי לְמֵימַר אֲחוֹתִי הִיא. וְלֹא עוֹד, אֶלָּא דְּחָמָא חַד מַלְאָכָא אָזִיל קַמָהּ, וְאָמַר לֵיהּ לְאַבְרָהָם, לָא תִּדְּחַל מִנָּהּ, קוּדְשָׁא בְּרִיךְ הוּא שָׁדַר לִי, לְאַפָּקָא לֵהּ מָמוֹנָא דִּשְׁאַר עַמִּין, וּלְנַטְרָא לָהּ מִכֹּלָּא. וּכְדֵין לָא דָּחִיל אַבְרָהָם מְאִתְּתֵיהּ, אֶלָּא מִנֵיהּ, דְּלָא חָמָא עִמֵּיהּ מַלְאָכָא, אֶלָּא עִמָּהּ. אָמַר הָא הִיא מִתְנַטְרָא, וַאֲנָא לָא נְטִירְנָא. וּבְגִּינֵי כַּךְ אָמַר, אִמְרִי נָא אֲחוֹתִי אַתְּ וְגוֹ'.</p>\n<p>יִיטַב לִי, יֵיטִיבוּ לִי מִבָּעֵי לֵיהּ, דִּכְתִּיב וְהָיָה כִּי יִרְאוּ אוֹתָךְ הַמִצְרִים וְאָמְרוּ אִשְׁתּוֹ זֹאת, וְעַל דָּא יֵיטִיבוּ לִי מִבָּעֵי לֵיהּ. אֶלָּא יִיטַב לִי, דָּא דְּאָזִיל קַמָּךְ. יִיטַב לִי בְּהַאי עָלְמָא קוּדְשָׁא בְּרִיךְ הוּא בְּמָמוֹנָא. וְחָיְתָה נַפְשִׁי בְּהַהוּא עָלְמָא בִּגְלָלֵךְ, דְּלָא תִּסְטִי מִן אוֹרְחָא דִּקְשׁוֹט, דְּאִי אַזְכֵּי בְּגִינָךְ בְּמָמוֹנָא בְּהַאי עָלְמָא, וְתִסְטִי אַנְתְּ בְּאוֹרְחָא, הָא מִיתָא זְמִינָא בְּהַהוּא עָלְמָא, אֶלָּא תִּסְתַּמֵר, דִּתְחִי נַפְשִׁי בְּהַהוּא עָלְמָא בִּגְלָלֵךְ.</p>\n<p>וּבְגִין דְּהַהוּא מַלְאָכָא אָזִיל קַמָה לְנַטְרָא לָהּ, מַה כְּתִיב. וַיְנַגַּע יְיָ' אֶת פַּרְעֹה וְגוֹ', עַל דְּבַר שָׂרַי וַדַּאי, דַּהֲוַת אַמְרַת לְמַלְאָכָא מָחֵי, וְהוּא מָחֵי. וְעַל דָּא לָא דָּחִיל אַבְרָהָם מִנָּהּ כְּלוּם, דְּהָא הִיא מִתְנַטְרָא. וּמַה דְּדָחִיל, מִגַּרְמֵיהּ דָּחִיל, דְּלָא חָמָא עִמֵּיהּ נְטוּרָא הָכִי.</p>\n<p>תָּא חֲזֵי, עֶשֶׂר זִמְנִין פְּקִידַת שָׂרָה לְמַלְאָכָא, לְמַחֲאָה לְפַרְעֹה. וּבְעֶשֶׂר מַכְתְּשִׁין אַלְקֵי. סִימָנָא עַבְדַת שָׂרָה לִבְנָהָא בַּתְרָאָה בְּמִצְרַיִם.</p>\n<p>רִבִּי אַבָּא פָּתַח, (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַחֲזָאָה פּוּרְקָנָא לִבְנוֹי, כְּאִינּוּן יוֹמִין דְּשָׁלַח קוּדְשָׁא בְּרִיךְ הוּא לְאַפָּקָא לְיִשְׂרָאֵל, וְאַחְזֵי אִינּוּן מַכְתְּשִׁין בְּמִצְרָאֵי, וְאַלְקֵי לוֹן בְּגִינֵיהוֹן דְּיִשְׂרָאֵל. תָּא חֲזֵי, מַה בֵּין פּוּרְקָנָא דָּא, לְפוּרְקָנָא דְּמִצְרַיִם. פּוּרְקָנָא דְּמִצְרַיִם הֲוָה בְּחַד מַלְכָּא, וּבְמַלְכוּ חֲדָא. הָכָא, בְּכָל מַלְכִין דְּעָלְמָא, וּכְדֵין יִתְיְיקָּר קוּדְשָׁא בְּרִיךְ הוּא בְּכָל עָלְמָא, וְיִנְדְּעוּן כֹּלָּא שׁוּלְטָנוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ יִלְקוּן בְּמַכְתְּשִׁין עִלָּאִין, עַל חַד תְּרֵין, בְּגִין דְּיִסָּרְבוּן כֻּלְּהוּ בְּיִשְׂרָאֵל.</p>\n<p>וּכְדֵין יִתְגְּלֵי שׁוּלְטָנֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (זכריה י״ד:ט׳) וְהָיָה יְיָ' לְמֶלֶךְ עַל כָּל הָאָרֶץ. וּכְדֵין כֻּלְּהוּ יִתְנַדְּבוּן בְּהוּ בְּיִשְׂרָאֵל לְּקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ו:כ׳) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם וְגוֹ'. כְּדֵין קַיְימִין אֲבָהָן בְּחֶדְוָה, לְמֵחֱמֵי פּוּרְקָנָא דִּבְנַיְיהוּ כְּמִלְּקַדְּמִין. הֲדָא הוּא דִכְתִיב, כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. אָמֵן כֵּן יְהִי רָצוֹן. בָּרוּךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן: יִמְלוֹךְ יְיָ' אָמֵן וְאָמֵן:</p>"],[9520012087,"<p><Nonei></i>(ויקרא י״ד:א׳-ב׳) וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה לֵאמֹר. זֹאת תִּהְיֶה תּוֹרַת הַמְּצוֹרָע בְּיוֹם טָהֳרָתוֹ וְגוֹ'. רִבִּי אַבָּא פָּתַח, (ספרי שמות כ\"ו ע\"א) (איוב י״ט:כ״ט) גּוּרוּ לָכֶם מִפְּנֵי חֶרֶב כִּי חֵמָה עֲוֹנוֹת חָרֶב לְמַעַן תֵּדְעוּן שַׁדּוּן. שַׁדּוּן, שַׁדִּין כְּתִיב. כַּמָה אִית לוֹן לִבְנֵי נָשָׁא לְאִסְתַּמְּרָא אָרְחַיְיהוּ וּלְדַחֲלָא מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּלָא יִסְטֵי מֵאָרְחָא דְּכַשְׁרָא, וְלָא יַעֲבוֹר עַל פִּתְגָּמֵי אוֹרַיְיתָא, וְלָא יִתְנְשֵׁי מִנָּהּ.</p>\n<p>דְּכָל מַאן דְּלָא לָעֵי בְּאוֹרַיְיתָא, וְלָא יִשְׁתְּדַל בָּה, נְזִיפָא הוּא מְקוּדְשָׁא בְּרִיךְ הוּא, רְחִיקָא הוּא מִנֵּיהּ, לָא שַׁרְיָא שְׁכִינְתָּא עִמֵּיהּ. וְאִינּוּן נְטוּרִין, דְּאַזְלִין עַמֵּיהּ, אִסְתְּלָקוּ מִנֵּיהּ, וְלֹא עוֹד אֶלָּא דְּמַכְרְזֵי קָמֵיהּ וְאַמְרֵי, אִסְתְּלָקוּ סוֹחֲרָנֵיהּ דִּפְלַנְיָא, דְּלָא חָשׁ עַל יְקָרָא דְּמָארֵיהּ. וַוי לֵיהּ, דְּהָא שַׁבְקוּהוּ עִלָּאִין וְתַתָּאִין. לֵית לֵיהּ חוּלָקָא בְּאָרְחָא דְּחַיֵּי.</p>\n<p>וְכַד אִיהוּ אִשְׁתָּדַּל בְּפוּלְחָנָא דְּמָארֵיהּ, וְלָעֵי בְּאוֹרַיְיתָא, כַּמָה נְטוּרִין זְמִינִין לָקֳבְלֵיהּ לְנַטְרָא לֵיהּ, וּשְׁכִינְתָּא שַׁרְיָא עָלֵיהּ, וְכֹלָּא מַכְרְזֵי קַמֵּיהּ וְאַמְרֵי, הָבוּ יְקָרָא לְדִיּוּקְנָא דְּמַלְכָּא, הָבוּ יְקָרָא לִבְרֵיהּ דְּמַלְכָּא, אִתְנְטִיר הוּא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, זַכָּאָה חוּלָקֵיהּ.</p>\n<p>תָּא חֲזֵי, בְּלִישָׁנָא בִּישָׁא דְּאָמַר נָחָשׁ לְאִתְּתָא, גָּרִים לְאִתְּתָא, וּלְאָדָם, לְמִגְזַר עָלַיְיהוּ מִיתָה, וְעַל כָּל עָלְמָא בְּלִישָׁנָא בִּישָׁא כְּתִיב, (תהילים נ״ז:ה׳) וּלְשׁוֹנָם חֶרֶב חַדָּה. בְּגִין כָּךְ, גּוּרוּ לָכֶם מִפְּנֵי חֶרֶב, מִפְּנֵי לִישָׁנָא בִּישָׁא. כִּי חֵמָה עֲוֹנוֹת חָרֶב. מַאי כִּי חֵמָה עֲוֹנוֹת חָרֶב. דָּא חֶרֶב לַיְיָ', דִּתְנָן, חֶרֶב אִית לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, דְּבֵיהּ דָּאִין לְחַיָּיבַיָּא. הֲדָא הוּא דִכְתִיב, (ישעיהו ל״ד:ו׳) חֶרֶב לַיְיָ' מָלְאָה דָם. (דברים ל״ב:מ״ב) וְחַרְבִּי תֹּאכַל בָּשָׂר. וּבְגִין כָּךְ גּוּרוּ לָכֶם מִפְּנֵי חֶרֶב כִּי חֵמָה עֲוֹנוֹת חָרֶב לְמַעַן תֵּדְעוּן שַׁדּוּן, שַׁדִּין כְּתִיב. בְּגִין דְּתֵדְעוּן דְּהָכִי אִתְּדָּן, מַאן דְּאִית לֵיהּ חֶרֶב בְּלִישָׁנֵיהּ, אִזְדְּמַן לֵיהּ חֶרֶב (ס\"א אחדן בההוא חרב) דְּשָׁצֵי כֹּלָּא, הֲדָא הוּא דִכְתִיב זֹאת תִּהְיֶה תּוֹרַת הַמְּצוֹרָע.</p>"],[9520012088,"<p>רִבִּי אֶלְעָזָר פָּתַח, (קהלת ט׳:י״ב) וְכַצִּפֳּרִים הָאֲחוּזּוֹת בַּפָּח כָּהֵם יוּקָשִׁים בְּנֵי הָאָדָם. הַאי קְרָא הָא אִתְּמַר. אֲבָל תָּא חֲזֵי, בְּנֵי נָשָׁא לָא יַדְעִין, וְלָא שַׁמְעִין, וְלָא מִסְתַּכְּלֵי בִּרְעוּתָא דְּמָארֵיהוֹן, וְכָרוֹזָא כָּל יוֹמָא קָארֵי קָמַיְיהוּ, וְלֵית מַאן דְּצָיִית לֵיהּ, וְלֵית מַאן דְּיִתְּעַר רוּחֵיהּ לְפוּלְחָנָא דְּמָארֵיהּ.</p>\n<p>בְּשַׁעֲתָא דְּרָמַשׁ לֵילְיָא, וְתַרְעִין סְתִימִין, אִתְּעַר נוּקְבָּא דִּתְהוֹמָא רַבָּא, וְכַמָּה חֲבִילֵי טְרִיקִין מִשְׁתַּכְּחֵי בְּעָלְמָא. כְּדֵין אָפִּיל קוּדְשָׁא בְּרִיךְ הוּא שֵׁינָתָא עַל כָּל בְּנֵי עָלְמָא, וַאֲפִילּוּ עַל כָּל דִּי בְּהוֹן אִתְּעָרוּתָא דְּחַיֵּי, וְאִינּוּן שָׁאטָן בְּעָלְמָא, וּמוֹדְעִין לְהוּ לִבְנֵי נָשָׁא, מִלִּין, מִנְּהוֹן כְּדִיבָן, וּמִנְּהוֹן קְשׁוֹט, וּבְנֵי נָשָׁא אִתְקְטָרוּ בְּשֵׁינָתָא.</p>\n<p>כַּד אִתְּעַר רוּחָא דְּצָפוֹן, וְאִתְפְּלִיג לֵילְיָא, שַׁלְהוֹבָא נָפְקָא וּבָטַשׁ תְּחוֹת גַּדְפּוֹי דְּתַרְנְגוֹלָא, וְקָרֵי, וְקוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִנְתָּא דְּעֵדֶן לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּא. וּכְדֵין כָּרוֹזָא נָפִיק וְקָרֵי, וְכָל בְּנֵי עָלְמָא מִתְעָרֵי בְּעַרְסַיְיהוּ, אִינּוּן דִּי בְּהוֹן אִתְּעָרוּתָא דְּחַיֵּי, קַיְימִין לְפוּלְחָנָא דְּמָארֵיהוֹן, וְעַסְקֵי בְּאוֹרַיְיתָא וּבִשְׁבָחָא דְּקוּדְשָׁא בְּרִיךְ הוּא עַד דְּאָתֵי צַפְרָא.</p>"],[9520012089,"<p>כַּד אָתֵי צַפְרָא, (ס\"א כרוזא קרי בקול) כָּל חַיָּילִין וּמַשִׁרְיָין דִּלְעֵילָּא מְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וְגוֹ'. כְּדֵין כַּמָה תַּרְעִין אִתְפְּתָחוּ לְכָל סִטְרִין. וְתַרְעָא דְּאַבְרָהָם, אִתְפְּתַח בָּהּ בִּכְנֶסֶת יִשְׂרָאֵל, לְזַמְּנָא לְכָל בְּנֵי עָלְמָא, הֲדָא הוּא דִּכְתִּיב, (בראשית כ״א:ל״ג) וַיִּטַּע אֵשֶׁל בִּבְאֵר שָׁבַע.</p>\n<p>וּמַאן דְּלָא יִתְּעַר רוּחֵיהּ בְּפוּלְחָנָא דְּמָרֵיהּ, בְּהֵיךְ <Nonei></i>אַנְפִּין יְקוּם קָמֵי מַלְכָּא, כַּד יִתְּעֲרוּן עָלֵיהּ בְּדִינָא, וְיִתְפְּשׂוּן לֵיהּ בְּקוֹלָרָא, וְלָא יִשְׁתְּכַּח עָלֵיהּ זְכוּתָא לְאִשְׁתְּזָבָא, כְּדֵין כְּתִיב, (קהלת ט׳:י״ב) וְכַצִּפֳּרִים הָאֲחֻזוֹת בַּפָּח כָּהֵם יוּקָשִׁים בְּנֵי אָדָם. וְעַד לָא יִנְפּוֹק בַּר נָשׁ מֵהַאי עָלְמָא, בְּכַמָּה דִּינִין אִתְּדָּן נַפְשָׁא עִם גּוּפָא, עַד לָא יִתְפָּרְשׁוּן דָּא מִן דָּא, וְלֵית מַאן דְּיִשְׁגַּח.</p>\n<p>(אפילו) בְּהַהוּא זִמְנָא דְּמָטָא שַׁעֲתָא לְאִתְפָּרְשָׁא, לָא נָפְקָא נַפְשָׁא מִן גּוּפָא, עַד דְּאִתְגְּלֵי עָלֵיהּ שְׁכִינְתָּא, וְנַפְשָׁא, מִגּוֹ חֶדְוָתָא וַחֲבִיבוּתָא דִּשְׁכִינְתָּא, נָפְקָא מִגּוּפָא לְקָֹבְלָהָא. אִי זַכָּאָה הוּא, מִתְקְשַׁר בָּהּ וְאִתְדַּבָּק בָּהּ. וְאִי לָאו, שְׁכִינְתָּא אַזְלָא, וְהִיא אִשְׁתְּאָרַת, וְאַזְלַת וּמִתְאַבְּלָא עַל פְּרִישׁוּתָא דְּגוּפָא. מַתְלָא אַמְרֵי. שׁוּנְרָא מֵאֶשָּׁא לָא מִתְפָּרְשָׁא, חַדְדֵי לְסַכִּינָא, אַזְלָא אֲבַתְרֵיהּ.</p>\n<p>לְבָתַר אִתְדָּנוּ תַּרְוַויְיהוּ עַל יְדוֹי דְּדוּמָה. גּוּפָא אִתְּדָּן בְּקִבְרָא עַד דְּתָב לְעַפְרָא, וְנַפְשָׁא בְּאֶשָּׁא דְּגֵיהִנָּם בְּכַמָּה דִּינִין, עַד הַהוּא זִמְנָא דְּאִתְגְּזַר עָלָהּ לְקַבְּלָא עוֹנְשָׁא. בָּתַר דְּקַבִּילַת עוֹנְשָׁא, וּמָטֵי זִמְנָא לְאִתְדַּכְּאָה, כְּדֵין אִסְתָּלְקָא מִגֵּיהִנָּם, וְאִתְלַבְּנַת מֵחוֹבָהָא כְּפַרְזְלָא דְּאִתְלָבַּן בְּנוּרָא, וְסַלְּקִין עִמָּהּ, עַד דְּעָאלָת לְגִנְתָּא דְּעֵדֶן דִּלְתַתָּא, וְאִסְתַּחֵי תַּמָּן בְּאִינּוּן מַיָּא, וְאִסְתַּחֵי בְּבוּסְמִין דְּתַמָּן. כְּמָה דְאַתְּ אָמֵר, (שיר השירים) מְקֻטֶּרֶת מֹר וּלְבֹנָה. וְקַיְּימָא תַּמָּן עַד זִמְנָא דְּאִתְגְּזַר עָלֵיהּ לְאִתְרַחֲקָא מֵאֲתַר דְּיַתְבִין בֵּיהּ צַדִּיקַיָּא.</p>\n<p>וְכַד מָטָא זִמְנָא לְסַלְּקָא, כְּדֵין סַלְּקִין עִמָּהּ, דַּרְגָּא בָּתַר דַּרְגָּא, עַד דְּאִתְקְרִיבַת כְּקוּרְבְּנָא עַל מַדְבְּחָא. הֲדָא הוּא דִכְתִיב, זֹאת תִּהְיֶה תּוֹרַת הַמְּצוֹרָע בְּיוֹם טָהֳרָתוֹ וְהוּבָא אֶל הַכֹּהֵן, כַּהֲנָא עִלָּאָה דִּלְעֵילָּא, הַאי נַפְשָׁא דְּלָא אִסְתְּאָבַת כָּל כַּךְ, בְּהַאי עָלְמָא, הַאי אִית לָהּ תְּקַנְתָּא, כְּגַוְונָא דָּא. וְאִי לָאו, (קהלת א׳:ט״ו) מְעֻוָּות לֹא יוּכַל לִתְקוֹן וְגוֹ'.</p>"],[9520012090,"<p>(ויקרא י״ד:ב׳) זֹאת תִּהְיֶה תּוֹרַת הַמְּצוֹרָע. רִבִּי יִצְחָק פָּתַח, (קהלת א׳:ה׳) וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ וְגוֹ'. הַאי קְרָא אִתְּמַר, וְאוֹקִימְנָא לֵיהּ בְּנִשְׁמְתָא דְּבַּר נָשׁ, בְּשַׁעֲתָא דְּהִיא קַיְּימָא עִמֵּיהּ דְּבַּר נָשׁ בְּהַאי עָלְמָא, כְּדֵין, וְזָרַח הַשֶּׁמֶשׁ. וּבָא הַשָּׁמֶשׁ, בְּזִמְנָא דְּנָפִיק בַּר נָשׁ מֵהַאי עָלְמָא, וְאִשְׁתְּכַח בִּתְשׁוּבָה, כְּדֵין אֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ הוּא שָׁם, אִי זַכָּאָה אִיהוּ, כְּמָה דְאַתְּ אָמֵר, (ויקרא כ״ב:ז׳) וּבָא הַשֶּׁמֶשׁ וְטָהֵר, וְאַחַר יֹאכַל מִן הַקֳּדָשִׁים.</p>\n<p>תָּא חֲזֵי, כָּל חוֹבֵי עָלְמָא, קוּדְשָׁא בְּרִיךְ הוּא מְכַפֵּר עָלַיְיהוּ, בִּתְשׁוּבָה, בַּר מֵהַהוּא לִישָׁנָא בִּישָׁא, דְּאַפִּיק שׁוּם בִּישׁ עַל חַבְרֵיהּ. וְהָא אוּקְמוּהָ, דִּכְתִּיב, זֹאת תִּהְיֶה תּוֹרַת הַמְּצוֹרָע, זֹאת הִיא תּוֹרָתוֹ שֶׁל מוֹצִיא שֵׁם רָע. רִבִּי חִיָּיא אָמַר, כָּל מַאן דְּאַפִּיק לִישָׁנָא בִּישָׁא, אִסְתַּאֲבָן לֵיהּ כָּל שַׁיְיפוֹי, וְיִתְחֲזֵי לְסַגְרָא, בְּגִין דְּהַהִיא מִלָּה בִּישָׁא סַלְּקָא וְאִתְּעַר רוּחָא מִסְאֲבָא עֲלוֹי וְאִסְתְּאַב, אָתֵי לְאִסְתַּאֲבָא מְסָאֲבִין לֵיהּ, בְּמִלָּה דִּלְתַתָּא אִתְּעַר מִלָּה אָחֳרָא.</p>\n<p>פָּתַח וְאָמַר, (ישעיהו א׳:כ״א) אֵיכָה הָיְתָה לְזוֹנָה קִרְיָה נֶאֱמָנָה וְגוֹ'. מַאן דַּהֲוַת מְהֵימָנָא לְבַעְלָהּ, אַהֲדְרַת לְזוֹנָה. מְלֵאֲתִי מִשְׁפָּט, מִשְׁפָּט, וַדַּאי דָּא קוּדְשָׁא בְּרִיךְ הוּא, צֶדֶק, דָּא כְּנֶסֶת יִשְׂרָאֵל, וּבְגִין דְּאַתְּעָרַת מִלָּה אָחֳרָא, אִסְתְּלַּק מִנָּהּ קוּדְשָׁא בְּרִיךְ הוּא, וְשַׁרְיָא בָּהּ רוּחָא דְּקַטוּלֵי. הֲדָא הוּא דִכְתִיב וְעַתָּה מְרַצְחִים. וּמַה יְרוּשָׁלַם קַרְתָּא קַדִּישָׁא כַּךְ, שְׁאָר בְּנֵי נָשָׁא עַל אַחַת כַּמָּה וְכַמָּה. הֲדָא הוּא דִכְתִיב, זֹאת תִּהְיֶה תּוֹרַת הַמְּצוֹרָע.</p>\n<p>רִבִּי יְהוּדָה אָמַר, זֹאת תִּהְיֶה וַדַּאי לָקֳבְלֵיהּ לְאִתְפָּרְעָא מִנֵּיהּ, דְּהַהוּא מוֹצִיא שֵׁם רָע, בְּיוֹם טָהֳרָתוֹ וְהוּבָא אֶל הַכֹּהֵן, מַאי קָא מַשְׁמַע לָן. מַשְׁמַע, מַאן דְּאִית לֵיהּ לִישָׁנָא בִּישָׁא צְלוֹתֵיהּ לָא עָאלַת קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּהָא אִתְּעַר עָלֵיהּ רוּחָא מִסְאֲבָא. כֵּיוָן דְּאָהֲדָר בִּתְשׁוּבָה וְקַבִּיל עָלֵיהּ תְּשׁוּבָה, מַה כְּתִיב, בְּיוֹם טָהֳרָתוֹ וְהוּבָא אֶל הַכֹּהֵן וְגוֹ' וְרָאָה הַכֹּהֵן וְגוֹ'.</p>\n<p>(ויקרא י״ד:ד׳) וְצִוָּה הַכֹּהֵן וְלָקַח לַמִּטַּהֵר שְׁתֵּי צִפֳּרִים חַיּוֹת. רִבִּי יִצְחָק וְרִבִּי יוֹסֵי הֲווֹ שְׁכִיחֵי קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן. יוֹמָא חַד אָמַר לֵיהּ, עֵץ אֶרֶז הָא יְדִיעַ, כְּמָה דְאַתְּ אָמֵר, (מלכים א ה׳:י״ג) מִן הָאֶרֶז אֲשֶׁר בַּלְּבָנוֹן, דְּהָא הַהוּא עֵץ אֶרֶז, לָא אִשְׁתָּרְשָׁן נְטִיעוֹי אֶלָּא בַּלְּבָנוֹן, וְהָא אִתְּמַר. אֵזוֹב לָמָּה, וּמַאי הוּא.</p>\n<p>פָּתַח וְאָמַר, וְלָקַח לַמִּטַּהֵר שְׁתֵּי צִפֳּרִים חַיּוֹת טְהוֹרוֹת וְעֵץ אֶרֶז וּשְׁנִי תּוֹלַעַת <Nonei></i>וְאֵזוֹב. תָּא חֲזֵי, בַּר נָשׁ דְּמִשְׁתַּדֵּל בְּפוּלְחָנָא דְּמָארֵיהּ, וְאִשְׁתְּדַּל בְּאוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא שָׁארֵי עֲלוֹי וּשְׁכִינְתָּא אִשְׁתַּתְּפָא בַּהֲדֵיהּ. כֵּיוָן דְּבַּר נָשׁ אָתֵי לְאִסְתַּאֲבָא, שְׁכִינְתָּא אִסְתָּלָקַת מִנֵּיהּ, קוּדְשָׁא בְּרִיךְ הוּא אִתְרְחִיק מִנֵּיהּ, וְכָל סִטְרָא דִּקְדוּשָּׁה דְּמָארֵיהּ מְרַחֲקִין מִנֵיהּ, וְשָׁארִי עָלֵיהּ רוּחַ מִסְאֲבָא וְכָל סִטְרָא דִּמְסָאֲבָא, אָתֵי לְאִתְדַכְּאָה מְסַיְּיעִין לֵיהּ. בָּתַר דְּאִתְדָכֵּי וְאַהְדָּר בִּתְשׁוּבָה, הַהוּא דְּאִסְתַּלָּק מִנֵּיהּ אַהְדָּר, וְשָׁארִי עֲלוֹי.</p>"],[9520012091,"<p>תָּא חֲזֵי, כְּתִיב וְלָקַח לַמִּטַּהֵר שְׁתֵּי צִפֳּרִים חַיּוֹת טְהוֹרוֹת. כֵּיוָן דְּאָמַר, שְׁתֵּי צִפֳּרִים, לָא יְדַעְנָא דְּאִינּוּן חַיוֹת, אֶלָּא, הָא אוּקְמוּהָ, אֲבָל חַיּוֹת, חַיּוֹת מַמָּשׁ. כְּמָה דְאַתְּ אָמֵר (יחזקאל א׳:ט״ו) וָאֵרֶא הַחַיּוֹת, לָקֳבֵל אֲתַר דְּיַנְקֵי מִנַּיְיהוּ נְבִיאֵי מְהֵימְנֵי, וְעֵץ אֶרֶז הָא אִתְּמַר, וּשְׁנִי תּוֹלַעַת, סְטָר סוּמָקָא דִּגְבוּרָה דְּאִשְׁתַּתֵּף בַּהֲדֵיהּ בְּקַדְמִיתָא. וְאֵזוֹב, דָּא ו' זְעֵירָא, דְּיָנִיק לֵיהּ לִכְּנֶסֶת יִשְׂרָאֵל, וּבְגִין כָּךְ, עֵץ אֶרֶז וְאֵזוֹב, אַזְלָן כַּחֲדָא, וְעַל דָּא ו' ו' כַּחֲדָא אִשְׁתְּכָחוּ, חַד עִלָּאָה, וְחַד זְעֵירָא, וְקַרְיָין לוֹן, ו' עִלָּאָה, ו' תַּתָּאָה. וְכֻלְּהוּ אָהַדְרוּ לְשַׁרְיָא עֲלוֹי בְּגִין דְּהָא אִתְדָּכֵי, לָקֳבֵל אִלֵּין, לְתַתָּא (מנייהו), עֵץ אֶרֶז וְאֵזוֹב וּשְׁנִי תּוֹלַעַת אִשְׁתְּכָחוּ (בשמא) בְּדַכְיוּתָא דָּא, וְתַּלְיָין מֵאִלֵּין עִלָּאִין.</p>"],[9520012092,"<p>רִבִּי יְהוּדָה וְרִבִּי יִצְחָק הֲווֹ אַזְלֵי בְּאָרְחָא. יָתְבוּ בְּהַהוּא בֵּי חַקְלָא וְצַלּוּ. בָּתַר דְּסִיְימוּ צְלוֹתָא קָמוּ וְאַזְלוּ. פָּתַח רִבִּי יְהוּדָה בְּמִלֵּי דְּאוֹרַיְיתָא. וְאָמַר, (משלי ג׳:י״ח) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ וְתוֹמְכֶיהָ מְאוּשָּׁר. עֵץ חַיִים, דָּא אוֹרַיְיתָא, דְּאִיהִי אִילָנָא עִלָּאָה רַבָּא וְתַקִּיף. תּוֹרָה, אֲמַאי אִקְרֵי תּוֹרָה. בְּגִין דְּאוֹרֵי וְגַלֵּי בְּמָה דְּהֲוָה סָתִים דְּלָא אִתְיְדַע. חַיִים, דְּכָל חַיִּים דִּלְעֵילָּא בָּהּ אִתְכְּלִילוּ, וּמִנָהּ נָפְקִין. לַמַּחֲזִיקִים בָּהּ, לְאִינּוּן דְּאַחְדִּין בָּהּ, דְּמַאן דְּאָחִיד בְּאוֹרַיְיתָא אָחִיד בְּכֹלָּא, אָחִיד לְעֵילָּא וְתַתָּא. וְתוֹמְכֶיהָ מְאוּשָּׁר, מַאן תּוֹמְכֶיהָ. אִלֵּין אִינּוּן דְּמַטִילִין מְלָאי, לְכִיסָן שֶׁל תַּלְמִידֵי חֲכָמִים, כְּמָה דְּאוּקְמוּהָ.</p>\n<p>וְתוֹמְכֶיהָ, זָכֵי לִנְבִיאֵי מְהֵימְנֵי דְּיִפְּקוּן מִנֵּיהּ. מְאוּשָּׁר, אַל תִּקְרֵי מְאוּשָּׁר, אֶלָּא מֵרֹאשׁוֹ, אִינּוּן תַּמְכִין לְאוֹרַיְיתָא, מֵרֹאשׁוֹ וְעַד סוֹפוֹ. מֵרֹאשׁוֹ, דָּא רֵישָׁא דְּכֹלָּא דְּאִקְרֵי רֹאשׁ, דִּכְתִּיב, (משלי ח׳:כ״ג) מֵעוֹלָם נִסַּכְתִּי מֵרֹאשׁ. וְרֹאשׁ דָּא חָכְמָה, דְּאִיהִי רֵישָׁא לְכָל גּוּפָא, וְגוּפָא אִתְפְּשָׁט בֵּיהּ עַד סִיּוּמָא דְּשִׁית סִטְרִין, וְתוֹמְכֶיהָ, כְּמָה דְאַתְּ אָמֵר, (שיר השירים ה׳:ט״ו) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ. דְּאִינּוּן דְּמַטִילִין מְלָאי לְכִיסָן שֶׁל תַּלְמִידֵי חֲכָמִים אִינּוּן תַּמְכִין לְאוֹרַיְיתָא מֵרֵישָׁא עַד סִיּוּמָא דְּגוּפָא, וְכָל מְהֵימְנוּתָא, בֵּיהּ תַּלְיָא, וְאִתְּמָךְ. וְזָכֵי לִבְנִין דְּיִתְחֲזוּן לִנְבִיאֵי מְהֵימְנֵי.</p>"],[9520012093,"<p>רִבִּי יִצְחָק פָּתַח, (ויקרא א׳:א׳) וַיִקְרָא אֶל מֹשֶׁה וַיְדַבֵּר יְיָ' אֵלָיו מֵאֹהֶל מוֹעֵד לֵאמֹר. וַיִקְרָא אָלֶף זְעֵירָא, אֲמַאי. אֶלָּא בְּגִין לְאַחֲזָאָה מַאן הוּא הַהוּא דְּקָרָא, הַהוּא דְּשָׁרֵי בְּמַקְדְּשָׁא, וּכְדֵין זַמִּין לְמֹשֶׁה, כְּמַאן דְּזַמִּין אוּשְׁפִּיזָא. הָכָא א' זְעֵירָא, הָתָם א' רַבְּתָא, אָדָם שֵׁת אֱנוֹשׁ. (ס\"א אדם) דָּא שְׁלִימוּ דְּכֹלָּא.</p>\n<p>תָּא חֲזֵי, מַה בֵּין מֹשֶׁה לְאַהֲרֹן, הֵי מִנַּיְיהוּ עִלָּאָה. אֶלָּא מֹשֶׁה עִלָּאָה, מֹשֶׁה שׁוּשְׁבִינָא דְּמַלְכָּא, אַהֲרֹן שׁוּשְׁבִינָא דְּמַטְרוֹנִיתָא. מְתַל לְמַלְכָּא דְּהֲוָה לֵיהּ מַטְרוֹנִיתָא עִלָּאָה. מָה עֲבַד. יָהַב לָהּ שׁוּשְׁבִינָא לְתַקְּנָא לָהּ וּלְאִסְתַּכְּלָא בְּמִלֵּי דְּבֵיתָא. וְעַל דָּא, כַּד עַיִּיל שׁוּשְׁבִינָא דָּא לְמַלְכָּא, לָא עַיִּיל אֶלָּא עִם מַטְרוֹנִיתָא, הֲדָא הוּא דִכְתִיב, בְּזֹאת יָבֹא אַהֲרֹן וְגוֹ'.</p>\n<p>מֹשֶׁה שׁוּשְׁבִינָא לְמַלְכָּא, בְּגִין כָּךְ אִזְדָּמַן כְּאוּשְׁפִּיזָא, וּלְבָתַר, וַיְדַבֵּר יְיָ' אֵלָיו. אַהֲרֹן הוּא שׁוּשְׁבִינָא לְמַטְרוֹנִיתָא, וְכָל מִלּוֹי הֲווֹ, לְפַיְּיסָא לְמַלְכָּא בְּמַטְרוֹנִיתָא, וְיִתְפְּיָיס מַלְכָּא בַּהֲדָהּ. וְעַל דָּא בְּגִין דְּאִיהוּ, שׁוּשְׁבִינָא לָהּ שַׁוִּי מָדוֹרֵיהּ בַּהֲדָהּ, לְתַקְּנָא בֵּיתָא וּלְעַיְינָא תָּדִיר בְּמִלֵּי דְּבֵיתָא. וְעַל דָּא אִתְתְּקַּן כְּגַוְונָא דִּלְעֵילָּא, וְאִקְרֵי כֹּהֵן גָּדוֹל. מְנָא לָן. דִּכְתִּיב, (תהילים ק״י:ד׳) אַתָּה כֹהֵן לְעוֹלָם עַל דִּבְרָתִי מַלְכִּי צֶדֶק.</p>\n<p>וּבְגִין כָּךְ כָּל מַה דְּאִצְטְרִיךְ מִבֵּי מַלְכָּא, נָטִיל, וְלֵית מַאן דְּיִמְחֵי בִּידֵיהּ. וְעַל דָּא הוּא קָאִים לְדַכְּאָה לְכָל אִינּוּן דְּעָאלִין לְבֵי מַטְרוֹנִיתָא, בְּגִין דְּלָא <Nonei></i>יִשְׁתְּכַּח מִסְאֲבָא בְּאִינּוּן בְּנֵי הֵיכָלָא. וּבְגִין כָּךְ כְּתִיב, וְלָקַח לַמִּטַּהֵר שְׁתֵּי צִפֳּרִים וְגוֹ'.</p>\n<p>רִבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים ב׳:ד׳) יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק יְיָ' יִלְעַג לָמוֹ. יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק, דָּא יִצְחָק דְּאָתֵי מִסִּטְרָא דְּחַמְרָא, נָהִיר בְּקַדְמִיתָא, וְחַיִיךְ, וּלְבָתַר זָעִים וְתָרִיךְ. הֲדָא הוּא דִכְתִיב יוֹשֵׁב בַּשָּׁמַיִם וְלָא כְּתִיב, יוֹשֵׁב שָׁמַיִם. יִשְׂחָק, נָהִיר וְחַיִיךְ. וְעַל דָּא דִּינָא נָהִיר וְחַיִיךְ, לְהוּ לְרַשִׁיעַיָּיא.</p>\n<p>וּלְבָתַר מַה כְּתִיב, אָז יְדַבֵּר אֵלֵימוֹ בְאַפּוֹ וּבַחֲרוֹנוֹ יְבַהַלֵמוֹ. וְכַךְ אָרְחֵי דְּחַיָּיבַיָּא, קוּדְשָׁא בְּרִיךְ הוּא נָהִיר לְהוּ בְּהַאי עָלְמָא, וְנָהִיר לוֹן אַנְפִּין כְּחַמְרָא, דְּנָהִיר בְּקַדְמִיתָא, וּלְבָתַר זָעִים וְקָטִיל. וְקוּדְשָׁא בְּרִיךְ הוּא מָשִׁיךְ לוֹן לְחַיָּיבַיָּא, אִי יְהַדְרוּן לָקֳבְלֵיהּ, יָאוּת, וְאִי לָא שָׁצֵי לוֹן מֵהַהוּא עָלְמָא דְּאָתֵי, וְלֵית לוֹן בֵּיהּ חוּלָקָא, וְיִשְׁתֵּצוּן מִכֹּלָּא. אַתּוּן לְאִתְדַכְּאָה, מְסַיְּיעִין לוֹן. וְקוּדְשָׁא בְּרִיךְ הוּא מְדַכֵּי לוֹן וְקָרִיב לוֹן לְגַבֵּיהּ, וְקָארִי עָלַיְיהוּ שָׁלוֹם. הֲדָא הוּא דִּכְתִּיב (ישעיהו נ״ז:י״ט) שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב וְגוֹ'.</p>"],[9520012094,"<p>(ויקרא ט\"ז) וְאִשָּׁה כִּי יָזוּב זוֹב דָּמָהּ יָמִים רַבִּים בְּלֹא עֶת נִדָּתָהּ וְגוֹ'. רִבִּי חִיָּיא פָּתַח וְאָמַר, (זכריה י״ד:א׳) הִנֵּה יוֹם בָּא לַיְיָ' וְחֻלַּק שְׁלָלֵךְ בְּקִרְבֵּךְ. הַאי קְרָא הָכִי מִבָּעֵי לֵיהּ, הִנֵּה יוֹם יָבֹא, מַאי, הִנֵּה יוֹם בָּא. אֶלָּא שֶׁכְּבָר בָּא, עַד לָא אִבְרֵי עָלְמָא, וְהוּא יוֹם דְּבֵיהּ יַעְבִיד דִּינָא לְחַיָּיבַיָּא. וְהוּא יוֹם דְּבֵיהּ יִתְפְּרַע קוּדְשָׁא בְּרִיךְ הוּא מֵאִינּוּן דְּעָקוּן לוֹן לְיִשְׂרָאֵל. הַאי יוֹם בָּא וְקָאִים קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְתָבַע מִנֵּיהּ לְמֶעְבַּד דִּינָא וּלְשֵׁצָאָה עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְאִתְיְהִיב לֵיהּ רְשׁוּ, כְּמָה דְאַתְּ אָמֵר (זכריה י״ד:ב׳) וְאָסַפְתִּי אֶת כָּל הַגּוֹיִם אֶל יְרוּשָׁלַם לַמִּלְחָמָה וְגוֹ'.</p>\n<p>רִבִּי יִצְחָק אָמַר, תְּרֵין יוֹמִין אִינּוּן לְּקוּדְשָׁא בְּרִיךְ הוּא, חַד שָׁארֵי עִמֵּיהּ, וְחַד אָתֵי לְקַמֵּיהּ, וּבְאִלֵּין עָבִיד קוּדְשָׁא בְּרִיךְ הוּא קְרָבִין בְּכֹלָּא. וְכַד הַאי יוֹמָא, אָתֵי לְאַגָּחָא קְרָבָא, אִזְדְּוַּוג בְּהַהוּא יוֹמָא אָחֳרָא, וְנָטִיל זַיְינִין עַל זַיְינֵיהּ, וְאָגַח קְרָבָא בְּכֹלָּא, בְּאִינּוּן רָאמִין וּנְמוּכִין. הֲדָא הוּא דִכְתִיב, (ישעיהו ב׳:י״ב) כִּי יוֹם לַיְיָ' צְבָאוֹת, עַל כָּל גֵּאֶה וָרָם וְעַל כָּל נִשָּׂא וְשָׁפֵל.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, וְאִשָּׁה כִּי יָזוּב זוֹב דָּמָהּ וְגוֹ'. הַיְינוּ דִּכְתִּיב, (ישעיהו ל״ד:ו׳) חֶרֶב לַיְיָ' מָלְאָה דָם. מָלְאָה דָם וַדַּאי, דִּכְתִּיב כִּי יָזוּב זוֹב דָּמָהּ יָמִים רַבִּים. בְּלֹא עֶת נִדָּתָהּ, הַיְינוּ דִּכְתִּיב, (דניאל ט׳:י״ד) וַיּשְׁקוֹד יְיָ' עַל הָרָעָה וַיְבִיאֶהָ עָלֵינוּ. דְּתָנֵינָן, קוּדְשָׁא בְּרִיךְ הוּא אַקְדִּים פּוּרְעָנוּתָא לְעָלְמָא, חַיָּיבַיָּא מְקַדְּמִין פּוּרְעָנוּתָא בְּחוֹבֵיהוֹן לְמֵיתֵי לְעָלְמָא, אוֹ כִי תָזוּב עַל נִדָּתָהּ. הַיְינוּ (ויקרא כ״ו:י״ח) וְיָסַפְתִּי לְיַסְּרָה אֶתְכֶם, מַהוּ וְיָסַפְתִּי לְיַסְּרָה. אוֹסִיף דִּינָא עַל דִּינָא, וְאֶתֵּן דָּמָא עַל דָּמָא, יַתִּיר עַל מַה דְּאִית בְּהַהוּא חֶרֶב לַיְיָ' מָלְאָה דָם.</p>\n<p>כְּתִיב, (בראשית ח׳:כ״א) לֹא אוֹסִיף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם. מַהוּ לֹא אוֹסִיף. אֶלָּא, לָא אֶתֵּן עוֹד תּוֹסֶפֶת לְהַהוּא חֶרֶב, אֶלָּא כְּגַוְונָא דְּיָכִיל עָלְמָא לְמִסְבַּל. וְהָא כְּתִיב וְיָסַפְתִּי. אֶלָּא לְיַסְּרָה כְּתִיב, וְלָא לְשֵׁיצָאָה. הֲדָא הוּא דִכְתִיב, אוֹ כִּי תָזוּב עַל נִדָּתָהּ.</p>\n<p>כָּל יְמֵי זוֹב טוּמְאָתָהּ. מַהוּ כָּל יְמֵי זוֹב טוּמְאָתָהּ. אֶלָּא חַיָּיבַיָּא מְסָאֲבִין בְּחוֹבֵיהוֹן לְגַרְמֵיהוֹן, וּמְסָאֲבִין לַאֲתַר אָחֳרָא, כְּמָה דְאַתְּ אָמֵר, (במדבר י״ט:כ׳) כִּי אֶת מִקְדַּשׁ יְיָ' טִמֵּא. וְאִתְּעַר רוּחַ מִסְאֲבָא עָלַיְיהוּ. וּלְזִמְנָא דְּאָתֵי, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְדַכְּאָה לְהוּ לְיִשְׂרָאֵל וּלְאַעְבְּרָא לְהַהוּא רוּחָא מִסְאֲבָא מֵעָלְמָא. דִּכְתִּיב, (ישעיהו נ״ב:א׳) לֹא יוֹסִיף יָבֹא בָךְ עוֹד עָרֵל וְטָמֵא. וּכְתִיב (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטּוּמְאָה אַעֲבִיר מִן הָאָרֶץ. מִן הָאָרֶץ וַדַּאי. (מאן דאתי לאסתאבא מסאבין ליה ודאי)</p>"],[9520012095,"<p>רִבִּי חִזְקִיָּה הֲוָה יָתִיב קַמֵּיהּ דְּרִבִּי אֶלְעָזָר, לֵילְיָא חַד קָמוּ בְּפַלְגוּת לֵילְיָא לְמִלְעֵי בְּאוֹרַיְיתָא. פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (קהלת ז׳:י״ד) בְּיוֹם טוֹבָה הֱיֵה בְטוֹב וְגוֹ' גַּם אֶת זֶה לְעוּמַּת זֶה עָשָׂה הָאֱלֹהִים וְגוֹ'. בְּיוֹם טוֹבָה הֱיֵה בְטוֹב, בְּזִמְנָא דְּאַסְגֵּי קוּדְשָׁא בְּרִיךְ הוּא חֶסֶד בְּעָלְמָא, בָּעֵי בַּר נָשׁ לְמֵיהַךְ בְּשׁוּקֵי וּלְאִתְחֲזָאָה קָמֵי כֹּלָּא, דְּהָא כַּד שָׁארֵי טִיבוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּעָלְמָא, בְּכֹלָּא שָׁארֵי, וּבְכֹלָּא עָבִיד טִיבוּ וְאַסְגֵּי לֵיהּ בְּעָלְמָא. וּבְגִין כָּךְ, יִתְחֲזֵי בַּר נָשׁ בְּאִתְגַּלְיָא בְּשׁוּקֵי, וְיַעְבִיד טִיבוּ דְּלִשְׁרֵי עָלֵיהּ טִיבוּ אָחֳרָא. הֲדָא הוּא דִּכְתִּיב בְּיוֹם טוֹבָה הֱיֵה בְטוֹב. הֱיֵה בְטוֹב וַדַּאי.</p>\n<p>וּבְיוֹם רָעָה רְאֵה. לָא כְּתִיב וּבְיּוֹם רָעָה הֱיֵה בְּרָע, אֶלָּא, בְּיוֹם רָעָה רְאֵה. דְּהָא בְּשַׁעֲתָא דְּדִינָא תַּלְיָא בְּעָלְמָא, לָא לִבְעֵי לֵיהּ לֶאֱינִישׁ לְאִתְחֲזָאָה בְּשׁוּקָא <Nonei></i>וּלְמֵיהַךְ יְחִידָאָה בְּעָלְמָא. דְּהָא כַּד דִּינָא שַׁרְיָא בְּעָלְמָא, עַל כֹּלָּא שָׁארֵי. וּמַאן דְּפָגַע בֵּיהּ, וְאַעְרַע קַמֵּיהּ, יִתְדָּן בְּהַהוּא דִּינָא. וּכְדֵין כְּתִיב, (משלי י״ג:כ״ג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. דְּהָא מִשְׁפָּט אִסְתַּלָּק מִצֶדֶק, וְלָא שַׁרְיָין דָּא בְּדָא עַל עָלְמָא. וְעַל דָּא רְאֵה. רְאֵה וַהֲוִי נָטִיר, אַשְׁגַּח וְעַיֵין לְכָל סְטָר. וַהֲוִי יָדַע, דִּבְכֻלְּהוּ שַׁרְיָא דִּינָא, וְלָא תִּפּוּק לְבַר, וְלָא תִּתְחֲזֵי בְּשׁוּקָא, בְּגִין דְּלָא יִשְׁרֵי עֲלָךְ. מַאי טַעְמָא. בְּגִין דְּגַם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים. כַּמָה דְּכַד שָׁארֵי טִיבוּ בְּעָלְמָא שָׁארֵי עַל כֹּלָּא, כַּךְ, כַּד שַׁרְיָא דִּינָא בְּעָלְמָא שָׁארֵי עַל כֹּלָּא, וּמַאן דְּאִעְרַע בֵּיהּ אִתְפַּס.</p>\n<p>תָּא חֲזֵי, כַּד דִּינָא שַׁרְיָא בְּעָלְמָא, כַּמָה סַיְיפִין תַּלְיָין, דְּנַפְקֵי מֵהַהוּא חֶרֶב עִלָּאָה, וְזַקְפִין רֵישָׁא וְחָמָן דְּהָא הַהוּא חֶרֶב עִלָּאָה סוּמָקָא, מַלְיָיא דָּמָא בְּכָל סִטְרִין, כְּדֵין גַּזְרִין נִימוּסִין. וְכַמָּה סַיְיפַיָּא אִתְּעֲרוּ, (ס\"א כדין פסירן סייפין, וכמה נימוסין אתערו) כְּמָה דְאַתְּ אָמֵר, (שיר השירים ג׳:ח׳) אִישׁ חַרְבּוֹ עַל יְרֵכוֹ. וּכְתִיב, (יהושע ה׳:י״ג) וְחַרְבּוֹ שְׁלוּפָה בְּיָדוֹ. וְכֻלְּהוּ מִשְׁתַּכְּחֵי לְמֶעְבַּד דִּינָא. וּמַאן דְּיִעְרַע בְּהוּ אִתְּזָק. כְּתִיב, (בראשית י״ט:י״ט) הִנֵה נָא מָצָא עַבְדְּךָ חֵן בְּעֵינֶיךָ וַתַּגְדֵּל חַסְדְּךָ וְגוֹ'. מַאי טַעְמָא, בְּגִין דִּבְכָל אֲתַר דְּדִינָא שַׁרְיָא בְּכֹלָּא שַׁרְיָא, בֵּין בְּמָתָא בֵּין בְּמַדְבְּרָא וּבְסָחֲרָנָא דְּמָתָא.</p>"],[9520012096,"<p>תּוּ פָּתַח וְאָמַר, (שיר השירים ח׳:ו׳) שִׂימֵנִי כַחוֹתָם עַל לִבֶּךָ וְגוֹ'. שִׂימֵנִי כַחוֹתָם, כְּנֶסֶת יִשְׂרָאֵל אָמְרָה דָּא לְּקוּדְשָׁא בְּרִיךְ הוּא. שִׂימֵנִי כַחוֹתָם, מַאן הוּא חוֹתָם. דָּא חוֹתָם דְּגוּשְׁפַּנְקָא דִּקְשׁוֹט. כַחוֹתָם עַל לִבֶּךָ, דָּא חוֹתָם שֶׁל תְּפִלִּין, דְּאָנַח בַּר נָשׁ עַל לִבֵּיהּ. כַּחוֹתָם עַל זְרוֹעֶךָ, דָּא יַד כֵּהָה, דְּמָנַח בְּהַהוּא זְרוֹעַ, וּמַנוּ יִצְחָק. וּכְּנֶסֶת יִשְׂרָאֵל קָאָמַר שִׂימֵנִי כַּחוֹתָם, חוֹתָם מִבָּעֵי לֵיהּ, מַאי כַּחוֹתָם. כְּאִינּוּן תְּפִלִּין דְּרֵישָׁא, דְּאָתֵי שְׁבָחָא לְכָל גּוּפָא. וְעַל דָּא תְּפִלִין בַּזְּרוֹעַ, עַל הַלֵּב, וּבְדָא אִשְׁתְּכַח בַּר נָשׁ שְׁלִים כְּגַוְונָא דִּלְעֵילָּא.</p>\n<p>כִּי עַזָּה כַמָּוְת אַהֲבָה. מַאי כִּי עַזָּה כַמָּוְת. אֶלָּא לָא אִשְׁתְּכַח קַשְׁיוּתָא בְּעָלְמָא, כְּמָה דִּפְרִישׁוּ דְּנַפְשָׁא מִגּוּפָא, כַּד בַּעְיָין לְאִתְפָּרְשָׁא. (ועל דא) כַּךְ אַהֲבַת כְּנֶסֶת יִשְׂרָאֵל לְּקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא אִתְפָּרְשָׁן לְעָלְמִין. וּבְגִין כָּךְ תְּפִלָּה שֶׁל יַד, אִתְקַשְּׁרָא בִּזְרוֹעַ, לְקַיְּימָא דִּכְתִּיב, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי.</p>\n<p>קָשָׁה כִשְׁאוֹל קִנְאָה. בְּכָל דַּרְגִּין דְּגֵיהִנָּם, לָא אִית קַשְׁיָא כִּשְׁאוֹל, דְּנָחִית לְתַתָּא מִנַּיְיהוּ, בַּר הַהוּא דַּרְגָּא דְּאִקְרֵי אֲבַדּוֹן, וְדָא וְדָא אִשְׁתָּתָּפוּ כַּחֲדָא. וְדָא קַשְׁיָא לְהוּ לְחַיָּיבַיָּא מִכֹּלָּא. כַּךְ, קָשָׁה כִשְׁאוֹל קִנְאָה, דְּלֵית קִנְאָה אֶלָּא בִּרְחִימוּתָא, וּמִגּוֹ רְחִימוּתָא אָתֵי קִנְאָה, וּמַאן דְּקַנֵּי לְהַהוּא דְּרָחִים (ויחי קע\"ה ע\"א) יַתִּיר, קַשְׁיָא לֵיהּ לְאִתְפָּרְשָׁא מִנֵּיהּ מֵהַהוּא דַּרְגָּא דְּאִקְרֵי שְׁאוֹל, דְּאִיהוּ קַשְׁיָא מִכָּל דַּרְגִּין דְּגֵיהִנָּם.</p>\n<p>רְשָׁפֶיהָ רִשְׁפֵי אֵשׁ שַׁלְהֶבֶת יָהּ. וּמַאן אִיהוּ שַׁלְהֶבֶת יָהּ, דָּא אֶשָּׁא דְּנָפִיק מִגּוֹ שׁוֹפָר, כָּלִיל מֵרוּחָא וּמַיָא. וּמִגּוֹ הַהוּא שַׁלְהוֹבָא כַּד מִתְלַהֲטָא בִּכְּנֶסֶת יִשְׂרָאֵל, אוֹקִיד עָלְמָא בְּשַׁלְהֹבוּתָא בְּקִנְאָה דְּקוּדְשָׁא בְּרִיךְ הוּא, וּבְשַׁעֲתָא דְּהִיא מְקַנְּאָה לֵיהּ, וַוי דְּאַעְרַע בְּשַׁלְהוֹבִיתָא, דְּאִיהוּ יִתּוֹקַד בְּהוּ.</p>"],[9520012097,"<p>תּוּ פָּתַח וְאָמַר. (שיר השירים ח׳:ז׳) מַיִם רַבִּים לֹא יוּכְלוּ לְכַבּוֹת וְגוֹ'. מַיִם רַבִּים דָּא דְּרוֹעָא יְמִינָא, דְּבָעֵי לְקַשְּׁרָא בֵּיהּ קִשְׁרָא דִּתְפִלָּה עַל דְּרוֹעָא שְׂמָאלָא, לְקַיְּימָא וִימִינוֹ תְּחַבְּקֵנִי. דָּבָר אַחֵר, מַיִם רַבִּים, דָּא הוּא נָהָר עִלָּאָה, דְּמִנֵּיהּ נָפְקִין נַהֲרִין לְכָל עִבָר, וְכֻלְּהוּ נַגְדִּין וְאִתְמַשְּׁכָן מִנֵּיהּ. כְּמָה דְאַתְּ אָמֵר, (תהילים צ״ג:ד׳) מִקּוֹלוֹת מַיִם רַבִּים. מֵאִינּוּן קוֹלוֹת דְּמַיִם רַבִּים, דְּנַפְקָן וְאִתְמַשְּׁכָן מִנֵּיהּ. וּנְהָרוֹת, כְּמָה דְאַתְּ אָמֵר, נָשְׂאוּ נְהָרוֹת וְגוֹ'.</p>\n<p>אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בָּאַהֲבָה, דְּרָחִים כְּנֶסֶת יִשְׂרָאֵל לְקוּדְשָׁא בְּרִיךְ הוּא, יָבוּזוּ לוֹ. (שיר השירים ח׳:ז׳) בּוֹז יָבוּזוּ לוֹ, יָבוּז מִבָּעֵי לֵיהּ, מַאי יָבוּזוּ לוֹ. אֶלָּא, אִם יִתֵּן אִישׁ, דָּא קוּדְשָׁא בְּרִיךְ הוּא. אֶת כָּל הוֹן בֵּיתוֹ, כְּמָה דְאַתְּ אָמֵר (משלי כ״ד:ד׳) כָּל הוֹן יָקָר וְנָעִים. בְּאַהֲבָה, דְּכְּנֶסֶת יִשְׂרָאֵל לְגַבֵּיהּ, וְלָא לְאִתְקַשְּׁרָא בַּהֲדָהּ, בּוֹז יָבוּזוּ לוֹ, כָּל אִינּוּן <Nonei></i>אוּכְלוּסִין וְכָל אִינּוּן מַשִׁרְיָין דִּלְעֵילָּא, לְהַהוּא הוֹן יָקָר, דְּהָא לֵית רְעוּתָא לְכֻלְּהוּ אֶלָּא בְּשַׁעֲתָא דְּכְּנֶסֶת יִשְׂרָאֵל מִתְקַשְּׁרָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וּמִתְעַטְּרָא בַּהֲדֵיהּ, כְּדֵין כָּל אִינּוּן אוּכְלוּסִין, וְכָל אִינּוּן מַשִׁרְיָין, וְכֻלְּהוּ עָלְמִין כֻּלְּהוּ בְּחֵדוּ, בִּנְהִירוּ, בְּבִרְכָּאן, (על דא אמר) כְּתִיב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. מַאן דְּאָנַח תְּפִלִּין, כַּד מָנַח תְּפִלָּה שֶׁל יַד, בָּעֵי לְאוֹשָטָא דְּרוֹעָא שְׂמָאלָא, לְקַבְּלָא לָהּ לִכְּנֶסֶת יִשְׂרָאֵל, וּלְקַשְּׁרָא קִשְׁרָא עִם יְמִינָא, בְּגִין לְחַבְּקָא לָהּ, לְקַיְּימָא דִּכְתִּיב, שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. לְאִתְחֲזָאָה בַּר נָשׁ כְּגַוְונָא דִּלְעֵילָּא, וּלְאִתְעַטְּרָא בְּכֹלָּא, וּכְדֵין בַּר נָשׁ שְׁלִים בְּכֹלָּא, בִּקְדוּשָּׁה עִלָּאָה. וְקוּדְשָׁא בְּרִיךְ הוּא קָארֵי עָלֵיהּ, (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.</p>\n<p><Noneb>תוספתא</b> בּוֹז יָבוּזוּ לוֹ. מַאי בּוֹז. יוֹמָא תִּנְיָינָא וְיוֹמָא שְׁתִּיתָאָה וְיוֹמָא שְׁבִיעָאָה דְּסוּכּוֹת, דִּבְהוֹן הֲווֹ מְנַסְּכֵי מַיִם וְיַיִן. דְּז' יוֹמִין דְּסוּכּוֹת, בְּהוֹן הֲווֹ מַקְרִיבִין יִשְׂרָאֵל, ע' פָּרִים, לְכַפְּרָא עַל שִׁבְעִין מְמָנָן, בְּגִין דְּלָא יִשְׁתְּאַר עָלְמָא חָרוּב מִנַּיְיהוּ, הֲדָא הוּא דִכְתִיב, (במדבר כ״ט:י״ב) וּבַחֲמִשָּׁה עָשָׂר יוֹם וְגוֹ' וְהִקְרַבְתֶּם עוֹלָה אִשֵּׁה וְגוֹ'. (ע\"כ תוספתא)</p>"],[9520012098,"<p>רִבִּי חִזְקִיָּה פָּתַח וְאָמַר, (תהלים יז) שִׁמְעָה יְיָ' צֶדֶק וְגוֹ'. כַּמָה חֲבִיבָה כְּנֶסֶת יִשְׂרָאֵל קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, דִּבְכָל זִמְנָא דְּכְּנֶסֶת יִשְׂרָאֵל, אָתַת לְקָמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, קוּדְשָׁא בְּרִיךְ הוּא אִזְדְּמַן לָקֳבְלָהּ. הֲדָא הוּא דִכְתִיב שִׁמְעָה יְיָ' צֶדֶק הַקְשִׁיבָה רִנָּתִי הַאֲזִינָה תְפִלָּתִי. אָמַר דָּוִד, אֲנָא אִתְקָטַּרְנָא בִּכְּנֶסֶת יִשְׂרָאֵל. כְּמָה דְּהִיא אִשְׁתְּכַחַת לְקַמָּךְ, אֲנָא נָמֵי הָכִי אִשְׁתֵּכַחְנָא. וּבְגִין כַּךְ שִׁמְעָה יְיָ' צֶדֶק, בְּקַדְמִיתָא, וּלְבָתַר, הַקְשִׁיבָה רִנָּתִי הַאֲזִינָה תְפִלָּתִי.</p>\n<p>בְּלֹא שִׂפְתֵי מִרְמָה. מַאי בְּלָא שִׂפְתֵי מִרְמָה. אֶלָּא הָכִי תָּנֵינָן. כָּל מִלָּה וּמִלָּה דִּצְלוֹתָא, דְּאַפִּיק בַּר נָשׁ מִפּוּמֵיהּ, סַלְקָא לְעֵילָּא וּבַקְעָא רְקִיעִין, וְעָאלַת לַאֲתַר דְּעָאלָת, תַּמָּן אִתְבְּחָנַת הַהִיא מִלָּה, אִי הִיא מִלָּה דְּכַשְׁרָא אִי לָא, אִי אִיהִי מִלָּה דְּכַשְׁרָא עָאלִין לָהּ קָמֵי מַלְכָּא קַדִּישָׁא לְמֶעְבַּד רְעוּתָהּ. וְאִי לָאו, סָאטִין לָהּ לְבַר, וְאִתְעַר בְּהַהִיא מִלָּה רוּחָא אָחֳרָא.</p>\n<p>וְתָּא חֲזֵי, כְּתִיב בֵּיהּ בְּיוֹסֵף, (תהילים ק״ה:י״ט) עִנּוּ בַכֶּבֶל רַגְלוֹ וְגוֹ'. עַד אֵימָתַי, עִנּוּ בַכֶּבֶל רַגְלוֹ. עַד עֵת בֹּא דְּבָרוֹ אִמְרַת יְיָ' צְרָפָתְהוּ. עַד עֵת בֹּא דְּבָרוֹ דְּמַאן. אֶלָּא עַד עֵת בֹּא דְּבָרוֹ (דיוסף, ואתבחין) הַהִיא מִלָּה, הֲדָא הוּא דִכְתִיב, אִמְרַת יְיָ' צְרָפָתְהוּ. כְּדֵין, שַׁלַּח מֶלֶךְ וַיַּתִּירֵהוּ מוֹשֵׁל עַמִּים וַיְפַתְּחֵהוּ. אַדְּהָכִי הֲוָה אָתָא צַפְרָא.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, כְּתִיב, (שמואל א כ״ה:כ״ט) וְהָיְתָה נֶפֶשׁ אֲדוֹנִי צְרוּרָה בִּצְרוֹר הַחַיִּים. נֶפֶשׁ אֲדֹנִי, סְתָם. כְּמָה דְאַתְּ אָמֵר, (תהילים כ״ד:ד׳) אֲשֶׁר לֹא נָשָׂא לַשָׁוְא נַפְשִׁי, הָא עִידָנָא בְּצַפְרָא לְאִתְקַשְּׁרָא כְּנֶסֶת יִשְׂרָאֵל וּלְאִתְחַבְּרָא בְּבַעְלָהּ, זַכָּאִין אִינּוּן צַדִּיקַיָּא דְּמִשְׁתַּדְּלִין בְּאוֹרַיְיתָא בְּלֵילְיָא, וְאָתָאן לְאִתְקַשְּׁרָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא וּבִּכְּנֶסֶת יִשְׂרָאֵל. עָלַיְיהוּ כְּתִיב, (משלי כ״ג:כ״ה) יִשְׂמַח אָבִיךָ וְאִמֶךָ וְתָגֵל יוֹלַדְתֶּךָ.</p>"],[9520012099,"<p>אָמַר רִבִּי אֶלְעָזָר כְּתִיב, (ויקרא ט״ו:ל״א) וְהִזַּרְתֶּם אֶת בְּנֵי יִשְׂרָאֵל מִטּוּמְאָתָם וְגוֹ' בְּטַמְּאָם אֶת מִשְׁכָּנִי אֲשֶׁר בְּתוֹכָם. וְהִזַּרְתֶּם, כְּהַאי זָר, דְּאִיהוּ זָר מְכֻּלְּהוּ, וְלָא אִתְחַבָּר בְּמָה דְּלֵיתֵיהּ דִּילֵיהּ.</p>\n<p>וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּמִסְתַּאֲבִין בְּנֵי נָשָׁא לְתַתָּא, מִסְאֲבִין לוֹן בְּכֹלָּא, וְהָא אִתְּמַר. אֲבָל, בְּשַׁעֲתָא דְּרוּחַ מִסְאֲבָא אִתְּעַר (ס\"א לתתא, אתער רוח וכו') חֲשַׁבְתּוּן זָר, אֶלָּא רוּחַ מִסְאֲבָא דִּלְתַתָּא, אִתְּעַר רוּחַ מִסְאֲבָא אָחֳרָא, וְאִתְיְהִיב לֵיהּ רְשׁוּתָא לְנַחְתָּא לְעָלְמָא. מַאי רְשׁוּתָא, רְשׁוּתָא דִּקְדוּשָּׁה דְּהֲוָה נָחִית וּמָחֵי בֵּיהּ, לָא אִשְׁתְּכַח, וְאִסְתְּלַּק, וּכְדֵין אִתְגַּלְיָיא דִּינָא, לָקֳבְלֵיהוֹן דְּחַיָּיבִין, וְאוֹסִיף דִּינָא עַל דִּינֵיהּ, וּכְדֵין, תְּרֵין רוּחִין מִשְׁתַּכְּחִין בְּעָלְמָא, חַד, רוּחָא דְּדִינָא, וְחַד, רוּחָא דִּמְסָאֲבָא.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, אִצְטְרִיכְנָא הָכָא לְמֵימַר מִלָּה דְּאוֹלִיפְנָא מֵאַבָּא. תָּא חֲזֵי, הָכָא יַלְפִינָן מִנֶּגַע דְּבֵיתָא. דְּכַד רוּחָא מִסְאֲבָא שַׁרְיָא בְּבֵיתָא וְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְדַכְּאָה לֵיהּ, שָׁדַר נֶגַע צָרַעַת בְּבֵיתָא, לְקַטְרְגָא דָּא בְּדָא, וְהַהוּא נֶגַע לָא אַעְדֵּי מִבֵּיתָא, וְאַף עַל גַּב דְּרוּחַ מִסְאֲבָא אִסְתְּלַּק מֵהַהוּא בֵּיתָא, עַד דְּיִנְתְּצוּן בֵּיתָא, אֲבָנִין וְאָעִין וְכֹלָּא, כְּדֵין אִתְדָּכֵי אַתְרָא.</p>\n<p>כְּהַאי גַּוְונָא, מַאן דְּאִסְתְּאָב וְאִתְּעַר רוּחָא מִסְאֲבָא וְשָׁארִי עֲלוֹי, כַּד בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְדַכְּאָה עָלְמָא, אִתְּעַר רוּחַ דִּינָא תַּקִּיפָא, וְאִשְׁתְּכַח בְּעָלְמָא וְשַׁרְיָא עַל הַהוּא רוּחָא מִסְאֲבָא, וּמְקַטְרְגֵי דָּא בְּדָא, עַד <Nonei></i>דְּיִתְעַבָּר מֵעָלְמָא, וְהַהוּא רוּחָא דִּינָא תַּקִּיפָא, לָא אִסְתְּלַּק מֵאַתְרֵיהּ עַד דְּיִנָּתֵץ אֲתַר, שַׁיְיפִין וְגַרְמִין וְכֹלָּא, כְּדֵין אִתְדָּכֵי עָלְמָא וְאִתְעַבְּרוּ מִנֵּיהּ רוּחִין מִסְאֲבִין, וְעָלְמָא אִשְׁתְּכַח בְּדַכְיוּ.</p>\n<p>וְעַל דָּא תָּנֵינָן, אָתָא לְאִסְתַּאֲבָא מִסְאֲבִין לֵיהּ ודַּאי. וַוי לֵיהּ לְבַּר נָשׁ כַּד שָׁארֵי עָלֵיהּ רוּחַ מִסְאֲבָא, וְאִשְׁתְּכַח בֵּיהּ בְּעָלְמָא, דְּוַדַּאי לִינְדַע, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְבַעֲרָא לֵיהּ מִן עָלְמָא. זַכָּאִין אִינּוּן צַדִּיקַיָּא דְּכֻלְּהוּ קַדִּישִׁין, וְאִשְׁתְּכָחוּ בִּקְדוּשָּׁה קָמֵי מַלְכָּא קַדִישָׁא, וְשַׁרְיָא עָלַיְיהוּ רוּחַ קַדִּישָׁא, בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי. כֵּיוָן דְּאָתָא צַפְרָא קָמוּ אַזְלוּ.</p>"],[9520012100,"<p>עַד דַּהֲווֹ אָזְלֵי, פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (בראשית ל״ב:ב׳-ג׳) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים. וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ, דְּהֲוָה אָזִיל לָקֳבֵל אֲבוּהִי. תָּא חֲזֵי, כָּל זִמְנָא, דְּיַעֲקֹב אִשְׁתְּכַח לְגַבֵּיהּ דְּלָבָן לָא מַלִּיל עִמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, (ולא אשתכח לגביה) וְאִי תֵּימָא, וְהָא כְּתִיב, (בראשית ל״א:ג׳) וַיֹּאמֶר יְיָ' אֶל יַעֲקֹב שׁוּב אֶל אֶרֶץ אֲבוֹתֶיךָ וּלְמוֹלַדְתֶּךָ וְגוֹ'. הַאי בְּסוֹפָא הֲוָה, בְּזִמְנָא דְּבָעָא לְאִתְפָּרְשָׁא מִלָּבָן וְכַד אִתְפְּרַשׁ מִנֵּיהּ, אָתוּ לָקֳבְלֵיהּ אִינּוּן מַלְאֲכֵי וְאוֹזְפוּהוּ בְּאוֹרְחָא.</p>\n<p>תָּא חֲזֵי, כְּתִיב, וַיִּפְגְּעוּ בוֹ. וַיִּפְגַּע בְּמַלְאֲכֵי אֱלֹהִים מִבָּעֵי לֵיהּ, מַאי בוֹ. אֶלָּא אִינְהוּ אָתוּ לְאִתְכַּלְּלָא בֵּיהּ (ואוזפוהו באורחא). מַאי לְאִתְכַּלְּלָא בֵּיהּ. אֶלָּא אִינּוּן מִסִּטְרָא דִּגְבוּרָה קָאַתְיָין, דִּכְתִּיב מַלְאֲכֵי אֱלֹהִים, וְחָמָא מִסִּטְרָא אָחֳרָא מַלְאֲכֵי דְּרַחֲמֵי, וְאִתְכָּלְלוּ בֵּיהּ רַחֲמֵי וְדִינָא.</p>\n<p>תָּא חֲזֵי, בְּקַדְמִיתָא, מַחֲנֶה אֱלֹהִים, זֶה חַד. לְבָתַר וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם, תְּרֵי. חַד מִסִּטְרָא דְּדִינָא וְחַד מִסִּטְרָא דְּרַחֲמֵי, מַלְאֲכִין מֵהַאי גִּיסָא, וּמַלְאָכִין מֵהַאי גִּיסָא, וְעַל דָּא כְּתִיב, וַיִּפְגְּעוּ בוֹ. בוֹ, דַּיְיקָא. וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם, רָאָה אוֹתָם מִבָּעֵי לֵיהּ, מַאי רָאָם. אֶלָּא חָמָא לוֹן כְּלִילָן כַּחֲדָא, מִתְדַּבְּקָן דָּא בְּדָא, מִתְחַבְּרָן דָּא בְּדָא, וְעַל דָּא כְּתִיב רָאָם, וְכֻלְּהוּ אָתוּ לְאוֹזְפָא לֵיהּ וּלְשֵׁיזָבָא לֵיהּ מִידָא דְּעֵשָׂו.</p>"],[9520012101,"<p>כְּתִיב בֵּיהּ בְּעֵשָׂו, (בראשית כ״ה:כ״ה) וַיֵצֵא הָרִאשׁוֹן אַדְמוֹנִי. וַיֵּצֵא הָרִאשׁוֹן, אִי תֵּימָא, דְּיַעֲקֹב טִפָּה קַדְמָאָה הֲוָה, לָאו הָכֵי, דְּהָא כְּתִיב, וַיֵּצֵא הָרִאשׁוֹן, וְלָא כְּתִיב, וַיֵּצֵא רִאשׁוֹן. וּבְגִין דְּיִצְחָק אָתֵי מִסִּטְרָא דְּדִינָא קַשְׁיָא, נָפַק עֵשָׂו אַדְמוֹנִי, סוּמָקָא. דְּאִי יַעֲקֹב הֲוָה בּוּכְרָא, הַהִיא טִפָּה קַדְמָאָה נָפְקָא הָכִי סוּמָקָא. אֲבָל טִפָּה תִּנְיָינָא הֲוָה, וּבְגִין כַּךְ לָא נָפְקָא הָכֵי, דְּהָא מִסִּטְרָא דְּרַחֲמֵי הֲוַת הַהִיא טִפָּה, מֵהַאי גִּיסָא וּמֵהַאי גִּיסָא.</p>\n<p>וְטִפָּה דְּעֵשָׂו לָא הֲוַת כְּטִפָּה דְּיַעֲקֹב, דְּדָא שְׁלִים וְדָא לָא שְׁלִים. וּבְהַהִיא שַׁעֲתָא, יִצְחָק הֲוָה <Nonei></i>מְכַוִּון בְּסִיוּמָא דְּדִינָא קַשְׁיָא, דְּאַפִּיק בְּסִטְרוֹי, בִּגְלִיפוֹי טְהִירִין בְּשַׁיְיפוֹי, וּבְגִין כַּךְ עֵשָׂו, זוּהֲמָא דְּאִתְהַתִּיךְ מִדַּהֲבָא.</p>\n<p>וְעַל דָּא תָּנֵינָן, דְּבָעֵי בַּר נָשׁ לְכַוְּונָא בְּהַהִיא שַׁעֲתָא, בִּרְעוּתָא דְּמָארֵיהּ, בְּגִין דְּיִפּוּק בְּנִין קַדִּישִׁין לְעָלְמָא. וְאִי תֵּימָא, יִצְחָק לָא אִתְכַּוָּון. לָאו הָכֵי, אֶלָּא אִתְכַּוָּון בִּקְדוּשָּׁה, וְאִתְכַּוָּון בְּסִיוּמָא דְּהַהוּא אֲתַר, וְאִשְׁתְּכַח כַּד נָפַק הַהִיא טִפָּה קַדְמָאָה, בְּהַהוּא אֲתַר מַמָּשׁ, וְעַל דָּא כְּתִיב, כֻּלּוֹ כְּאַדֶּרֶת שֵׂעָר.</p>\n<p>תָּא חֲזֵי, דָּוִד בִּשְׁפִירוּ דְּסוּמָקָא נָפַק, וְאִתְאֲחָד בִּקְדוּשָּׁה דְּמָארֵיהּ. וְעַל דָּא כְּתִיב, (שמואל א ט״ז:י״ב) וְהוּא אַדְמוֹנִי עִם יְפֵה עֵינַיִם וְטוֹב רֹאִי. אֲבָל יַעֲקֹב בּוּכְרָא הֲוָה מִנֵּיהּ דְּעֵשָׂו, לָאו מִטִּפָּה, אֶלָּא דְּכַוָּונָה דִּרְעוּתָא, בְּאִילָנָא עִלָּאָה רַבְרְבָא וְתַקִּיף, וְעֵשָׂו בְּהַהוּא אֲתַר דְּסִיוּמָא דְּכֹלָּא, וּבְגִין כַּךְ כְּתִיב, (עובדיה א׳:ב׳) הִנֵּה קָטֹן נְתַתִּיךָ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד.</p>\n<p>רִבִּי יְהוּדָה הֲוָה מַתְנֵי הָכֵי. עֵשָׂו נִקְרָא רִאשׁוֹן, דִּכְתִּיב, (בראשית כ״ה:כ״ה) וַיֵּצֵא הָרִאשׁוֹן אַדְמוֹנִי כֻּלּוֹ. וְקוּדְשָׁא בְּרִיךְ הוּא אִקְרֵי רִאשׁוֹן, דִּכְתִּיב, (ישעיהו מ״ד:ו׳) אֲנִי רִאשׁוֹן ואֲנִי אַחֲרוֹן וְאֶת אַחֲרוֹנִים אֲנִי הוּא. וְזַמִּין לְאִתְפָּרְעָא רִאשׁוֹן מֵרִאשׁוֹן. וּלְמִבְנֵי רִאשׁוֹן, דִּכְתִּיב, (ירמיהו י״ז:י״ב) כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן. וּלְזִמְנָא דְּאָתֵי כְּתִיב, (ישעיהו מ״א:כ״ז) רִאשׁוֹן לְצִיּוֹן הִנֵּהּ הִנָּם וְלִיְרוּשָׁלַ ם מְבַשֵּׂר אֶתֵּן.</p>\n<p>תָּאנָא, זְמִינָא יְרוּשָׁלַם, לְמֶהֱוִי שׁוּרָהָא לְעֵילָּא וּלְאִתְקָרְבָא עַד כּוּרְסֵי יְקָרָא דְּמַלְכָּא. הֲדָא הוּא דִכְתִיב, (ירמיהו ג׳:י״ז) בָּעֵת הַהִיא יִקְרְאוּ לִיְרוּשָׁלַ ם כִּסֵּא יְיָ'. כְּדֵּין כְּתִיב, (ישעיהו ל׳:כ״ו) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם. כְּדֵין (זכריה י״ד:ט׳) בַּיוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וּשְׁמוֹ אֶחָד. בָּרוּךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן: יִמְלוֹךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9520012102,"<p><Nonei></i><Noneb>תוספתא</b> (נ\"ח מ\"ה) רִבִּי אֶלְעָזָר, וְרִבִּי יוֹסֵי חָמוּי, הֲווֹ אָזְלֵי מֵאוּשָׁא לְלוּד. אָמַר רִבִּי יוֹסֵי לְרִבִּי אֶלְעָזָר, אֶפְשָׁר שַׁמַעְת מֵאָבוּךְ מַאי דִּכְתִּיב, וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וְגוֹ'. אָמַר לֵיהּ לָא יְדַעְנָא. עַד דַּהֲווֹ אָזְלֵי מָטוּ לִמְעַרְתָּא דְּלוּד. שָׁמְעוּ הַהוּא קָלָא דְּאָמַר, תְּרֵי עוּזְלִין דְּאַיַלְתָּא עָבְדוּ קָמַאי רְעוּתָא דְּנִיחָא לִי. וְאִינּוּן הֲווֹ מַשִׁרְיָּיתָא קַדִּישָׁא דְּעָרַע יַעֲקֹב קַמֵּיהּ. אִתְרְגִישׁ רִבִּי אֶלְעָזָר, וְאִסְתָעַר בְּנַפְשׁוֹי, וְאָמַר, מָרֵיהּ דְּעָלְמָא כַּךְ אוֹרְחוֹי, טַב לָן דְּלָא נִשְׁמַע, שְׁמַעְנָא וְלָא יְדַעְנָא.</p>\n<p>אִתְרְחִישׁ לֵיהּ נִיסָא, וְשָׁמַע הַהוּא קָלָא דְּאָמַר, אַבְרָהָם וְיִצְּחָק הֲווֹ, נָפַל עַל אַנְפּוֹי וְחָמָא דִּיּוּקְנָא דַּאֲבוֹי, אָמַר לֵיהּ, אַבָּא, שָׁאִילְנָא וַאֲתִיבוּנָא, דְּאַבְרָהָם וְיִצְּחָק הֲווֹ, דְּעָרְעוּ לְיַעֲקֹב כַּד אִשְׁתְּזִיב מִלָּבָן. אָמַר לֵיהּ בְּרִי, פּוּק (ס\"א פסקך) פִּתְקָךְ, וְסָב סְבָתֵךְ, פּוּם מְמַלֵּל רַבְרְבָן הֲוָה. וְלָא דָּא הִיא בִּלְחוֹדוֹי, אֶלָּא לְכָל צַּדִּיקַיָּא נִשְׁמָתְהוֹן דְּצַּדִּיקַיָּא מְעַרְעִין קֳדָמוֹהִי לְשֵׁיזָבוּתֵיהּ, וְאִינּוּן מַלְאֲכֵיא קַדִישֵׁי עִלָּאֵי.</p>\n<p>וְתָּא חֲזֵי, יִצְּחָק קַיָּים הֲוָה בְּהַהִיא שַׁעֲתָא, אֲבָל נִשְׁמָתֵיהּ קַדִּישָׁא אִתְנְסִיבַת בְּכוּרְסְיָא יְקָרָא דְּמָארֵיהּ, כַּד אִתְעֲקָד עַל גַּבֵּי מַדְבְּחָא. וּמִכְּדֵּין אַסְתְּמוּ עֵינוֹי מֵחֵיזוּ. הַיְינוּ דִּכְתִּיב, (בראשית ל״א:מ״ב) לוּלֵא וְגוֹ' וּפַחַד יִצְּחָק הָיָה לִי. (ע\"כ תוספתא)</p>"],[9520012103,"<p>(ויקרא ט״ז:א׳) וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן וְגוֹ'. וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה. רִבִּי יְהוּדָה אָמַר, כֵּיוָן דִּכְתִּיב וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה, אֲמַאי זִמְנָא אָחֳרָא וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה דַּבֶּר אֶל אַהֲרֹן אָחִיךְ, דְּהָא בְּמִלּוּלָא קַדְמָאָה סַגֵּי. אֶלָּא הָכִי תָּנֵינָן, כְּתִיב, וַיִּקְרָא אֶל מֹשֶׁה וַיְדַבֵּר יְיָ' אֵלָיו. וּכְתִיב, (שמות כ״ד:א׳) וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל יְיָ'. וְהָא אוּקְמוּהָ מִלָּה, דְּהָכָא דַּרְגָּא חַד. וּלְבָתַר, דַּרְגָּא אָחֳרָא. אוּף הָכָא, וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה דַּרְגָּא חַד. וּלְבָתַר וַיֹאמֶר יְיָ' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךְ, דַּרְגָּא אָחֳרָא. וְכֹלָּא, בְּחַד מַתְקְלָא סַלְּקָא, וּמִן שָׁרְשָׁא חָד כֻּלָּא אִתְחַבָּר.</p>\n<p>אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. רִבִּי יִצְחָק פָּתַח, (תהילים ב׳:י״א) עִבְדוּ אֶת יְיָ' בְּיִרְאָה וְגִילוּ בִּרְעָדָה. וּכְתִיב, (תהילים ק׳:ב׳) עִבְדוּ אֶת יְיָ' בְּשִׂמְחָה בֹּאוּ לְפָנָיו בִּרְנָנָה. הָנֵי קְרָאֵי קַשְׁיָין אֲהַדְדֵי, אֶלָּא הָכִי תָּאנָא, עִבְדוּ אֶת יְיָ' בְּיִרְאָה. דְּכָל פּוּלְחָנָא דְּבָעֵי בַּר נָשׁ לְמִפְלַח קָמֵי מָארֵיהּ, בְּקַדְמִיתָא בָּעֵי יִרְאָה, לְדַחֲלָא מִנֵּיהּ, וּבְגִין דַּחֲלָא דְּמָארֵיהּ, יִשְׁתְּכַּח לְבָתַר דְּיַעֲבֵיד בְּחֶדְוָותָא פִּקּוּדֵי אוֹרַיְיתָא. וְעַל דָּא כְּתִיב, (דברים י׳:י״ב) מָה יְיָ' אֱלֹהֶיךָ שׁוֹאֵל מֵעִמָּךְ כִּי אִם לְיִרְאָה.</p>\n<p>וְגִילוּ בִּרְעָדָה. דְּאָסִיר לֵיהּ לְבַּר נָשׁ לְמֶחְדֵּי יַתִּיר בְּעָלְמָא דֵּין. הַאי בְּמִלֵי דְּעָלְמָא, אֲבָל בְּמִלֵי דְּאוֹרַיְיתָא וּבְפִקוּדֵי דְּאוֹרַיְיתָא, בָּעֵי לְמֶחְדֵּי. לְבָתַר, יִשְׁתְּכַּח בַּר נָשׁ דְּיעָבִיד בְּחֶדְוָותָא פִּקּוּדֵי אוֹרַיְיתָא. דִּכְתִּיב, עִבְדוּ אֶת יְיָ' בְּשִׂמְחָה.</p>\n<p>רִבִּי אַבָּא אָמַר, עִבְדוּ אֶת יְיָ' בְּיִרְאָה. <Nonei></i>רָזָא דְּמִלָּה הוּא, עִבְדוּ אֶת יְיָ' בְּיִרְאָה, מַה יִרְאָה הָכָא. אֶלָּא כְּמָה דְּאוֹקִימְנָא, דִּכְתִּיב, (משלי א׳:ז׳) יִרְאַת יְיָ' רֵאשִׁית דָּעַת, וּכְתִיב, (תהילים קי״א:י׳) רֵאשִׁית חָכְמָה יִרְאַת יְיָ'. יִרְאַת יְיָ', קוּדְשָׁא בְּרִיךְ הוּא הָכִי אִקְרֵי. רִבִּי אֶלְעָזָר אָמַר, עִבְדוּ אֶת יְיָ' בְּיִרְאָה, מַאן דְּבָעֵי לְמֶעְבַּד פּוּלְחָנָא דְּמָארֵיהּ, מֵאָן אֲתַר שָׁארֵי, וּבְאָן אֲתַר יְכַוִּון פּוּלְחָנָא לְיַחֲדָא שְׁמָא דְּמָארֵיהּ. הָדָר וְאָמַר בְּיִרְאָה, בְּיִרְאָה הוּא שֵׁירוּתָא, מִתַּתָּא לְעֵילָּא. (תא חזי בני אהרן האי אוקימנא והא אתמר מלה)</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב הָכָא אַחֲרֵי מוֹת, וּלְבָתַר דַּבֵּר אֶל אַהֲרֹן אָחִיךְ וְגוֹ' בְּזֹאת יָבֹא אַהֲרֹן, אֶלָּא מִכָּאן, שֵׁירוּתָא לְאַזְהָרָא לְכַהֲנֵי, כָּל מַאן, דְּבַעְיָין לְאִזְדַּהֲרָא בְּהַאי זֹאת, וְדָא הִיא יִרְאַת יְיָ'.</p>\n<p>דָּבָר אַחֵר. אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. רִבִּי יוֹסֵי אָמַר, אַחֲרֵי מוֹת נָדָב וַאֲבִיהוּא, מִבָּעֵי לֵיהּ, מַאי טַעְמָא שְׁנֵי בְּנֵי אַהֲרֹן, וְהָא יְדִיעַ דִּבְנוֹי הֲווֹ. אֶלָּא הָכִי תָּאנָא, דְּעַד כָּאן לָאו בִּרְשׁוּתַיְיהוּ קַיְימֵי, אֶלָּא בִּרְשׁוּתָא דְּאָבוּהוֹן, וּבְגִין כָּךְ, בְּקָרְבָתָם לִפְנֵי יְיָ' וַיָמוּתוּ, דְּאִינּוּן דָּחֲקוּ שַׁעֲתָא בְּחַיֵּי דְּאָבוּהוֹן, וְכֹלָּא הֲוָה, בְּגִין הַהוּא חוֹבָא דְּעָבְדוּ, דִּכְתִּיב (במדבר ג׳:ד׳) בְּהַקְרִיבָם אֵשׁ זָרָה. דְּתַנְיָא, בְּאָתַר חַד, כְּתִיב בְּהַקְרִיבָם אֵשׁ זָרָה, וּבְאֲתָר חַד כְּתִיב, בְּקָרְבָתָם לִפְנֵי יְיָ'. וְהַאי וְהַאי הֲוָה, וּבְגִין כָּךְ כְּתִיב הָכָא בְּנֵי אַהֲרֹן, וּכְתִיב בְּקָרְבָתָם.</p>\n<p>(תאנא) אָמַר רִבִּי חִיָיא, יוֹמָא חַד הֲוִינָא אָזִיל בְּאָרְחָא, לְמֵיהַךְ גַּבֵּיה דְּרִבִּי שִׁמְעוֹן, לְמֵילַף מִנֵּיהּ פַּרְשְׁתָּא דְּפִסְחָא. עַרְעִית בְּחַד טוּרָא, וַחֲמֵינָא בְּקִיעִין גּוּמִּין בְּחַד טִינְרָא, וּתְרֵין גּוּבְרִין בָה. עַד דַּהֲוִינָא אָזִיל, שְׁמַעְנָא קָלָא דְּאִינּוּן גּוּבְרִין, וַהֲווּ אַמְרִין, (תהילים מ״ח:א׳-ב׳) שִׁיר מִזְמוֹר לִבְנֵי קֹרַח גָּדוֹל יְיָ' וּמְהֻלָל מְאֹד וְגוֹ'. מַאי שִׁיר מִזְמוֹר. אֶלָּא הָכִי תָּאנָא מִשְּׁמֵיהּ דרִבִּי שִׁמְעוֹן, שִׁיר דְּאִיהוּ כָּפוּל, שִׁיר דְּאִיהוּ מְשׁוּבַּח מִשְּׁאַר שִׁירִין, וְעַל דְּאִיהוּ מְשׁוּבַּח מִשְּׁאַר שִׁירִין, תְּרֵין זִמְנִין אִתְּמַר בֵּיהּ שִׁירָתָא, וְכֵן (תהילים צ״ב:א׳) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת. כְּהַאי גַּוְונָא, (שיר השירים א׳:א׳) שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה, שִׁירָתָא לְעֵילָּא מִן שִׁירָתָא.</p>\n<p>שִׁיר מִזְמוֹר, שִׁירָתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּקָא מְזַמְּרֵי בְּנֵי קֹרַח עַל אִינּוּן דְּיַתְבֵי, עַל פִּתְחָא דְּגֵיהִנָם. וּמַאן אִינּוּן, אֲחוּהוֹן דְּאִינּוּן דְּיַתְבֵי בְּתַרְעֵי דְּגֵיהִנָּם. וְעַל דָּא, שִׁירָתָא דָּא בְּיוֹם שֵׁנִי אִתְּמַר. קָרִיבְנָא גַּבַּיְיהוּ, אֲמֵינָא לְהוּ, מַאי עֲסָקַיְיכוּ בַּאֲתַר דָּא. אָמְרוּ מְזַבְּנֵי אֲנָן, וּתְרֵי יוֹמֵי בְּשַׁבְּתָא, בָּדִילְנָא מִיִשׁוּבָא וְנַעֲסֵק בְּאוֹרַיְיתָא. בְּגִין דְּלָא שַׁבְקִין לָן בְּנֵי נָשָׁא, כָּל יוֹמָא וְיוֹמָא. אֲמֵינָא זַכָּאָה חוּלָקֵיכוֹן.</p>\n<p>תּוּ פָּתְחוּ וְאָמְרוּ. בְּכָל זִמְנָא דְּצַדִיקַיָא מִסְתַּלְּקֵי מֵעָלְמָא, דִּינָא אִסְתַּלָּק מֵעָלְמָא, וּמִיתַתְהוֹן דְּצַדִיקַיָא מְכַפֶּרֶת עָל חוֹבֵי דָּרָא. וְעַל דָּא פַּרְשְׁתָּא דִּבְנֵי אַהֲרֹן, בְּיוֹמָא דְּכִפּוּרֵי קָרֵינָן לָהּ, לְמֶהֱוִי כַּפָּרָה לְחוֹבֵיהוֹן דְּיִשְׂרָאֵל. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אִתְעַסְּקוּ בְּמִיתָתְהוֹן דְּצַדִּיקַיָּא אִלֵּין, וְיִתְחַשֵׁב לְכוּ כְּאִלּוּ אַתּוּן מְקָרְבִין קָרְבְּנִין בְּהַאי יוֹמָא לְכַפְּרָא עָלַיְיכוּ. דְּתָנֵינָן, כָּל זִמְנָא דְּיִשְׂרָאֵל יֵהוֹן בְּגָלוּתָא, וְלָא יִקְרְבוּן קָרְבְּנִין בְּהַאי יוֹמָא, וְאִינּוּן תְּרֵין שְׂעִירִין לָא יַכְלִין לְקָרְבָא, יְהֵא לְהוּ דֻּכְרָנָא, דִּתְרֵי בְּנֵי אַהֲרֹן, וְיִתְכַּפֵּר עֲלַיְיהוּ.</p>\n<p>דְּהָכִי אוֹלִיפְנָא, דִּכְתִּיב, (במדבר ג׳:ב׳) וְאֵלֶּה שְׁמוֹת בְּנֵי אַהֲרֹן הַכֹּהֲנִים וְגוֹ'. וּכְתִיב, הַבְּכֹר נָדָב וַאֲבִיהוּא אֶלְעָזָר וְאִיתָמָר. וְאֶלְעָזָר וְאִיתָמָר מִבָּעֵי לֵיהּ, מַהוּ אֶלְעָזָר וְאִיתָמָר. אֶלָּא שָׁקוּל הֲוָה אֲבִיהוּא כִּתְרֵי אֲחוּי. וְנָדָב כְּכֻלְּהוּ.</p>\n<p>וְאִית דְּמַתְנֵי (לה אפכא) הַבְּכֹר נָדָב, דָּא בִּלְחוֹדוֹי, וַאֲבִיהוּא בִּלְחוֹדוֹי, וְכָל חַד אִתְחֲשִׁיב בְּעֵינֵיהּ, כְּתַרְוַיְיהוּ, כְּאֶלְעָזָר וְאִיתָמָר. אֲבָל נָדָב וַאֲבִיהוּא בִּלְחוֹדַיְיהוּ, שְׁקוּלִין הֲווֹ לְקָבֵל שִׁבְעִין סַנְהֶדְרִין, דַּהֲווֹ מְשַׁמְּשִׁין קָמֵי מֹשֶׁה. וּבְגִין כַּךְ, מִיתָתְהוֹן מְכַפְּרָא עַל יִשְׂרָאֵל. וְעַל דָּא כְּתִיב, (ויקרא י׳:ו׳) וַאֲחֵיכֶם כָּל בֵּית יִשְׂרָאֵל יִבְכּוּ אֶת הַשְּׂרֵפָה. וְאָמַר רִבִּי שִׁמְעוֹן, הַבְּכֹר נָדָב, כְּלוֹמַר, הַהוּא, דְּכָל שְׁבָחָא וִיקָרָא דִּלֵּיהּ (מה שמיה). נָדָב וַאֲבִיהוּא, עַל אַחַת כַּמָּה וְכַמָּה, דְּהָנֵי תְּרֵי, לָא אִשְׁתְּכָחוּ כְּוָתַיְיהוּ בְּיִשְׂרָאֵל.</p>"],[9520012104,"<p>וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. רִבִּי <Nonei></i>חִזְקִיָּה פָּתַח וְאָמַר, (ישעיהו כ״ט:כ״ב) לָכֵן כֹּה אָמַר יְיָ' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָדָה אֶת אַבְרָהָם וְגוֹ'. הַאי קְרָא קַשְׁיָא, לָכֵן כֹּה אָמַר יְיָ' אֲשֶׁר פָדָה אֶת אַבְרָהָם מִבָּעֵי לֵיהּ. מַאי, כֹּה אָמַר יְיָ' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָדָה אֶת אַבְרָהָם.</p>\n<p>אֶלָּא הָא אוּקְמוּהָ וְהָא אִתְּמַר, דְּיַעֲקֹב פָדָה אֶת אַבְרָהָם וַדַּאי. דִּבְהַהִיא שַׁעֲתָא דְּנָפַל בְּגוֹ נוּרָא דְּכַשְׂדָּאֵי, דָּנוּ דִּינֵיהּ (ס\"י ואמרו קמי קודשא בריך הוא, בגין מאי ישתזיב האי, זכות אבהן לית ליה. אמר ליה, ישתזיב בגין בנוי, דהכי תניא, ברא מזכי אבא). אָמְרוּ, הָא יִשְׁמָעֵאל דְּנָפִיק מִנֵּיהּ. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, הָא יִצְחָק, דְּיוֹשִׁיט קְדָלֵיהּ עַל גַּבֵּי מַדְבְּחָא. אַמְרוּ, הָא עֵשָׂו דְּנָפִיק מִנֵּיהּ. אָמַר, הָא יַעֲקֹב, דְּאִיהוּ כּוּרְסְיָא שְׁלֵימָתָא, וְכָל בְּנוֹהִי שְׁלֵימִין קָמַאי. אַמְרוּ, הָא וַדַּאי בִּזְכוּתָא דָּא יִשְׁתְּזִיב אַבְרָהָם הֲדָא הוּא דִכְתִיב, אֲשֶׁר פָדָה אֶת אַבְרָהָם.</p>\n<p>לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחוָרוּ כִּי בִרְאוֹתוֹ יְלָדָיו מַעֲשֵׂה יָדַי בְּקִרְבּוֹ יַקְדִּישׁוּ שְׁמִי. מַאן אִינּוּן יְלָדָיו מַעֲשֵׂה וְגוֹ'. אִלֵּין אִינּוּן, חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה. דַּאֲפִּילוּ גַרְמַיְיהוּ לְגוֹ נוּרָא יָּקִידְתָא לְקָדָשָׁא שְׁמֵיהּ לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב מַאי בָּעֵי הָכָא יַעֲקֹב, וְהָא כְּתִיב, (דניאל א׳:ו׳) וַיְהִי בָהֶם מִבְּנֵי יְהוּדָה דָּנִיאֵל חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה. בְּנֵי יְהוּדָה אִקְרוּן, וּבְגִין כָּךְ לֹא עַתָּה יֵבוֹשׁ יְהוּדָה מִבָּעֵי לֵיהּ, מַאי לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב.</p>\n<p>אֶלָּא הָכִי תָּנֵינָן. בְּהַאי שַׁעֲתָא דְּאִתְּכְפִיתוּ, לְמִנְפַּל בְּנוּרָא, כָּל חַד אָרִים קַלֵיהּ וְאָמַר, גַּבֵּי כָּל אִינּוּן עַמִּין וּמַלְכִין וְאָפַרְכַיָא, חֲנַנְיָה אָמַר, (תהילים קי״ח:ו׳-ז׳) יְיָ' לִי לֹא אִירָא מַה יַעֲשֶׂה לִי אָדָם יְיָ' לִי בְּעוֹזְרָי וַאֲנִי אֶרְאֶה בְּשוֹנְאָי טוֹב לַחֲסוֹת בַּיְיָ' וְגוֹ'. מִישָׁאֵל פָּתַח וְאָמַר, (ירמיהו ל׳:י׳) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב נְאֻם יְיָ' וְגוֹ' כִּי אִתְּךָ אֲנִי נְאֻם יְיָ' לְהוֹשִׁיעֶךָ כִּי אֶעֱשֶׂה וְגוֹ'. בְּהַהִיא שַׁעֲתָא, דְּשַׁמְעוּ כֻּלְּהוּ שְׁמָא דְּיַעֲקֹב. תַּוְוהוּ וְחַיְיכוּ בְּלֵצָנוּתָא. עֲזַרְיָה פָּתַח וְאָמַר, (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד.</p>\n<p>הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ד:ה׳) זֶה יֹאמַר לַיְיָ' אָנִי וְגוֹ'. זֶה יֹאמַר לה' אָנִי, דָּא חֲנַנְיָה, וְזֶה יִקְרָא בְשֵׁם יַעֲקֹב, דָּא מִישָׁאֵל, וְזֶה יִכְתּוֹב יָדוֹ לַיְיָ' וּבְשֵׁם יִשְׂרָאֵל יְכַנֶּה, דָּא עֲזַרְיָה, בֵּיהּ שַׁעֲתָא כָּנַשׁ קוּדְשָׁא בְּרִיךְ הוּא פָּמַלְיָא דִּילֵיהּ, אָמַר לוֹן, בְּמַאן מִלָּה, מֵאִינּוּן מִלִּין דְּאָמְרוּ אִלֵּין תְּלָתָא, אַשְׁזִיב לוֹן. פָּתְחוּ וְאָמְרוּ, (תהילים פ״ג:י״ט) וְיֵדְעוּ כִּי אַתָּה שִׁמְךָ יְיָ' לְבַדֶּךָ עֶלְיוֹן עַל כָּל הָאָרֶץ.</p>\n<p>בָּה שַׁעֲתָא אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְכוּרְסְיָיא, כּוּרְסְיָיא דִּילִי, בְּמַאן מִלָּה מֵאִינּוּן מִלִּין, אַשְׁזִיב לְאִינּוּן צַדִּיקַיָּיא. אָמַר לֵיהּ, בְּהַאי מִלָּה דְּכֻלְּהוּ חַיְּיכִין בָה, אַשְׁזִיב לוֹן, לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחוָרוּ. כְּמָה דְּקָאִים יַעֲקֹב לְגַבֵּי דְּאַבְרָהָם בְּנוּרָא, יְקוּם הַשְׁתָּא לְגַבֵּי אִלֵּין, הֲדָא הוּא דִכְתִיב, כֹּה אָמַר יְיָ' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָדָה אֶת אַבְרָהָם לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְגוֹ'. מֵהַאי כִּסּוּפָא דְּלֵצָנוּתָא.</p>\n<p>תָּנָא, כֻּלְּהוּ דַּהֲווֹ חַיְיכִין מִמִּלָּה דָּא, אִתּוֹקָדוּ בְּהַהוּא נוּרָא, וְקָטַל לוֹן שְׁבִיבָא דְּנוּרָא. מַאן שֵׁזִיב לְאִלֵּין. עַל דַּהֲווֹ מְצָלָן קָמֵי קוּדְשָׁא בְּרִיךְ הוּא וּמְיַחֲדָן שְׁמֵיהּ כְּדְקָא יֵאוֹת, וְעַל דִּמְיַחֲדָן שְׁמֵיהּ כְּדְקָא יֵאוֹת, אִשְׁתֵּזִיבוּ מֵהַהוּא נוּרָא יָקִידְתָּא.</p>"],[9520012105,"<p>תְּרֵי בְּנֵי אַהֲרֹן קְרִיבוּ אֶשָּׁא נוּכְרָאָה, דְּלָא אִתְיַחֲדוּ שְׁמֵיהּ כְּדְקָא יֵאוֹת, וְאִתּוּקָדוּ בְּנוּרָא. רִבִּי יִצְחָק אָמַר, כְּתִיב, אַחֲרֵי מוֹת. וּכְתִיב וַיָמוּתוּ. כֵּיוָן דְּאָמַר אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן, לָא יְדַעְנָא, דְּהָא וַיָמוּתוּ. אֶלָּא הָכִי תָּנֵינָן, תְּרֵי מִיתוֹת הֲווֹ, חַד לִפְנֵי יְיָ'. וְחַד, דְּלָא הֲווֹ לְהוּ בְּנִין, דְּכָל מַאן דְּלָא זָכֵי לִבְנִין מִית הוּא. בְּגִין כַּךְ, אַחֲרֵי מוֹת, וַיָמוּתוּ.</p>\n<p>רִבִּי אַבָּא אָמַר, מַאי דִּכְתִּיב, (במדבר ג׳:ד׳) וַיָּמָת נָדָב וַאֲבִיהוּא לִפְנֵי יְיָ' בְּהַקְרִיבָם אֵשׁ זָרָה לִפְנֵי יְיָ' בְּמִדְבַּר סִינַי וּבָנִים לֹא הָיוּ לָהֶם וַיְכַהֵן אֶלְעָזָר וְאִיתָמָר. מַאי דָּא לְגַבֵּי דָּא, דִּכְתִּיב, וּבָנִים לֹא הָיוּ לָהֶם, וַיְכַהֵן אֶלְעָזָר וְאִיתָמָר. אֶלָּא רָזָא דְּמִלְתָּא. הַאי דַּאֲמֵינָא, וַיָמוּתוּ, דְּלָא הֲווֹ לְהוּ בְּנִין. וְהָכִי הוּא וַדַּאי. אֲבָל לָא כִּשְׁאָר בְּנֵי עָלְמָא, אַף עַל גַּב דְּלָא אַנְסִיבוּ, דְּהָא אִלֵּין לָא מִיתוּ אֶלָּא מִיתַת גַּרְמֵיהוֹן, אֲבָל מִיתַת נַפְשָׁהוֹן לָא מִיתוּ.</p>\n<p>מְנָא לָן, דִּכְתִּיב, (שמות ו׳:כ״ה) וְאֶלְעָזָר בֶּן אַהֲרֹן <Nonei></i>לָקַח לוֹ מִבְּנוֹת פּוּטִיאֵל לוֹ לְאִשָּׁה וַתֵּלֶד לוֹ אֶת פִּנְחָס אֵלֶּה רָאשֵׁי אֲבוֹת הַלְוִיִּם לְמִשְׁפְּחוֹתָם. אֵלֶּה, וְהָא פִּנְחָס בִּלְחוֹדוֹי הֲוָה. וּכְתִיב, רָאשֵׁי אֲבוֹת הַלְוִיִּם, בְּגִין כָּךְ, מִיתַת גַּרְמֵיהוֹן מִיתוּ, מִיתַת נַפְשָׁהוֹן לָא מִיתוּ. אָמַר רִבִּי אֶלְעָזָר וַדַּאי מַשְׁמַע אֵלֶּה, וּמַשְׁמַע רָאשֵׁי.</p>\n<p>וּבְגִין כָּךְ כְּתִיב, (במדבר כ״ה:ז׳) פִּנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן וּכְתִיב וּפִנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן הָיָה כֹּהֵן בַּיָמִים הָהֵם, פִּנְחָס בֶּן אֶלְעָזָר הַכֹּהֵן מִבָּעֵי לֵיהּ, אֶלָּא בְּכָל אֲתַר דְּאָתָא פִּנְחָס בֶּן אַהֲרֹן הַכֹּהֵן כְּתִיב, וְאֶלְעָזָר לָא כְּתִיב אֶלָּא אֶלְעָזָר הַכֹּהֵן. דִּכְתִּיב, (במדבר כ״ז:ב׳) וְלִפְנֵי אֶלְעָזָר הַכֹּהֵן. (במדבר ל״א:כ״א) וַיֹּאמֶר אֶלְעָזָר הַכֹּהֵן וְגוֹ'. וְעַל דָּא מִיתַת גַּרְמֵיהוֹן מִיתוּ, מִיתַת נַפְשָׁהוֹן לָא מִיתוּ.</p>\n<p>וְתָנֵינָן בְּרָזָא דְּמַתְנִיתִין, תְּרֵי זוּג, פֶּן חָס. וְהָא אִתְּמַר, יוֹ\"ד זְעֵירָא בֵּינֵי אַתְוָון דְּפִנְחָס. דְּהַאי יוֹ\"ד כָּלִיל תְּרֵי כַּחֲדָא, וְדָא הוּא רָזָא דְּמִלָּה, וְהָא אִתְּמַר.</p>\n<p>רִבִּי אֶלְעָזָר שָׁאִיל לַאֲבוּי, אָמַר לֵיהּ, וְהָא תְּרֵי אִינּוּן וּתְרֵי הֲווֹ, אֲמַאי לָא אִשְׁתְּכָחוּ תְּרֵי. אָמַר לֵיהּ, תְּרֵי פַּלְגֵּי גּוּפָא הֲווֹ, דְּהָא לָא אַנְסִיבוּ, וּבְגִין כָּךְ, בְּחַד אִתְכְּלִילוּ, דִּכְתִּיב, וַתֵּלֶד לוֹ אֶת פִּנְחָס אֵלֶּה רָאשֵׁי וְגוֹ'.</p>\n<p>וְיוֹ\"ד דְּפִנְחָס, לָא אִתְיְיהִיב בֵּיהּ לְחַבְּרָא אַתְוָון, אֶלָּא בְּשַׁעֲתָא דְּקַנֵּי לְּקוּדְשָׁא בְּרִיךְ הוּא, וְאָתָא לְיַשְּׁרָא עֲקִימָא, דְּחָמָא דְּהַאי אָת בְּרִית קַדִּישָׁא, עָיֵיל זִמְרִי בִּרְשׁוּתָא אָחֳרָא. וּבְמָּה דְּאִתְעַקָּם בְּקַדְמִיתָא, אִתְתָּקַן הָכָא. בְּנוּכְרָאָה אִתְעַקָּם בְּקַדְמִיתָא, דִּכְתִּיב, בְּהַקְרִיבָם אֵשׁ זָרָה, הָכָא בְּנוּכְרָאָה, אִתְתָּקַן, כְּמָה דִּכְתִיב, (מלאכי ב׳:י״א) וּבָעַל בַּת אֵל נֵכָר. מַה לְהַלָּן אֵשׁ זָרָה, אַף כָּאן נָמֵי אִשָׁה זָרָה.</p>\n<p>מַאי אִתְחֲזֵי הָכָא. אֶלָּא בְּקַדְמִיתָא רְחִיקָא קְרִיבוּ, דִּכְתִּיב, בְּהַקְרִיבָם אֵשׁ זָרָה. אוּף הָכָא זִמְרִי, הֲוָה קָרִיב רְחִיקָא, שְׁמָא דְּמַלְכָּא, הֲוָה קָרִיב גַּבֵּי רְחִיקָא, מִיַּד, (במדבר כ״ה:ז׳) וַיַרְא פִּנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן וַיָּקָם מִתּוֹךְ הָעֵדָה. הָכָא אַתְקִין עֲקִימָא דְּקַדְמֵיתָא, כְּדֵין אִתְיְיהִיב יוֹ\"ד בִּשְׁמֵיהּ לְחַבְּרָא אַתְוָון כַּחֲדָא, וְאִתְבְּשַׂר בְּשָׁלוֹם, דִּכְתִּיב, (במדבר כ״ה:י״ב) לָכֵן אֱמוֹר הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. (בריתי ממש).</p>\n<p>(נח ס\"ו ע\"ב) מַאי שָׁלוֹם הָכָא, אֶלָּא בְּהַהוּא כִּתְרָא, חָבוּ בְּקַדְמִיתָא, בְּהַהוּא כִּתְרָא, אַתְּעֲרוּ קְטָטוּתָא בְּקַדְמִיתָא, וְהַשְׁתָּא דְּאִתְתְּקַן, כְּתִיב הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. בְּרִיתִי מַמָּשׁ, תְּהֵא עִמֵּיהּ בְּשָׁלוֹם, וּבְגִין כַּךְ, אִתְיְיהִיב יוֹ\"ד זְעֵירָא בִּשְׁמֵיהּ, דְּהָא מֵאַתְוָון זְעִירָאן הִיא, לְאַתְחֲזָאָה דְּהָא אִתְתָּקַּן מַה דְּאִתְעַקָּם בְּקַדְמִיתָא, וְהָא אַשְׁלִימַת עִמֵּיהּ. אָתָא רִבִּי אֶלְעָזָר וְנָשִׁיק יְדוֹי. אָמַר, בְּרִיךְ רַחֲמָנָא דְּשָׁאִילְנָא הַאי מִלָּה, וְלָא אִתְאֲבִיד מִנַּאי.</p>\n<p>תָּאנָא אָמַר רִבִּי יוֹסֵי, בְּהַאי יוֹמָא דְּכִפּוּרֵי, אִתְתְּקַּן לְמִקְרֵי פַּרְשְׁתָּא דָּא, לְכַפְּרָא לְיִשְׂרָאֵל בְּגָלוּתָא, בְּגִין דָּא, סִדְרָא דְּיוֹמָא דָּא, הָכָא אִתְסָדַּר, וּבְגִין דְּמִיתַתְהוֹן דִּבְנֵי אַהֲרֹן, מְכַפְּרָא עַל יִשְׂרָאֵל.</p>\n<p>מִכָּאן אוֹלִיפְנָא, כָּל הַהוּא בַּר נָשׁ דְּיִסּוּרֵי דְּמָארֵיהּ אַתְיָין עָלֵיהּ, כַּפָּרָה דְּחוֹבוֹי אִינּוּן. וְכָל מַאן דְּמִצְטָעַר עַל יִסּוּרֵיהוֹן דְּצַדִּיקַיָּא, מַעֲבִירִין חוֹבַיָּיא דִּלְהוֹן מֵעָלְמָא. וְעַל דָּא בְּיוֹמָא דָּא, קוֹרִין, אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן, דְּיִשְׁמְעוּן עַמָּא, וְיִצְטַעֲרוּן עַל אֲבוּדְהוֹן דְּצַדִּיקַיָּא, וְיִתְכַּפֵּר לְהוֹן חוֹבַיְיהוּ. וְכָל דְּמִצְטָעַר עַל אֲבוּדְהוֹן דְּצַדִּיקַיָּא, אוֹ אָחִית דִּמְעִין עָלַיְיהוּ, קוּדְשָׁא בְּרִיךְ הוּא מַכְרִיז עָלֵיהּ וְאוֹמֵר, (ישעיהו ו׳:ז׳) וְסָר עֲוֹנֶךָ וְחַטָּאתְךָ תְּכוּפָּר. וְלֹא עוֹד, אֶלָּא דְּלָא יְמוּתוּן בְּנוֹי בְּיוֹמוֹי. וְעָלֵיהּ כְּתִיב, (ישעיהו נ״ג:י׳) יִרְאֶה זֶרַע יַאֲרִיךָ יָמִים וְגוֹ'.</p>"],[9520012106,"<p>(ויקרא ט״ז:ב׳) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךָ וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ וְגוֹ' רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא וְגוֹ'. אָמַר רִבִּי שִׁמְעוֹן, תַּוַּוהְנָא עַל בְּנֵי עָלְמָא, דְּהָא לֵית לְהוּ עַיְינִין לְמֵחֱזֵי, וְלִבָּא לְאַשְׁגְחָא, וְלָא יַדְעִין, וְלָא שַׁוְיָין לִבַּיְיהוּ לְאִסְתַּכְּלָא בִּרְעוּתָא דְמָאָרֵיהוֹן, הֵיךְ נַיְימִין, וְלָא מִתְעָרֵי מִשֵׁנָתַיְיהוּ, עַד לָא יֵיתֵי הַהוּא יוֹמָא דְּחָפֵי עָלַיְיהוּ חֲשׁוֹכָא וְקַבְלָא, וְיִתְבַּע הַהוּא <Nonei></i>מָארֵיהּ דְּפִקְדוֹנָא, חוּשְׁבָּנָא מִנַּיְיהוּ.</p>\n<p>וְכָרוֹזָא כָּל יוֹמָא קָארֵי עָלַיְיהוּ, וְנִשְׁמָתֵהוֹן, אַסְהִידַת בְּהוֹן בְּכָל יוֹמָא וְלֵילְיָא, אוֹרַיְיתָא רָאמַת קָלִין לְכָל עִבָר, מַכְרֶזֶת וְאוֹמֶרֶת, (משלי א׳:כ״ב) עַד מָתַי פְּתָאִים תְּאֶהֲבוּ פֶתִי (משלי ט׳:ה׳) מִי פֶתִי יָסוּר הֵנָּה חֲסַר לֵב אָמְרָה לוֹ. לְכוּ לַחֲמוּ בְלַחְמִי וּשְׁתוּ בְּיַיִן מָסָכְתִּי. וְלֵית מַאן דְּיַרְכִּין אוּדְנֵיהּ, וְלֵית מַאן דְּיִתְּעַר לִבֵּיהּ.</p>\n<p>תָּא חֲזֵי, זְמִינִין דָּרֵי בַּתְרָאֵי דְּיֵיתוּן, דְּיִתְנְשֵׁי אוֹרַיְיתָא מִבֵּינַיְיהוּ, וְחַכִּימֵי לִבָּא יִתְכַּנְּשׁוּן לְאַתְרַיְיהוּ, (ס\"א לאתרא קדישא) וְלָא יִשְׁתְּכַּח מַאן דְּסָגִיר וּפָתַח. וַוי לְהַהוּא דָּרָא. וּמִכָּאן וּלְהָלְאָה, לָא יְהֵא דָּרָא כְּדָרָא דָּא, עַד דָּרָא דְּיֵיתֵי מַלְכָּא מְשִׁיחָא, וּמַנְדְּעָא יִתְּעַר בְּעָלְמָא, דִּכְתִּיב, (ירמיהו ל״א:ל״ד) כִּי כֻלָּם יֵדְעוּ אוֹתִי לְמִקְּטַנָּם וְעַד גְּדוֹלָם.</p>\n<p>תָּא חֲזֵי, כְּתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן. וְתָנֵינָן, מַה שְׁמֵיהּ דְּהַהוּא נָהָר. אוֹקִימְנָא יוּבַל שְׁמֵיהּ, דִּכְתִּיב, (ירמיהו י״ז:ח׳) וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו. וּבְסִפְרָא דְּרַב הַמְנוּנָא סָבָא, חַיִּים שְׁמֵיהּ, דִּמִתַּמָּן נָפְקִין חַיִּים לְעָלְמָא, וְאִינּוּן אִקְרוּן חַיֵּי מַלְכָּא. וְהָא אוֹקִימְנָא, הַהוּא אִילָנָא רַבָּא וְתַקִּיפָא, דְּמָזוֹן לְכֹלָּא בֵּיהּ. אִקְרֵי עֵץ חַיִּים. אִילָנָא דְּנָטַע שָׁרְשׁוֹי בְּאִינּוּן חַיִּים, וְכֹלָּא הוּא שַׁפִּיר.</p>\n<p>וְתָאנָא, הַהוּא נָהָר אַפִּיק נַחֲלִין עֲמִיקִין, בִּמְשַׁח רְבוּת, לְאַשְׁקָאָה גִּנְתָּא, וּלְרַוָּואָה אִילָנִין וּנְטִיעִין, דִּכְתִּיב (תהילים ק״ד:ט״ז) יִשְׂבְּעוּ עֲצֵי יְיָ' אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע, וְאִינּוּן נַחֲלִין, נַגְדִּין וְאִתְמַשְּׁכָן וּמִתְכַּנְּשִׁין בִּתְרֵין קַיָימִין (נ\"א סמכין) וְאִינּוּן בִּרְיָיתֵי (תרי) קָרֵינָן לְהוּ, (מלכים א ז) יָכִי\"ן וּבוֹעַ\"ז, וְשַׁפִּיר. וּמִתַּמָּן נָפְקִין כָּל אִינּוּן נַחֲלִין, וְשַׁרְיָין לוֹן בְּחַד דַּרְגָּא דְּאִקְרֵי צַדִּיק, דִּכְתִּיב, (משלי י׳:כ״ה) וְצַדִיק יְסוֹד עוֹלָם. וְכֻלְּהוּ אַזְלִין וּמִתְכַּנְּשִׁין לְהַהוּא אֲתַר דְּאִקְרֵי יָם, וְהוּא יַמָּא דְּחָכְמְתָא, הֲדָא הוּא דִכְתִיב, (קהלת א׳:ז׳) כָּל (שמות נ' ע\"ב) הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְגוֹ'.</p>\n<p>וְאִי תֵּימָא, דְּהָא מָטוּ לַאֲתָר דָּא, וּפַסְקִין, וְלָא תַּיְיבִין, לְבָתַר כְּתִיב, אֶל מְקוֹם שֶׁהַנְּחָלִים הוֹלְכִים שָׁם הֵם שָׁבִים לָלָכֶת, בְּגִין דְּהַהוּא נַהֲרָא לָא פָּסִיק לְעָלְמִין. הֵם שָׁבִים, לְאָן אֲתַר שָׁבִים, לְאִינּוּן תְּרֵין קַיְימִין, נֶצַח וְהוֹד. לָלָכֶת, בְּהַאי צַדִּיק, לְאַשְׁכְּחָא בִּרְכָאָן וְחִידוּ. וְהַיְינוּ רָזָא דְּתָנֵינָן, (תהילים ק״ד:כ״ו) לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ, דָּא צַדִּיק.</p>\n<p>כֻּלָּם אֵלֶיךָ יְשַׂבֵּרוּן לָתֵת אָכְלָם בְּעִתּוֹ. מַאן עִתּוֹ. דָּא (עתו דצדיק) מַטְרוֹנִיתָא, דְּאִקְרֵי עִתּוֹ דְּצַדִּיק, וּבְגִין כָּךְ כֻּלְּהוּ מְחַכָּאן לְהַאי עִתּוֹ, כֻּלְּהוּ דְּאַתְּזְנָן לְתַתָּא, מֵאֲתַר דָּא אַתְּזְנָן, וְרָזָא דָּא אוֹקִימְנָא, (תהילים קמ״ה:ט״ו) עֵינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ וְגוֹ' כְּמָה דְּאוֹקִימְנָא.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּהַאי כֹּל, מְבַסֵּם לְעִתּוֹ, וּמִתְחַבְּרָא עִמֵּיהּ, כֻּלְּהוּ עָלְמִין בְּחֵידוּ, כֻּלְּהוּ עָלְמִין בְּבִרְכָּאן, כְּדֵין שְׁלָמָא אִשְׁתְּכַח בְּעִלָּאֵי וְתַתָּאֵי. וְכַד גַּרְמִין חַיָּיבֵי עָלְמָא, דְּתַמָן לָא אִשְׁתְּכָחוּ בִּרְכָאן דְּאִינּוּן נַחֲלֵי, וְיַנְקָא, הַאי עֵת, מִסִּטְרָא אָחֳרָא, כְּדֵין דִּינִין מִתְעָרִין בְּעָלְמָא, וּשְׁלָמָא לָא אִשְׁתְּכַח. וְכַד בָּעָאן בְּנֵי עָלְמָא לְאִתְבָּרְכָא, לָא יַכְלִין אֶלָּא עַל יְדָא דְּכַהֲנָא, בְּגִין דְּיִתְּעַר כִּתְרָא דִּילֵיהּ, וְיִתְבְּרַךְ מַטְרוֹנִיתָא, וְיִשְׁתְּכָחוּ בִּרְכָאן בְּכֻלְּהוּ עָלְמִין.</p>\n<p>תָּאנָא, בְּהַהִיא שַׁעֲתָא, בָּעָא מֹשֶׁה קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, מִלָּה דָּא, אָמַר לֵיהּ, אִי בְּנֵי עָלְמָא יְתוּבוּן קַמָּךְ, עַל יְדֵי דְּמַאן מִתְבָּרְכָאן. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְלִי אַתְּ אוֹמֵר, דַּבֵּר אֶל אַהֲרֹן אָחִיךָ, דְּהָא בִּידֵיהּ מְסִירָאן בִּרְכָאן לְעֵילָּא וְתַתָּא.</p>"],[9520012107,"<p>וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךָ וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ וְגוֹ'. אָמַר רִבִּי אַבָּא, זִמְנִין אִית קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, לְאִשְׁתַּכְּחָא רַעֲוָון, וּלְאִשְׁתַּכְחָא בִּרְכָאן, וּלְמִתְבַּע בָּעוּתֵי, וְזִמְנִין, דְּרַעֲוָון לָא אִשְׁתְּכָחוּ, וּבִרְכָּאן לָא מִזְדַּמְנָן, וְדִינִין קַשְׁיָין מִתְעָרִין בְּעָלְמָא. וְזִמְנִין דְּדִינָא תָּלֵי. תָּא חֲזֵי, זִמְנִין אִית בְּשַׁתָּא, דְּרַעֲוָוא אִשְׁתְּכַח. וְזִמְנִין אִית בְּשַׁתָּא, דְּדִינָא אִשְׁתְּכַח. וְזִמְנִין אִית בְּשַׁתָּא, דְּדִינָא אִשְׁתְּכַח וְתַלְיָא. זִמְנִין אִית בְּיַרְחֵי, דְּרַעֲוָא <Nonei></i>אִשְׁתְּכַח בְּהוּ. וְזִמְנִין אִית בְּיַרְחֵי, דְּדִינִין אִשְׁתְּכָחוּ, וְתַּלְיָין עַל כֹּלָּא.</p>\n<p>זִמְנִין אִית בְּשָׁבוּעֵי, דְּרַעֲוָון מִשְׁתַּכְּחָן, וְזִמְנִין אִית בְּשָׁבוּעֵי, דְּדִינִין מִשְׁתַּכְּחָן בְּעָלְמָא. וְזִמְנִין אִית בְּיוֹמֵי, דְּרַעֲוָוא אִשְׁתְּכַח בְּעָלְמָא וְעָלְמָא אִתְבַּסְמָא. וְזִמְנִין אִית בְּיוֹמֵי דְּדִינִין תַּלְיָין וּמִשְׁתַּכְחָן, וַאֲפִילּוּ בְּשַׁעְתֵּי. וְעַל דָּא כְּתִיב, (קהלת ג׳:א׳) וְעֵת לְכָל חָפֵץ וְגוֹ'. וּכְתִיב, (תהילים ס״ט:י״ד) וַאֲנִי תְפִלָּתִי לְךָ וְגוֹ'. וּכְתִיב, (ישעיה נה) דִּרְשׁוּ יְיָ' בְּהִמָּצְאוֹ. וּכְתִיב, (תהילים י׳:א׳) לָמָּה יְיָ' תַּעֲמוֹד בְּרָחוֹק תַּעְלִים לְעִתּוֹת בַּצָּרָה. וּכְתִיב, (ירמיהו ל״א:ג׳) מֵרָחוֹק יְיָ' נִרְאָה לִי. וְזִמְנִין דְּאִיהוּ קָרוֹב, דִּכְתִּיב, (תהילים קמ״ה:י״ח) קָרוֹב יְיָ' לְכָל קוֹרְאָיו. בְּגִין כָּךְ, וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ וְגוֹ'.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, הָא אוֹקִימְנָא. מִלָּה בְּעִתּוֹ, וְהָכִי הוּא ודַּאי, וְהָכָא אָתָא קוּדְשָׁא בְּרִיךְ הוּא לְאַזְהָרָא לְאַהֲרֹן, דְּלָא יִטְעֵי בְּהַהוּא חוֹבָא, דְּטָעוּ בְּנוֹי, דְּהָא הַאי עֵת יְדִיעָא, בְּגִין כָּךְ לָא יִטְעֵי לְחַבְּרָא עֵת אָחֳרָא, לְגַבֵּי מַלְכָּא. הֲדָא הוּא דִכְתִיב, וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. כְּלוֹמַר, אַף עַל גַּב דְּיֵחֱמֵי עִידָּן, דְּאִתְּמְסַר בִּידָא אָחֳרָא, לְאִתְנָהֲגָא עָלְמָא, וְיִתְמְסַר בִּידוֹי לְיַיחֵד בֵּיהּ לְקָרְבָא לֵיהּ לְקוּדְשָׁא, דְּהָא אֲנָא וּשְׁמִי חַד הוּא. וּבְגִּינֵי כַּךְ, (ס\"א לקרבא ליה לקודשא בריך הוא דהא האי עת ידיע, בגין כך) וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. וְאִי בָּעֵי לְמִנְדַּע בְּמָה יֵיעוּל. בְּזֹאת. בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. דְּהַאי זֹאת, הִיא עֵת דַּאֲחִידַת בִּשְׁמִי, בְּהַאי י', דִּרְשִׁימָא בִּשְׁמִי, יֵיעוּל אֶל הַקֹּדֶשׁ. (אבל) וְאַל יָבֹא בְכָל עֵת.</p>\n<p>תָּאנָא אָמַר רִבִּי יוֹסֵי כְּתִיב (קהלת ג׳:י״א) אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ הַאי מִלָּה אוֹקְמָהּ בּוּצִינָא (ס\"א בשמא) קַדִּישָׁא וְהָכִי הוּא דְּתַנִּינָא אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ וְהָכִי הוּא וַדַּאי. אֶת הַכֹּל וַדַּאי. עָשָׂה יָפֶה בְעִתּוֹ, דָּא בְּדָא, וְלָא יִתְעָרְבוּן אָחֳרָנִין בֵּינַיְיהוּ. בְעִתּוֹ מַמָּשׁ, וְלָא בָּאֳחָרָא. בְּגִינֵי כַּךְ, אַזְהָרוּתָא לְאַהֲרֹן, וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. אֲבָל בְּמָה יֵיעוּל. בְּזֹאת, כְּמָה דְּאוֹקִימְנָא, דִּכְתִּיב בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ.</p>\n<p>רִבִּי אֶלְעָזָר הֲוָה יָתִיב קָמֵי אֲבוּהָ, אָמַר לֵיהּ, כְּתִיב בִּכְנִישְׁתָּא דְּקֹרַח, (במדבר ט״ז:ל״ג) וְיֹּאבְדוּ מִתּוֹךְ הַקָּהָל, מַאי וְיֹּאבְדוּ. אֶלָּא כְּמָה דִּכְתִּיב, (ויקרא כ״ג:ל׳) וְהַאֲבַדְתִּי אֶת הַנֶּפֶשׁ הַהִיא מִקֶּרֶב עַמָּהּ. (ס\"א כתיב בבני אהרן (ויקרא י׳:ב׳) ותצא אש מלפני יי' ותאכל אותם וימותו. וכתיב בכנישתא דקרח ואש יצאה מאת יי' ותאכל את החמשים ומאתים איש ס\"ד דשקילין דא כדא) אָמַר רִבִּי שִׁמְעוֹן, שָׁאנֵי אִינּוּן בְּנֵי אַהֲרֹן, דְּלָא כְּתִיב בְּהוּ אֲבֵדָה, כְּאִינּוּן דִּכְנִישְׁתָּא דְּקֹרַח, דִּכְתִּיב בְּהוּ, וְיֹּאבְדוּ מִתּוֹךְ הַקָּהָל. וּכְתִיב, (במדבר י״ז:כ״ז) הֵן גָּוַעְנוּ אָבַדְנוּ כֻּלָּנוּ אָבַדְנוּ. לְאַכְלְלָא אִינּוּן דְּאַקְרִיבוּ קְטֹרֶת בּוּסְמִין, מָאתָן וְחַמְשִׁין, דְּאִתְאֲבִידוּ וַדַּאי, וְאִלֵּין לָא אִתְאֲבִידוּ.</p>\n<p>אָמַר לֵיהּ כְּתִיב, וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. וּכְתִיב, בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. כֵּיוָן דְּאָמַר, וְאַל יָבֹא בְכָל עֵת, אֲמַאי לָא כְּתִיב, בְּמָה זִמְנָא יֵיעוּל. אָמַר לֵיהּ אֶלְעָזָר, הָא אִתְּמַר, וּמִלָּה חַד הוּא, וְזִמְנָא חַד הוּא הֲווֹ יַדְעֵי כַּהֲנֵי. אֲבָל עַל מַה דְּחָאבוּ בְּנוֹי, בָּעָא לְאַזְהָרָא הָכָא, וְהָא אִתְּמַר. אָמַר לֵיהּ, וַאֲנָא הָכִי סָבִירְנָא, וּבְגִין לְאִתְיַישְּׁבָא מִלָּה בְּעֵינָא.</p>\n<p>אָמַר לֵיהּ, אֶלְעָזָר בְּרִי תָּא חֲזֵי, כָּל קָרְבְּנִין וְכָל עִלָּוָון, נַיְיחָא הוּא דְּקוּדְשָׁא בְּרִיךְ הוּא, אֲבָל לָא הֲוָה נַיְיחָא, כְּמָה דְּהַאי קְטֹרֶת, דִּקְטֹרֶת מְעַלְיָא מִכֹּלָּא. וּבְגִין כָּךְ, הֲווֹ מַעֲלִין לֵיהּ לְגוֹ בְּגוֹ, בִּלְחִישׁוּ. וְהָא אִתְּמַר. וּבְגִין כָּךְ, לָא אִתְעֲנָשׁוּ כָּל בְּנֵי נָשָׂא בִּשְׁאָר קָרְבְּנִין וְעִלָּוָון כְּמוֹ בַּקְּטֹרֶת, דְּכָל פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, הָכָא אִתְקְטַר וְאִתְקְשַׁר יַתִּיר מִכֹּלָּא. וְעַל דָּא אִקְרֵי קְטֹרֶת. וְהָא אִתְּמַר, (משלי כ״ז:ט׳) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב.</p>"],[9520012108,"<p>פָּתַח רִבִּי שִׁמְעוֹן וְדָרַשׁ, (שיר השירים א׳:ג׳) לְרֵיחַ שְׁמָנֶיךָ טוֹבִים וְגוֹ'. הַאי קְרָא אִסְתַּכַּלְנָא בֵּיהּ, וְהָכִי הוּא. לְרֵיחַ, מַאי רֵיחַ. רֵיחַ דִּקְטֹרֶת דְּאִיהוּ דְּקִיקָא וּמָעַלְיָא וּפְנִימָאָה מִכֹּלָּא, וְכַד סָלִיק הַהוּא רֵיחַ לְאִתְקַשְּׁרָא, בְּהַהוּא מְשַׁח רְבוּת דְּנַחֲלֵי מַבּוּעָא, אִתְּעֲרוּ דָּא בְּדָא וְאִתְקְטָרוּ כַּחֲדָא. וּכְדֵין אִינּוּן מִשְׁחָן טָבָאן לְאַנְהָרָא. כְּמָה דְאַתְּ אָמֵר, לְרֵיחַ שְׁמָנֶיךָ טוֹבִים.</p>\n<p>וּכְדֵין אִתְרַק מִשְׁחָא מִדַּרְגָּא לְדַרְגָּא, בְּאִינּוּן דַּרְגִּין דְּאִקְרוּן שְׁמָא קַדִּישָׁא, הֲדָא הוּא דִכְתִיב, שֶׁמֶן תּוּרַק שְׁמֶךָ עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. מַאי עֲלָמוֹת. כְּמָה דְּאוֹקִימְנָא עוֹלָמוֹת, עוֹלָמוֹת מַמָּשׁ, דָּבָר אַחֵר עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. כְּמָה דְאַתְּ אָמֵר, (תהילים מ״ו:א׳) עַל עֲלָמוֹת שִׁיר. וְכֹלָּא חַד.</p>\n<p>וּבְסִפְרָא דְּרַב הַמְנוּנָא סַבָא כְּתִיב, מַאי עוֹלָמוֹת. כְּמָה דְּאַתְּ אָמֵר, (משלי ל״א:ט״ו) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק <Nonei></i>לְנַעֲרוֹתֶיהָ. נַעֲרוֹתֶיהָ הָנֵי עֲלָמוֹת, אֲהֵבוּךָ, לְבָרְכָא שְׁמָךְ, וּלְזַמְּרָא קַמָּךְ, וּמִתַּמָּן אִשְׁתַּכְּחָן בִּרְכָאן בְּכֻלְּהוּ תַּתָּאֵי, וּמִתְבָּרְכִין עִלָּאִין וְתַתָּאִין.</p>\n<p>דָּבָר אַחֵר עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. שַׁפִּיר הוּא מַאן דְּאָמַר. עַל מָוְת אֲהֵבוּךָ, דְּהָא בְּמִלָּה דָּא מָארֵיהוֹן דְּדִינִין אִתְבַּסְּמָן, וּבְגִין דְּהַאי קְטֹרֶת, אִתְקְטַר בְּמִשְׁחָא דִּלְעֵילָּא יַתִּיר, אִתְחֲשָׁב קָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, מִכָּל קָרְבְּנִין וְעִלָּוָון. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, אֲנָא כִּקְטֹרֶת, וְאַנְתְּ כְּמִשְׁחָא, מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה וְגוֹ'. נָרוּצָה: כְּמָה דְאַתְּ אָמֵר, עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. אֲנָא וְכָל אוּכְלוּסִין, דְּהָא כֻּלְּהוּ בִּי אֲחִידָן, וְעַל דָּא מָשְׁכֵנִי, דְּהָא בִּי תַּלְיָין.</p>\n<p>הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו. אִם יֵיעוּל לִי מַלְכָּא בְּאִדָרוֹי, נָגִילָה וְנִשְׂמְחָה בָּךְ, אֲנָא וְכֻלְּהוּ אוּכְלוּסִין. תָּאנָא. כֻּלְּהוּ אוּכְלוּסִין, בְּשַׁעֲתָא דִּכְנֶסֶת יִשְׂרָאֵל חַדָּאת וּמִתְבָּרְכָא, כֻּלְּהוּ חַדָּאן, וְדִינָא לָא שַׁרְיָא כְּדֵין בְּעָלְמָא. וְעַל דָּא כְּתִיב, (תהילים צ״ו:י״א) יִשְׂמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ.</p>\n<p>כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. אָמַר רִבִּי יְהוּדָה, זַכָּאִין אִינּוּן צַדִּיקַיָּא, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי בִּיקָרֵיהוֹן. וְתָנֵינָא, מֶלֶךְ בָשָׂר וָדָם, אִי בַּר נָשׁ רָכִיב עַל סוּסְיָא דִּילֵיהּ, בַּר קַטָלָא הוּא, קוּדְשָׁא בְּרִיךְ הוּא אַרְכִּיב אֵלִיָּהוּ עַל דִּילֵיהּ, דִּכְתִיב, (מלכים ב ב׳:י״א) וַיָּעַל אֵלִיָּהוּ בַּסֳּעָרָה הַשָׁמָיִם וְגוֹ'. הָכָא מַאי כְּתִיב, וְלֹא יָמוּת כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. וְקוּדְשָׁא בְּרִיךְ הוּא עַיְילֵיהּ לְמֹשֶׁה בֵּיהּ, הֲדָא הוּא דִכְתִיב, (שמות כ״ד:י״ח) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן, בְּתוֹךְ הֶעָנָן מַמָּשׁ, כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. הֲדָא הוּא דִכְתִיב, (ישעיהו ד׳:ה׳) וּבָרָא יְיָ' עַל כָּל מְכוֹן הַר צִיּוֹן וְעַל מִקְרָאֶיהָ עָנָן יוֹמָם וְעָשָׁן. וּכְתִיב, (שמות מ׳:ל״ח) כִּי עָנָן יְיָ' עַל הַמִּשְׁכָּן יוֹמָם.</p>\n<p>וְתָאנָא, הַאי דִּכְתִּיב, (שמות לד) וַיֵּרֶד יְיָ' בֶּעָנָן. בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. תָּאנָא, אֲתַר דַּהֲווֹ שָׁרָאן אִינּוּן כְּרוּבֵי, כְּמָה דְּאוֹקִימְנָא, כְּרוּבִים עַל אָת הֲווֹ יַתְבִין. וְתָאנָא, ג' זִמְנִין בְּיוֹמָא אִתְרְחִישׁ נִיסָא, בְּגַדְפַיְיהוּ. בְּשַׁעֲתָא דְּאִתְגְּלֵי עָלַיְיהוּ קְדוּשָּׁה דְּמַלְכָּא, אִינּוּן מִגַּרְמַיְיהוּ סַלְּקִין גַּדְפַּיְיהוּ, וּפַרְסִין לוֹן, וְחַפְּיָין עַל כַּפּוֹרְתָא. לְבָתַר קְמִיטִין גַּדְפַיְיהוּ, וְנֶאֱחָזִין בְּגַּדְפַיְיהוּ (ס\"א ונאחזין בגופייהו) כְּמָה דְאַתְּ אָמֵר (שמות כ״ה:כ׳) וְהָיוּ הַכְּרוּבִים פּוֹרְשֵׂי כְנָפַיִם לְמַעְלָה, פּוֹרְשֵׂי וְלָא פְּרוּשֵׂי. סוֹכְכִים וְלָא סְכוּכִים. דָּא בְּאָת (ס\"א בזאת) הֲווֹ קַיְימֵי וְחַדָּאן בִּשְׁכִינְתָּא.</p>"],[9520012109,"<p>אָמַר רִבִּי אַבָּא, מַה בָּעָא הָכָא, כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. וּכְתִיב בְּזֹאת יָבֹא אַהֲרֹן, וְהָא כַּהֲנָא לָא חָמֵי לִשְׁכִינְתָּא בְּשַׁעֲתָא כַּד הֲוָה עָאל. אֶלָּא עֲנָנָא הֲוָה נָחִית, וְכַד הֲוָה נָחִית מָטָא עַל הַאי כַּפֹּרֶת, וּמִתְעָרִין גַּדְפַּיְיהוּ דִּכְרוּבִין, וְאַקְשֵׁי לְהוּ וְאַמְרֵי שִׁירָתָא.</p>\n<p>וּמַה שִׁירָתָא אַמְרֵי (תהילים צ״ו:ד׳) כִּי גָּדוֹל יְיָ' וּמְהֻלָּל מְאֹד נוֹרָא הוּא עַל כָּל אֱלֹהִים. הַאי כַּד סַלְקֵי גַּדְפַּיְיהוּ. בְּשַׁעֲתָא דְּפַרְסִין לְהוּ אַמְרֵי, (תהילים צ״ו:ה׳) כִּי כָּל אֱלֹהֵי הָעַמִּים אֱלִילִים וַיְיָ' שָׁמַיִם עָשָׂה. כַּד חַפְיָין עַל כַּפּוֹרְתָא, אַמְרֵי, (תהילים צ״ח:ט׳) לִפְנֵי יְיָ' כִּי בָא לִשְׁפּוֹט אֵת הָאָרֶץ יִשְׁפּוֹט תֵּבֵל בְּצֶדֶק וְעַמִּים בְּמֵישָׁרִים.</p>\n<p>וְקַלְהוֹן הֲוָה שָׁמַע כַּהֲנָא בְּמַקְדְּשָׁא, כְּדֵין שַׁוִּי קְטֹרֶת בְּאַתְרֵיהּ, וְאִתְכְּוָון בְּמָה דְּאִתְכָּוַּון, בְּגִין דְּיִתְבְּרַךְ כֹּלָּא (וקלהון). וְגַדְפֵּי כְּרוּבְיָיא, סַלְּקִין וְנַחְתִּין, וְזַמְרֵי שִׁירָתָא, מְחַפְּיָין לְכַפּוֹרְתָּא וְסַלְקֵי לְהוּ. הֲדָא הוּא דִכְתִיב סוֹכְכִים. סוֹכְכִים דַּיְיקָא ומְנָא לָן דְּקַלֵהוֹן אִשְׁתְּמַע, כְּמָה דְאַתְּ אָמֵר (יחזקאל א׳:כ״ד) וָאֶשְׁמַע אֶת קוֹל וְגוֹ'.</p>\n<p>אָמַר רִבִּי יוֹסֵי, וְעַמִּים בְּמֵישָׁרִים. מַהוּ בְּמֵישָׁרִים. כְּמָה דְאַתְּ אָמֵר, מֵישָׁרִים אֲהֵבוּךָ, לְאַכְלְלָא תְּרֵין כְּרוּבִין, דְּכַר וְנוּקְבָּא, מֵישָׁרִים וַדַּאי. וְעַל דָּא, וְעַמִּים בְּמֵישָׁרִים.</p>"],[9520012110,"<p>וּכְתִיב, (במדבר ז׳:פ״ט) וְיִּשְׁמַע אֶת הַקּוֹל מִדַּבֵּר אֵלָיו מִבֵּין שְׁנֵי הַכְּרוּבִים וַיְדַבֵּר אֵלָיו. רִבִּי יִצְחָק אָמַר, מִכָּאן אוֹלִיפְנָא דִּבְכָל אֲתַר דְּלָא אִשְׁתְּכַח דְּכַר וְנוּקְבָּא, לָאו כְּדַאי לְמֵחֱמֵי אַפֵּי שְׁכִינְתָּא. הֲדָא הוּא דִכְתִיב, (תהילים ק״מ:י״ד) יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ, וְתָנֵינָן, כְּתִיב, (דברים ל״ב:ד׳) צַדִּיק וְיָשָׁר הוּא, דְּכַר וְנוּקְבָּא, אוּף הָכָא כְּרוּבִים דְּכַר וְנוּקְבָּא. וְעָלַיְיהוּ כְּתִיב, (תהילים צ״ט:ד׳) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים. וְעַמִּים בְּמֵישָׁרִים. וּבְגִּינֵי כַּךְ, (שמות כ״ה:כ׳) וּפְנֵיהֶם אִישׁ אֶל אָחִיו, וְהָא אוֹקִימְנָא.</p>"],[9520012111,"<p><Nonei></i>תַּנְיָא אָמַר רִבִּי יוֹסֵי, זִמְנָא חֲדָא, הֲוָה צְרִיכָא עַלְמָּא לְמִטְרָא, אָתוּ לְקָמֵיהּ (ס\"א אזלו לגביה) דְּרַבִּי שִׁמְעוֹן, רִבִּי יֵיסָא וְרִבִּי חִזְקִיָּה וּשְׁאָר חַבְרַיָּיא. אַשְׁכְּחוּהוּ דְּהֲוָה אָזִיל לְמֵחֱמֵי, לְרִבִּי פִּנְחָס בֶּן יָאִיר, הוּא וְרִבִּי אֶלְעָזָר בְּרֵיהּ. כֵּיוָן דְּחָמָא לוֹן, פָּתַח וְאָמַר, (תהילים קל״ג:א׳) שִׁיר הַמַּעֲלוֹת הִנֵּה מַה טוֹב וּמַה נָעִים שֶׁבֶת אַחִים גַּם יָחַד. מַאי שֶׁבֶת אַחִים גַּם יָחַד.</p>\n<p>כְּמָה דְאַתְּ אָמֵר, וּפְנֵיהֶם אִישׁ אֶל אָחִיו, בְּשַׁעֲתָא דַּהֲווֹ חַד בְּחַד מַשְׁגִּיחִין אַנְפִּין בְּאַנְפִּין, כְּתִיב, מַה טוֹב וּמַה נָעִים. וְכַד מְהַדֵּר דְּכוּרָא אַנְפּוֹי מִן נוּקְבָּא, וַוי לְעָלְמָא. כְּדֵין כְּתִיב, (משלי י״ג:כ״ג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. בְּלֹא מִשְׁפָּט וַדַּאי, וּכְתִיב, (תהילים פ״ט:ט״ו) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךָ, דְּלָא אָזִיל דָּא בְּלָא דָּא, וְכַד מִשְׁפָּט, מִתְרַחֵק מִצֶדֶק, וַוי לְעָלְמָא. (כדין כתיב, (משלי י״ג:כ״ג) ויש נספה בלא משפט).</p>\n<p>וְהַשְׁתָּא חֲמֵינָא, דְּאַתּוּן אֲתִיתוּן, עַל דִּדְכוּרָא לָא שַׁרְיָא בְּנוּקְבָּא, אָמַר, אִי לְדָא אֲתִיתוּן גַּבָּאי תִּיבוּ. דְּהַאי יוֹמָא אִסְתַּכַּלְנָא, דְּיִתְהַדָר כֹּלָּא לְמִשְׁרֵי אַנְפִּין בְּאַנְפִּין. וְאִי לְאוֹרַיְיתָא אֲתִיתוּן, שָׁרוּ גַּבָּאי. אָמְרוּ לֵיהּ, לְכֹלָּא, קָא אֲתֵינָא לְגַבֵּי דְּמֹר, יִשְׁתְּמִיט חַד מִינָן, לְבַשְּׂרָא לַאֲחָנָא, שְׁאָר חַבְרַיָּיא, וַאֲנָן נֵתִיב לְקָמֵיהּ דְּמֹר.</p>\n<p>עַד דַּהֲווֹ אַזְלֵי, פָּתַח וְאָמַר, (שיר השירים א׳:ה׳) שְׁחוֹרָה אֲנִי וְנָאוָה בְּנוֹת יְרוּשָׁלָיִם וְגוֹ'. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, שְׁחוֹרָה אֲנִי בְּגָלוּתָא, וְנָאוָה אֲנִי בְּפִקּוּדֵי אוֹרַיְיתָא, דְּאַף עַל גַּב דְּיִשְׂרָאֵל בְּגָלוּתָא לָא שַׁבְקֵי לוֹן. כְּאָהֳלֵי קֵדָר, דְּאִינּוּן בְּנֵי קְטוֹרָה (ס\"א טורי), דְּאִתְקַדְּרוּ אַנְפַּיְיהוּ תְּדִירָא, וְעִם כָּל דָּא כִּירִיעוֹת שְׁלֹמֹה, כְּהַהוּא חֵיזוֹ שְׁמַיָא לְמִדְכֵּי, דִּכְתִּיב, (תהילים ק״ד:ב׳) נוֹטֶה שָׁמַיִם כַּיְרִיעָה.</p>\n<p>אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת. מַאי טַעְמָא (ס\"א אני שחרחורת בגין ששזפתני) אַל תִּרְאוּנִי, בְּגִין שֶׁאֲנִי שֶׁחַרְחֹרֶת. שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ, דְּלָא אִסְתָּכַּל בִּי שִׁמְשָׁא, לְאַנְהָרָא לִי כְּדְקָא יֵאוֹת. יִשְׂרָאֵל מַה אִינּוּן אַמְרִין. בְּנֵי אִמִּי נִחֲרוּ בִּי. מַאן אִינּוּן בְּנֵי אִמִּי, אִלֵּין רַבְרְבִין מְמָנָן תְּרִיסִין עַל שְׁאָר עַמִּין.</p>\n<p>דָּבָר אַחֵר, בְּנֵי אִמִּי מַמָּשׁ. כְּמָה דְאַתְּ אָמֵר, (איכה ב׳:א׳) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ וְגוֹ'. וְכַד הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ, שָׂמוּנִי נוֹטֵרָה אֶת הַכְּרָמִים. מַאי טַעְמָא. דְּכַרְמִי שֶׁלִּי לֹא נָטָרְתִּי. וְתָנֵינָן, בְּנֵי אִמִּי וַדַּאי אִסְתְכָּמוּ עָלַי, כְּלוֹמַר, כַּד אִתְעָדֵי אֶרֶץ, מִשָּׁמַיִם, כְּמָה דְּאוֹקִימְנָא, דִּכְתִּיב, (שמות ב׳:ד׳) וַתֵּתַצַּב אֲחוֹתוֹ מֵרָחוֹק.</p>\n<p>וְהָכָא אִתְּמַר וַדַּאי, הִנֵּה מַה טוֹב וּמַה נָעִים שֶׁבֶת אַחִים גַּם יָחַד. וּבְהוּ אוֹקִימְנָא (נ\"א והכא אוקימנא), גַּם יָחַד. כְּמָה דְאַתְּ אָמֵר (ויקרא כ״ו:מ״ד) וְאַף גַּם זֹאת בִּהְיוֹתָם, שֶׁבֶת אַחִים בִּכְלַל, כֵּיוָן דִּכְתִּיב, גַּם, לְאַכְלְלָא כָּל אִינּוּן דִּלְעֵילָּא, דְּכָל שׁוּלְטָנוּתָא בְּהַהוּא אֲתַר אִשְׁתְּכַח.</p>\n<p>דָּבָר אַחֵר. הִנֵּה מַה טּוֹב וּמַה נָעִים וְגוֹ'. אִלֵּין אִינּוּן חַבְרַיָּיא, בְּשַׁעֲתָא דְּאִינּוּן יַתְבִין כַּחֲדָא, וְלָא מִתְפָּרְשָׁן דָּא מִן דָּא. בְּקַדְמִיתָא אִתְחָזוּן גּוּבְרֵי מַגִּיחֵי קְרָבָא, דְּבָעוּ לְקָטְלָא דָּא לְדָא. לְבָתַר, אִתְהֲדָרוּ בִּרְחִימוּתָא דְּאַחְוָה. קוּדְשָׁא בְּרִיךְ הוּא מַהוּ אוֹמֵר, הִנֵּה מַה טּוֹב וּמַה נָעִים שֶׁבֶת אַחִים גַּם יָחַד. גַּם, לְאַכְלְלָא עִמְּהוֹן שְׁכִינְתָּא. וְלֹא עוֹד, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא אָצִית לְמִלּוּלַיְיהוּ, וְנִיחָא לֵיהּ וְחַדֵּי בְּהוּ. הֲדָא הוּא דִכְתִיב, (מלאכי ג׳:ט״ז) אָז נִדְבְּרוּ יִרְאֵי יְיָ' אִישׁ אֶל רֵעֵהוּ וַיַּקְשֵׁב יְיָ' וַיִּשְׁמָע וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו וְגוֹ'.</p>\n<p>וְאַתּוּן חַבְרַיָּיא דְּהָכָא, כְּמָה דַּהֲוִיתוֹן בַּחֲבִיבוּתָא בִּרְחִימוּתָא, מִקַּדְמַת דְּנָא, הָכִי נָמֵי, מִכָּאן וּלְהָלְאָה לָא תִּתְפָּרְשׁוּן דָּא מִן דָּא, עַד דְּקוּדְשָׁא בְּרִיךְ הוּא יַחְדֵּי עִמְּכוֹן, וְיִקְרֵי עָלַיְיכוּ שְׁלָם. וְיִשְׁתְּכַּח בְּגִינֵיכוֹן שְׁלָמָא בְּעָלְמָא. הֲדָא הוּא דִכְתִיב, (תהילים קכ״ב:ח׳) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָא שָׁלוֹם בָּךְ.</p>\n<p>אָזְלוּ. עַד דַּהֲווֹ אַזְלֵי, מָטוּ לְבֵי רִבִּי פִּנְחָס בֶּן יָאִיר. נָפַק רִבִּי פִּנְחָס, וּנְשָׁקֵיהּ. אָמַר, זָכֵינָא לְנַשְּׁקָא שְׁכִינְתָּא. זַכָּאָה חוּלָקִי אַתְקִין לְהוּ טִיקְלֵי דְּעַרְסֵי, קַפְטוּרֵי דְּקִילְטָא. אָמַר רִבִּי שִׁמְעוֹן, אוֹרַיְיתָא לָא בָּעֵי הָכִי, אַעְבָּר לְהוֹן, וְיָתִיבוּ. אָמַר רִבִּי פִּנְחָס, עַד לָא נֵיכוּל, נִשְׁמַע מִמָּארֵיהּ דְּאוֹרַיְיתָא מִלָּה. דְּהָא רַבִּי שִׁמְעוֹן כָּל מִלּוֹי בְּאִתְגַּלְיָיא אִינּוּן, אִיהוּ גַּבְרָא דְּלָא דָּחִיל מֵעֵילָּא וּמִתַתָּא, לְמֵימַר לוֹן, לָא דָּחִיל מֵעֵילָּא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אִסְתָּכַּם <Nonei></i>בֵּיהּ, לָא דָּחִיל מִתַּתָּא, כְּאַרְיֵה דְּלָא דָּחִיל מִבְּנֵי עָנָא. אָמַר רִבִּי שִׁמְעוֹן לְרִבִּי אֶלְעָזָר בְּרִיה, אֶלְעָזָר קוּם בְּקִיּוּמָךְ, וְאֵימָא מִלָּה חַדְתָּא, לְגַבֵּי דְּרִבִּי פִּנְחָס וּשְׁאָר חַבְרַיָּיא.</p>"],[9520012112,"<p>קָם רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן וְגוֹ'. הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, דְּאִתְחֲזֵי דְּיַתִּירָא אִיהוּ. דְּהָא כְּתִיב בַּתְרֵיהּ, וַיֹאמֶר יְיָ' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךָ. מִכָּאן שֵׁירוּתָא דְּפַרְשְׁתָּא, הַאי קְרָא דִּלְעֵילָּא, מַאי הוּא, דִּכְתִּיב, וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה. מַאי הוּא דְּאָמַר לֵיהּ, וּלְבָתַר וַיֹאמֶר יְיָ' אֶל מֹשֶׁה.</p>\n<p>אֶלָּא בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב קְטֹרֶת בּוּסְמִין לְאַהֲרֹן, בָּעָא, דְּלָא יִשְׁתַּמֵשׁ בֵּיהּ בְּחַיּיוֹי בַּר נָשׁ אָחֳרָא. מַאי טַעְמָא. בְּגִין דְּאַהֲרֹן אַסְגֵּי שְׁלָמָא בְּעָלְמָא. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אַתְּ בָּעֵי לְאַסְגָּאָה שְׁלָמָא בְּעָלְמָא, עַל יְדָךְ יִסְגֵּי שְׁלָמָא לְעֵילָּא, הָא קְטֹרֶת בּוּסְמִין, יְהֵא מָסוּר בְּיָדְךָ מִכָּאן וּלְהָלְאָה, וּבְחַיֶּיךָ לָא יִשְׁתַּמֵשׁ בֵּיהּ בַּר נָשׁ אָחֳרָא. נָדָב וַאֲבִיהוּא אַקְדִימוּ בְּחַיֵּי דְּאָבוּהוֹן, לְאַקְרְבָא מַה דְּלָא אִתְמְסַר לְהוּ. וּמִלָּה דָּא, גָּרִים לְהוֹן דְּטָעוּ בֵּיהּ.</p>\n<p>וְתָאנָא, מֹשֶׁה הֲוָה מְהַרְהֵר, מַאן גָּרַם לוֹן טָעוּתָא דָּא, וַהֲוָה עָצִיב. מַה כְּתִיב, וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. וּמַה אָמַר לֵיהּ, בְּקָרְבָתָם לִפְנֵי יְיָ' וַיָמוּתוּ. בְּהַקְרִיבָם לָא כְּתִיב, אֶלָּא בְּקָרְבָתָם. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, דָּא גַּרְמָא לְהוּ, דְּדַּחֲקוּ שַׁעֲתָא בְּחַיֵּי אֲבוּהוֹן, וְטָעוּ בָּה, וְהַיְינוּ דִּכְתִּיב, (ויקרא י׳:א׳) אֲשֶׁר לֹא צִוָּה אוֹתָם, אוֹתָם לֹא צִוָּה, אֲבָל לְאַהֲרֹן צִוָּה. וּמַה תְּרֵין בְּנֵי אַהֲרֹן, עַל דְּדָחִיקוּ שַׁעֲתָא בְּחַיֵּי אֲבוּהוֹן גָּרְמוּ לְגַרְמַיְיהוּ כָּל כַּךְ, אֲנָא לְגַבֵּי אַבָּא וְרִבִּי פִּנְחָס וּשְׁאָר חַבְרַיָּיא, עַל אַחַת כַּמָה וְכַמָּה. אָתָא רִבִּי פִּנְחָס נְשָׁקֵּיהּ וּבַרְכֵיהּ.</p>"],[9520012113,"<p>רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (שיר השירים ג׳:ז׳) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ וְגוֹ'. הִנֵה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, מַאי מִטָּתוֹ. דָּא כּוּרְסֵי (נ\"א ערסא) יְקָרָא דְּמַלְכָּא, דִּכְתִּיב בֵּיהּ, (משלי ל״א:י״א) בָּטַח בָּהּ לֵב בַּעְלָהּ. שֶׁלִּשְׁלֹמֹה, מַלְכָּא דִּי שְׁלָמָא כֹּלָּא דִּילֵיהּ הוּא. שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ, דְּאִתְאַחֲדָן בְּסִטְרָהָא מִדִּינָא קַשְׁיָא, וְאִקְרוּן, שִׁתִּין פּוּלְסֵי דְּנוּרָא, (ס\"א שתין מזייני זיוני קשיין) דְּהַהוּא נַעַר, אִתְלְבַּשׁ בְּהוּ.</p>\n<p>מִימִינֵיהּ, שִׁנָּנָא דְּחַרְבָּא תַּקִּיפָא, מִשְּׂמָאלֵיהּ גּוֹמְרֵי דְּנוּרָא תַּקִּיפָא, דְּמִתְאַחֲדָא בִּגְלִיפוֹי (ס\"א בקליפוי), בְּשִׁבְעִין אֶלֶף לַהֲטֵי נוּרָא דְּאַכְלָא, וְאִינּוּן שִׁתִּין מְזַיְינֵי זִיּוּנֵי קַשְׁיָין, מֵאִינּוּן גְּבוּרָן תַּקִּיפִן, דְּהַהִיא גְּבוּרָה עִלָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב מִגִּבּוֹרֵי יִשְׂרָאֵל.</p>\n<p>וְתָאנָא, בְּהַאי עַרְסָא, מַה כְּתִיב בָּהּ, וַתָּקָם בְּעוֹד לַיְלָה, כַּד יַנְקָא מִסִּטְרָא דִּימִינָא (ס\"א מסטרא דדינא). וַתִּתֵּן טֶרֶף לְבֵיתָהּ. מַאי טֶרֶף, כְּמָה דְאַתְּ אָמֵר (מיכה ה׳:ז׳) וְטָרַף וְאֵין מַצִּיל. הֲדָא הוּא דִכְתִיב כֻּלָם אֲחוּזֵי חֶרֶב מְלוּמְּדֵי מִלְחָמָה, זְמִינִין בְּכָל אֲתַר לְמֶעְבַּד דִּינָא, וְאִקְרוּן מָארֵי דִּיבָבָא וִילָלָה.</p>\n<p>אִישׁ חַרְבּוֹ עַל יְרֵכוֹ. כְּמָה דְאַתְּ אָמֵר, (תהילים מ״ה:ד׳) חֲגוֹר חַרְבְּךָ עַל יָרֵךְ גִּבּוֹר. מִפַּחַד בַּלֵּילוֹת. הָא אוּקְמוּהָ, מִפַּחְדָהּ דְּגֵיהִנָּם וְכוּ' אֲבָל מִפַּחַד בַּלֵּילוֹת, כְּלוֹמַר, כָּל דָּא מָאֵן אֲתַר נַטְלִין, מִפַּחַד, מֵהַהוּא אֲתַר דְּאִקְרֵי פַּחַד, כְּמָה דְאַתְּ אָמֵר (בראשית ל״א:נ״ג) וּפַחַד יִצְחָק הָיָה לִי. וַיִשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. בַּלֵּילוֹת, בְּזִמְנִין דְּאִינּוּן מִתְפַּקְדִין לְמֶעְבַּד דִּינָא.</p>\n<p>וְתָאנָא, כְּתִיב (משלי ל״א:ט״ז) זָמְמָה שָׂדֶה וַתִּקָּחֵהוּ. הֲדָא הוּא דִכְתִיב, (איוב מ׳:כ׳) וְכָל חַיַּת הַשָּׂדֶה יְשַׂחֲקוּ שָׁם. וְעַל דָּא כְּתִיב, (תהילים ק״ד:כ״ה) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם וְגוֹ' שָׁם אֳנִיּוֹת יְהַלֵּכוּן וְגוֹ' כְּמָה דְאַתְּ אָמֵר. (משלי ל״א:י״ד) הָיְתָה כָּאֳנִיּוֹת סוֹחֵר מִמֶּרְחָק תָּבִיא לַחְמָהּ. מִמֶּרְחָק וַדַּאי. מֵרֵישָׁא דְּמוֹחָא, וּמֵעֵילָּא דְּרֵישָׁא, תָּבִיא לַחְמָהּ. עַל יְדָא דְּצַדִּיק, כַּד מִזְדַּוְּוגָן כְּחַד, כְּדֵין חֵידוּ בְּכֹלָּא. הֲדָא הוּא דִכְתִיב, לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ.</p>\n<p>תָּאנָא, אֶלֶף וַחֲמֵשׁ מְאָה, מָארֵי תְּרִיסִין, מָארֵי דְּשׁוּלְטָנוּתָא, אִתְאַחֲדָן מְהַאי סִטְרָא, דְּאִינּוּן גִּיבָּרִין. בִּידוֹי דְּהַהוּא דְּאִקְרֵי נַעַר, אַרְבַּע מַפְתְּחִין רַבְרְבָן. תַּנִּינַיָיא אַזְלִין תְּחוֹת סְפִינָה, דְּהַאי <Nonei></i>יַמָּא רַבָּא, לְאַרְבַּע זָוְיָין. דָּא אָזִיל לְסִטְרָא דָּא, וְדָא אָזִיל לְסִטְרָא דָּא. וְכֵן כֻּלְּהוּ. אַרְבַּע חֵיזוּ דְּאַנְפִּין אִתְחַזְיָין בְּהוּ, וְכַד אִתְכְּלִילָן בְּחַד, כְּתִיב, (יחזקאל א׳:י׳) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, פְּנֵיהֶם דְּכֹלָּא.</p>\n<p>אַפֵּי רַבְרְבֵי, וְאַפֵּי זוּטְרֵי, כְּלִילָן כְּחַד לְעֵילָּא, תְּרֵי סַלְּקִין וְשָׁאטִין, וּתְרֵין מַגְרוֹפִין בִּידַיְיהוּ. אֶלֶף טוּרִין סַלְּקִין וְעָאלִין (ס\"א אלין טמירין עאלין וסלקין) בְּכָל יוֹמָא, מִשַּׁקְיוּ דְּהַהוּא יַמָּא, לְבָתַר, אִתְעֲקָרוּ מִנָּהּ, וְסַלְּקִין לְיַמָּא אָחֳרָא.</p>\n<p>לֵית חוּשְׁבָּנָא לְאִינּוּן דְּאִתְאַחֲדָן בְּשַׂעְרָהָא, תְּרֵין בְּנִין יַנְקִין כָּל יוֹמָא, דְּאִקְרוּן מְאַלְלֵי אַרְעָא. וְדָא הוּא רָזָא דְּסִפְרָא דִּצְנִיעוּתָא, דִּכְתִּיב, (יהושע ב׳:א׳) וַיִּשְׁלַח יְהוֹשֻׁעַ בִּן נוּן מִן הַשִׁטִּים שְׁנַיִם אֲנָשִׁים מְרַגְּלִים חֶרֶשׂ לֵאמֹר. וְאִלֵּין, יַנְקִין מִתְּחוֹת סִטְרֵי אֶבְרָהָא, תְּרֵין בַּנוֹת בִּתְחוֹת רַגְלָהָא, (ס\"א ואלין ינקן מסטרא דאברהא, תרין בנת בתחותהא) וְעַל דָּא כְּתִיב, (בראשית ו׳:ב׳) וַיִּרְאוּ בְּנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם. וְאִלֵּין מִתְאַחֲדָן בְּטַרְפֵּי (ס\"א בטופרי) דְּהַהִיא עַרְסָא, וְדָא הוּא דְּתָנֵינָן, דִּכְתִּיב, (מלכים א ג׳:ט״ז) אָז תָּבֹאנָה שְׁתַּיִם נָשִׁים זוֹנוֹת אֶל הַמֶּלֶךְ. אָז תָּבֹאנָה, וְלָא מִקַּדְמַת דְּנָא, וּבְזִמְנָא דְּיִשְׂרָאֵל לְתַתָּא, אָהֲדְרוּן קְדָל מִבָּתַר קוּדְשָׁא בְּרִיךְ הוּא, מַאי כְּתִיב, (ישעיהו ג׳:י״ב) עַמִּי נוֹגְשָׂיו מְעוֹלֵל וְנָשִׁים מָשְׁלוּ בוֹ. וַדַּאי.</p>\n<p>בִּידָא שְׂמָאלָא, שִׁבְעִין עַנְפִין, דְּמְגַדְּלִין בֵּין נוּנֵי יַמָּא, כֻּלְּהוּ סוּמָקֵי כְּוַורְדָּא. וְעֵילָּא מִנְּהוֹן, עַנְפָּא חַד סוּמָקָא יַתִּיר, דָּא סָלִיק וְנָחִית. וְכֻלְּהוּ אִתְחַפְיָּין בְּשַׂעְרָהָא.</p>\n<p>מָארֵי דְּלִישָׁנָא בִּישָׁא. כַּד נָחִית חִוְיָא. אִתְעָבִיד מְקַפֵּץ עַל טוּרִין, מְדַלְגָא עַל טִנָרֵי. עַד דְּיִשְׁכַּח טַרְפָּא, דְּאָחִיד בְּטוּפְרֵי וְיֵיכוּל. כְּדֵין שָׁכִיךְ, וְאִתְחַזָר לִישָׁנֵיהּ לְטָב. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דִּמְזַמְּנִין לֵיהּ טַרְפֵיהּ. אַהֲדָר לְאַתְרֵיהּ (ס\"א לבתריה), עַיִּיל בְּנוּקְבָּא דִּתְהוֹמָא רַבָּא.</p>\n<p>כַּד (ס\"א סליק סלקין) סַלְּקִין מָארֵי דְּרוֹמְחִין וְסַיְיפִין, דְּלֵית לוֹן חוּשְׁבָּנָא, סוּחֲרָנַיְיהוּ דְּאִינּוּן שִׁתִּין עִלָּאִין, דְּסוּחֲרָנֵיהּ דְּהַאי עַרְסָא, אֶלֶף אַלְפִין, וְרִבּוֹא רִבְּוָון, קַיְימִין בְּכָל סִטְרָא דְּהַאי עַרְסָא לְעֵילָּא. וּמִנֵּיהּ אַתְּזְנָן, כֻּלְּהוּ מִקָּמֵיהּ (ס\"א ומניה אתזנו, ליה פלחין כולהו קמיה) יְקוּמוּן.</p>\n<p>מִתְּחוֹת כֻּלְּהוּ, נָפְקִין כַּמָה אֶלֶף וְרִבְּבָן, דְּלֵית לוֹן חוּשְׁבָּנָא, וְנַחְתִּין וְשָׁאטִין בְּעָלְמָא, עַד דְּתַקְעֵי מָארֵי שׁוֹפָרָא, וּמִתְכַּנְּשֵׁי. וְהָנֵי בְּזוּהֲמָא דְּטוּפְרֵי אֲחִידָן.</p>\n<p>דָּא עַרְסָא כָּלִיל לוֹן, דָּא עַרְסָא, רַגְלוֹהִי אֲחִידָן בְּאַרְבַּע סִטְרֵי עָלְמָא, כֹּלָּא עָאלִין בִּכְלָלָא, דְּאִשְׁתְּכַח לְעֵילָּא, וְאִשְׁתְּכַח לְתַתָּא, בַּשָׁמַיִם מִמַּעַל, וְעַל הָאָרֶץ מִתָּחַת, וְעַל דָּא כְּתִיב הִנֵּה. מַאי הִנֵּה. בְּגִין דִּזְמִינָא לְכֹלָּא לְעֵילָּא וְתַתָּא. וּרְשׁוּמָא הַאי עַרְסָא מִכֹּלָּא, אֲדֹנָ\"י אִתְקְרֵי, רִבּוֹנָא דְּכֹלָּא, רְשִׁימָא בֵּין חַיָּילָהָא.</p>\n<p>בְּגִין כַּךְ, כַּהֲנָא בָּעֵי לְכַוְּונָא מִלֵּי דִּלְעֵילָּא, לְיַחֲדָא שְׁמָא קַדִּישָׁא מֵאֲתַר דְּבָעָא לְיַחֲדָא, וְעַל דָּא תָּנֵינָן, כְּתִיב, בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ, בְּהַאי בָּעֵי לְקָרְבָא קְדוּשָּׁה לְאַתְרֵיהּ, מֵהַאי אֲתַר, בָּעֵי בַּר נָשׁ לְדַחֲלָא מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא כְּתִיב, (דברים ל״ב:כ״ט) לוּ חָכְמוּ יַשְׂכִּילוּ זֹאת מִיַּד יָבִינוּ לְאַחֲרִיתָם. כְּלוֹמַר, אִי יִסְתַּכְּלוּן בְּנֵי נָשָׂא בְּעוֹנְשָׁא, הֵיךְ אֲחִידַת זֹאת בֵּין חַיָּילָהָא, וְהֵיךְ אִתְמָנוּ קַמָּהּ כָּל אִינּוּן בְּנֵי חַיָּילִין, וַאֲחִידָן בְּפוּלְחָנָא לְאִתְפָּרְעָא מִן חַיָּיבַיָּא, מִיַּד יָבִינוּ לְאַחֲרִיתָם, וְיִסְתַּמְרוּן עוֹבָדֵיהוֹן, וְלָא יְחוּבוּן קָמֵי מַלְכָּא קַדִּישָׁא.</p>\n<p>תּוּ אָמַר רַבִּי שִׁמְעוֹן, כָּל בַּר נָשׁ דְּזָכֵי לְמֵילַף אוֹרַיְיתָא, וְנָטִיר לָהּ לְהַאי זֹאת. הַאי זֹאת נְטִירַת לֵיהּ, וְגָזַר עִמֵּיהּ קַיְּימָא עַל קַיְּימָא דִּילֵיהּ, דְּלָא יִתְעֲדֵי מִנֵּיהּ, וּמִן בְּנוֹהִי וּמִן בְּנֵי בְּנוֹהִי לְעָלְמִין. הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ט:כ״א) וַאֲנִי זֹאת בְּרִיתִי אוֹתָם וְגוֹ'. יָתְבוּ לְמֵיכַל. עַד דְּאָכְלוּ, אָמַר רַבִּי שִׁמְעוֹן לְחַבְרַיָּיא, כָּל חַד וְחַד לֵימָא מִלָּה חַדְתָּא דְּאוֹרַיְיתָא. עַל פָּתוֹרָא, לְקָמֵיהּ דרִבִּי פִּנְחָס.</p>"],[9520012114,"<p>פָּתַח רִבִּי חִזְקִיָּה וְאָמַר, (ישעיהו נ׳:ד׳) יְיָ' אֱלֹהִים נָתַן לִי לְשׁוֹן לִמוּדִים לָדַעַת לָעוּת אֶת יָעֵף דָּבָר וְגוֹ'. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ מִכָּל שְׁאָר עַמִין, וּקְרָאָן, קֹדֶשׁ. דִּכְתִּיב, (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַיְיָ'. וְיָהִיב <Nonei></i>לְהוּ חוּלָק, לְאִתְאַחֲדָא בִּשְׁמָא קַדִּישָׁא. וּבְמָּה אֲחִידוּ יִשְׂרָאֵל בִּשְׁמָא קַדִּישָׁא. בְּגִין דְּזָכוּ בְּאוֹרַיְיתָא, דְּכָל מַאן דְּזָכֵי בְּאוֹרַיְיתָא זָכֵי בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>(נ\"א בקדש) (רצ\"ז ע\"א) וְתָנֵינָן קָמֵיהּ דְּמַר, מַאי קֹדֶשׁ. שְׁלֵימוּתָא דְּכֹלָּא דְּאִקְרֵי חָכְמָה עִלָּאָה, וּמֵהַאי אֲתַר (נגיד משח רבות קדישא בשבילין ידיען, לאתר דאקרי בינה עלאה), וּמְתַּמָן נַפְקִין מְבּוּעִין וּנְחָלִין לְכָל עֵבָר, עַד דְמַטוּ לְהַאי זֹאת. (ומהאי אתר אתער רוחא קדישא) וְהַאי זֹאת כַּד מִתְבָּרְכָא, אִקְרֵי קֹדֶשׁ, וְאִקְרֵי חָכְמָה, וּקְרָאן לֵיהּ (נ\"א והאי זאת כד אתברכא מאתר עלאה דא דאקרי קדש ואקרי חכמה קראן ליה) רוּחַ הַקֹּדֶשׁ. כְּלוֹמַר, רוּחַ, מֵהַהוּא קֹדֶשׁ דִּלְעֵילָּא. וְכַד נָפְקִין וּמִתְעָרִין מִנֵּהּ רָזֵי אוֹרַיְיתָא, כְּדֵין אִתְקְרֵי לָשׁוֹן הַקֹּדֶשׁ.</p>\n<p>וּבְשַׁעֲתָא דְּנָגִיד הַהוּא רְבוּת קַדִּישָׁא, לְאִינּוּן תְּרֵי קַיְימִין, דְּאִקְרוּן לִמּוּדֵי ה', וְאִקְרוּן צְבָאוֹת, אִתְכְּנַשׁ תַּמָּן, וְכַד נָפִיק מִתַּמָּן, בְּהַהוּא דַּרְגָּא דְּאִקְרֵי יְסוֹד, לְהַהוּא חָכְמָה זְעֵירָא, כְּדֵין אִתְקְרֵי לְשׁוֹן לִמוּדִים. וְנָפִיק לְאִתְּעָרָא לְאִינּוּן קַדִּישֵׁי עֶלְיוֹנִים. כְּדֵין כְּתִיב, יְיָ' אֱלֹהִים נָתַן לִי לְשׁוֹן לִמוּדִים. וְלָמָּה. לָדַעַת לָעוּת אֶת יָעֵף דָּבָר. וְקוּדְשָׁא בְּרִיךְ הוּא יָהִיב הַאי לְבוּצִינָא קַדִּישָׁא, רַבִּי שִׁמְעוֹן. וְעוֹד דְּסָלִיק לֵיהּ לְעֵילָּא לְעֵילָּא, בְּגִין כָּךְ כָּל מִלּוֹי בְּאִתְגַּלְיָיא אִתְּמָרוּ, וְלָא אִתְכַּסְיָין. עָלֵיהּ כְּתִיב, (במדבר י״ב:ח׳) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידוֹת.</p>"],[9520012115,"<p>פָּתַח רִבִּי יֵיסָא וְאָמַר, (מלכים א ה׳:כ״ו) וַיְיָ' נָתַן חָכְמָה לִשְׁלֹמֹה כַּאֲשֶׁר דִּבֶּר לוֹ וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה וְגוֹ'. וַיְיָ' נָתַן חָכְמָה לִשְׁלֹמֹה, דָּא הוּא דְּתָנֵינָן, בְּיוֹמֵי דִּשְׁלֹמֹה מַלְכָּא, קַיְּימָא סִיהֲרָא בְּאַשְׁלְמוּתָא, כַּאֲשֶׁר דִּבֶּר לוֹ, כְּמָה דְּאִתְּמַר לֵיהּ, (דברי הימים ב א׳:י״ב) הַחָכְמָה וְהַמַּדָּע נָתוּן לָךָ.</p>\n<p>וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה. וְכִי מַה בֵּין הַאי לְהַאי. אֶלָּא הָכִי תָּנֵינָן, וַיְיָ' נָתַן חָכְמָה לִשְׁלֹמֹה. וְהַאי חָכְמָה בְּמַאי אוֹקִים לָהּ. אָמַר רִבִּי יוֹסֵי, אוֹקִים לָהּ בְּהַאי, בְּקַדְמִיתָא, דִּשְׁלֹמֹה עֲבַד דְּנָחִית לְחִירָם מֵהַהוּא דַּרְגָּא, דְּהֲוָה אָמַר, (יחזקאל כ״ח:ב׳) מוֹשָׁב אֱלֹהִים יָשַׁבְתִּי וְגוֹ', דְּתַנְיָא, חִירָם מֶלֶךְ צוֹר עָבֵד גַּרְמֵיהּ אֱלוֹהַּ. בָּתַר דִּשְׁלֹמֹה אָתָא, עֲבַד לֵיהּ בְּחָכְמָתֵיהּ, דְּנָחִית מֵהַהוּא עֵיטָא, וְאוֹדֵי לֵיהּ לִשְׁלֹמֹה. וּבְגִין כָּךְ, (מלכים א ה׳:כ״ו) וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה.</p>\n<p>וְתָנֵינָן, אָמַר רִבִּי יִצְחָק אָמַר רִבִּי יְהוּדָה, דְּשָׁדַר לֵיהּ, חַד שִׁידָא, וְנָחִית לְיָד שִׁבְעָה מָדוֹרִין דְּגֵיהִנָּם וְסַלְקֵיהּ, וְשָׁדַר לֵיהּ פִּתְקִין בְּכָל יוֹמָא וְיוֹמָא בִּידֵיהּ, עַד דְּאָהֲדָר, וְאוֹדֵי לֵיהּ לִשְׁלֹמֹה. וְתָנֵינָן. (ויחי רכ\"ג, רכ\"ה) שְׁלֹמֹה יָרִית לָהּ לְסִיהֲרָא, בְּכָל סִטְרוֹי. בְּגִין כָּךְ, בְּכֹלָּא שַׁלִּיט בְּחָכְמָתֵיהּ. וְרַבִּי שִׁמְעוֹן בֶּן יוֹחָאי, שַׁלִּיט בְּחָכְמָתֵיהּ עַל כָּל בְּנֵי עָלְמָא, כָּל אִינּוּן דְּסַלְּקִין בְּדַרְגּוֹי, לָא סַלְּקִין אֶלָּא לְאַשְׁלְמָא עִמֵּיהּ. (ס\"א אי לא שלמין עמיה)</p>\n<p>פָּתַח רִבִּי יוֹסֵי וְאָמַר, (שיר השירים ב׳:י״ד) יוֹנָתִי בְּחַגְוִי הַסֶּלַע בְּסֵתֶר הַמַּדְרֵגָה וְגוֹ'. יוֹנָתִי, דָּא כְּנֶסֶת יִשְׂרָאֵל, מַה יוֹנָה לָא שַׁבְקָת בֶּן זוּגָהּ לְעָלְמִין, כַּךְ כְּנֶסֶת יִשְׂרָאֵל לָא שַׁבְקָת לְּקוּדְשָׁא בְּרִיךְ הוּא לְעָלְמִין. בְּחַגְוִי הַסֶּלַע, אִלֵּין תַּלְמִידֵי חֲכָמִים, דְּלָא מִשְׁתַּכְּחֵי בְּנַיְיחָא בְּעָלְמָא דֵּין. בְּסֵתֶר הַמַּדְרֵגָה, אִלֵּין תַּלְמִידֵי חֲכָמִים, הַצְּנוּעִין, דִּבְהוֹן חֲסִידִין דַּחֲלֵי קוּדְשָׁא בְּרִיךְ הוּא, דִּשְׁכִינְתָּא לָא אַעְדֵּי מִנַיְיהוּ לְעָלְמִין. כְּדֵין, קוּדְשָׁא בְּרִיךְ הוּא מִתְּבַע בְּגִינַיְיהוּ לִכְּנֶסֶת יִשְׂרָאֵל, וְאָמַר, הַרְאִינִי אֶת מַרְאַיִךְ הַשְׁמִיעִנִי אֶת קוֹלֵךְ כִּי קוֹלֵךְ עָרֵב, דְּלֵית קָלָא מִשְׁתְּמַע לְעֵילָּא, אֶלָּא קָלָא דְּאִינּוּן דְּמִתְעַסְּקֵי בְּאוֹרַיְיתָא.</p>\n<p>וְתָאנָא, כָּל אִינּוּן דְּמִתְעַסְּקֵי בְּאוֹרַיְיתָא, בְּלֵילְיָא, דִּיּוּקְנֵיהוֹן אִתְחַקָּק לְעֵילָּא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעְשַׁע בְּהוּ כּוּלֵיהּ יוֹמָא, וּמִסְתְּכַּל בְּהוּ. וְהַהוּא קָלָא, (דהכא) סָלִיק וּבָקַע כָּל אִינּוּן רְקִיעִין, עַד דְּסָלִיק קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. כְּדֵין כְּתִיב, כִּי קוֹלֵךְ עָרֵב וּמַרְאֵךְ נָאוְה. וְהַשְׁתָּא קוּדְשָׁא בְּרִיךְ הוּא חָקַק דִּיּוּקְנָא דְּרַבִּי שִׁמְעוֹן לְעֵילָּא וְקָלֵיהּ לְעֵילָּא לְעֵילָּא סַלְּקָא, וּמִתְעַטְּרָא בְּכִתְרָא קַדִּישָׁא, עַד דְּקוּדְשָׁא בְּרִיךְ הוּא מִתְעַטָּר בֵּיהּ בְּכֻלְּהוּ עָלְמִין. וּמִשְׁתְּבַּח בֵּיהּ. עָלֵיהּ כְּתִיב, (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.</p>"],[9520012116,"<p>פָּתַח רִבִּי חִיָּיא וְאָמַר, (קהלת ג׳:ט״ו) מַה שֶׁהָיָה כְּבָר הוּא (נקרא שמו ל\"ג) וַאֲשֶׁר לִהְיוֹת וְגוֹ'. מַה שֶׁהָיָה כְבָר, הַיְינוּ דְּתָנֵינָן, עַד לָא בָּרָא קוּדְשָׁא בְּרִיךְ הוּא הַאי עָלְמָא, הֲוָה בָּארֵי עָלְמִין וְחָרִיב לוֹן, עַד <Nonei></i>דְּקוּדְשָׁא בְּרִיךְ הוּא סָלִיק בִּרְעוּתֵיהּ, לְמִבְרֵי הַאי עָלְמָא, וְאַמְלִיךְ בְּאוֹרַיְיתָא. כְּדֵין אִתְתָּקַּן הוּא בְּתִקּוּנוֹי, וְאִתְעַטָּר בְּעִטְרוֹי, וּבָרָא הַאי עָלְמָא. וְכָל מַאי דְּאִשְׁתְּכַח בְּהַאי עָלְמָא, הָא הֲוָה קַמֵּיהּ, (והא סליק מקמיה) וְאִתְתָּקַּן קַמֵּיהּ.</p>\n<p>וְתָאנָא, כָּל אִינּוּן דַּבָּרֵי עָלְמָא, דְּאִשְׁתְּכָחוּ בְּכָל דָּרָא וְדָרָא, עַד לָא יֵיתוּן לְעָלְמָא, הָא הֲווֹ קַיְימֵי קַמֵּיהּ בְּדִיּוּקְנֵיהוֹן. (והכי תאנא) אֲפִילּוּ כָּל אִינּוּן נִשְׁמָתִין דִּבְנֵי נָשָׁא, עַד לָא יֶחתוּן לְעָלְמָא, כֻּלְּהוּ גְּלִיפִין קָמֵיהּ בִּרְקִיעָא, בְּהַהוּא דִּיּוּקְנָא מַמָּשׁ, דְּאִינּוּן בְּהַאי עָלְמָא. וְכָל מַה דְּאוֹלְפִין בְּהַאי עָלְמָא, כֹּלָּא יָדְעוּ עַד לָא יֵיתוּן לְעָלְמָא. וְתָנֵינָא, הַאי בְּאִינּוּן זַכָּאֵי קְשׁוֹט.</p>\n<p>וְכָל אִינּוּן דְּלָא מִשְׁתַּכְּחִין זַכָּאִין בְּהַאי עָלְמָא, אֲפִילּוּ תַּמָּן, מִתְרַחֲקִין מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְעָאלִין בְּנוּקְבָּא דִּתְהוֹמָא רַבָּא, וְדַחֲקִין שַׁעֲתָא, וְנַחְתִּין לְעָלְמָא. וְהַהִיא נִשְׁמְתָא דִּלְהוֹן, הָא אוֹלִיפְנָא, כְּמָה דְּאִינּוּן קְשֵׁי קְדָל בְּהַאי עָלְמָא, כַּךְ הֲווֹ עַד לָא יֵיתוּן לְעָלְמָא. וְהַהוּא חוּלָקָא קַדִּישָׁא דְּיָהַב לוֹן רָמָאן לֵיהּ, וְאָזְלִין וְשָׁאטִין וְאַסְתַּאָבוּן, בְּהַהוּא נוּקְבָּא דִּתְהוֹמָא רַבָּא, וְנַטְלֵי חוּלָקֵיהוֹן מִתַּמָּן, וְדַחֲקִין שַׁעֲתָא וְנַחְתֵּי לְעָלְמָא. אִי זָכֵי לְבָתַר, וְתָב בְּתִיּוּבְתָּא קָמֵי מָארֵיהּ, הוּא נָטִיל הַהוּא חוּלָקָא דִּילֵיהּ מַמָּשׁ, הֲדָא הוּא דִכְתִיב, מַה שֶׁהָיָה כְּבָר (נקרא שמו) הוּא וַאֲשֶׁר לִהְיוֹת וְגוֹ' כְּבָר הָיָה.</p>\n<p>תָּא חֲזֵי בְּנֵי אַהֲרֹן לָא אִשְׁתְּכָחוּ בְּיִשְׂרָאֵל כְּוָותַיְיהוּ, בַּר מֹשֶׁה וְאַהֲרֹן, וְאִינּוּן אִקְרוּן (שמות כ״ד:ט׳) אֲצִילֵי בְּנֵי יִשְׂרָאֵל. וְעַל דְּטָעוּ קָמֵי מַלְכָּא קַדִּישָׁא, מִיתוּ. וְכִי קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאוֹבָדָא לוֹן, וְהָא תָּנֵינָן בְּרָזָא דְּמַתְנִיתִין, דְּקוּדְשָׁא בְּרִיךְ הוּא עָבֵד חֶסֶד בְּכֹלָּא, וַאֲפִילּוּ בְּרַשִׁיעֵי עָלְמָא לָא בָּעֵי לְאוֹבָדָא לוֹן. וְהָנֵי זַכָּאֵי קְשׁוֹט סַלְּקָא דַּעְתָּךְ דְּאִינּוּן אִתְאֲבִידוּ מֵעָלְמָא, זְכוּתָא דִּלְהוֹן אָן הוּא. זְכוּתָא דְּאָבוּהוֹן אָן הוּא. זְכוּתָא דְּמֹשֶׁה הָכִי נָמֵי. וְאִינּוּן הֵיךְ אִתְאֲבִידוּ.</p>\n<p>אֶלָּא הָכִי אוֹלִיפְנָא מִבּוּצִינָא קַדִּישָׁא, דְּקוּדְשָׁא בְּרִיךְ הוּא חָס עַל יְקָרָא דִּלְהוֹן, וְאִתּוֹקַד גַּרְמֵיהוֹן לְגוֹ, וְנִשְׁמָתֵהוֹן לָא אִתְאֲבִידוּ, וְהָא אוֹקִימְנָא. וְתָּא חֲזֵי עַד לָא מִיתוּ בְּנֵי אַהֲרֹן כְּתִיב, (שמות ו׳:כ״ה) וְאֶלְעָזָר בֶּן אַהֲרֹן לָקַח לוֹ וְגוֹ', אִקְרֵי שְׁמֵיהּ פִּנְחָס, דְּהֲוָה זַמִּין לְאִתְתָּקְנָא עֲקִימָא, הֲדָא הוּא דִכְתִיב וַאֲשֶׁר לִהְיוֹת כְּבָר הָיָה.</p>\n<p>וְתָאנָא, כֻּלְּהוּ זַכָּאֵי קְשׁוֹט, עַד לָא יֵיתוּן לְעָלְמָא, כֻּלְּהוּ אִתְתְּקָנוּ לְעֵילָּא, וְאִקְרוּן בִּשְׁמָהָן. וְרַבִּי שִׁמְעוֹן בֶּן יוֹחָאי, מִן יוֹמָא דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, הֲוָה אִזְדְּמַן קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְאִשְׁתְּכַח עִמֵּיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא קָרֵי לֵיהּ בִּשְׁמֵיהּ, זַכָּאָה חוּלָקֵיהּ לְעֵילָּא וְתַתָּא, עָלֵיהּ כְּתִיב (משלי כ״ג:כ״ה) יִשְׂמַח אָבִיךָ וְאִמֶּךָ, אָבִיךָ: דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְאִמֶּךָ: דָּא כְּנֶסֶת יִשְׂרָאֵל.</p>"],[9520012117,"<p>פָּתַח רִבִּי אַבָּא וְאָמַר (שיר השירים א׳:י״ב) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. הַאי קְרָא אוּקְמוּהָ חַבְרַיָּיא, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּכַח וְזַמִּין בְּטוּרָא דְּסִינַי, לְמֵיהַב אוֹרַיְיתָא לְיִשְׂרָאֵל, נִרְדִּי נָתַן רֵיחוֹ, יִשְׂרָאֵל יָהֲבוּ וּסְלִיקוּ רֵיחָא טַב, דְּקָאִים וְאָגִין עָלַיְיהוּ לְדָרֵי דָּרִין. וְאָמְרוּ, (שמות כ״ד:ז׳) כָּל אֲשֶׁר דִּבֶּר יְיָ' נַעֲשֶׂה וְנִשְׁמָע. דָּבָר אַחֵר עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ, בְּעוֹד דְּסָלִיק מֹשֶׁה לְקַבְּלָא אוֹרַיְיתָא מְקוּדְשָׁא בְּרִיךְ הוּא, וְאִתְחֲקָק בִּתְרֵי לוּחֵי אֲבָנִין, יִשְׂרָאֵל שָׁבְקוּ הַהוּא רֵיחָא טָבָא דְּהֲוָה מִתְעַטֵּר עָלַיְיהוּ, וְאָמְרוּ לָעֵגֶל, אֵלֶּה אֱלֹהֶיךָ יִשְׂרָאֵל.</p>\n<p>הַשְׁתָּא הַאי קְרָא בְּרָזָא דְּחָכְמְתָא הוּא, תָּא חֲזֵי, כְּתִיב (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן, הַאי נַהֲרָא אִתְפְּשָׁט בְּסִטְרוֹי, בְּשַׁעֲתָא דְּמִזְדְּוַּוג עִמֵּיהּ בְּזִוּוּגָא שְׁלִים, כָּדֵי הַאי עֵדֶן (זווגא) בְּהַהוּא נָתִיב, דְּלָא אִתְיְידַע לְעֵילָּא וְתַתָּא, כְּמָה דְאַתְּ אָמֵר (איוב כ״ח:ז׳) נָתִיב לֹא יְדָעוֹ עָיִט. וְאִשְׁתְּכָחוּ בִּרְעוּתָא (שמות ע\"ז, נ\"ה, ס\"ד ע\"ב) דְּלָא מִתְפָּרְשָׁן תְּדִירָא חַד מֵחַד. כְּדֵין נָפְקִין מַבּוּעִין וּנְחָלִין, וּמְעַטְּרִין לְבֵן קַדִּישָׁא, בְּכָל אִינּוּן כִּתְרִין, כְּדֵין (שמות כ\"ד ע\"א) כְּתִיב (שיר השירים ג׳:י״א) בַּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ. וּבְהַהִיא שַׁעֲתָא יָרִית הַהוּא בֵּן אַחֲסַנְתָּא דַּאֲבוֹי וְאִמֵּיהּ, כְּדֵין הוּא אִשְׁתַּעֲשַׁע, בְּהַהוּא עִנּוּגָא וְתַפְנוּקָא.</p>\n<p>וְתָאנָא, בְּשַׁעֲתָא דְּמַלְכָּא עִלָּאָה בְּתַפְנוּקֵי מַלְכִין, יָתִיב בְּעִטְרוֹי, כְּדֵין כְּתִיב עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. דָּא יְסוֹד דְּאַפִּיק בִּרְכָאן לְאִזְדַּוְּוגָא מַלְכָּא קַדִּישָׁא <Nonei></i>בְּמַטְרוֹנִיתָא. (בהא דרגא) וּכְדֵין אִתְיַיהֲבוּן בִּרְכָאן בְּכֻלְּהוּ עָלְמִין, (ונפקין) וּמִתְבָּרְכָן עִלָּאִין וְתַתָּאִין. וְהַשְׁתָּא הָא בּוּצִינָא קַדִּישָׁא מִתְעַטָּר בְּעִטְרוֹי דְּהַאי דַּרְגָּא, וְהוּא וְחַבְרַיָּיא סְלִיקוּ תּוּשְׁבְּחָן מִתַּתָּא לְעֵילָּא, וְהִיא מִתְעַטְּרָא בְּאִינּוּן תּוּשְׁבְּחָן. הַשְׁתָּא אִית לְאַפָּקָא בִּרְכָאן לְכֻלְּהוּ חַבְרַיָּיא מֵעֵילָּא לְתַתָּא, בְּהַאי דַּרְגָּא קַדִּישָׁא, וְרִבִּי אֶלְעָזָר (ס\"א דרבי אלעזר) בְּרֵיהּ לֵימָא מֵאִינּוּן מִלִּין מְעַלְּיָין דְּאוֹלִיף מֵאֲבוֹי.</p>"],[9520012118,"<p>פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (בראשית כ״ט:ב׳) וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה וְגוֹ'. וְנֶאֱסָפוּ שָׁמָּה כָל הָעֲדָרִים וְגוֹ'. הָנֵי קְרָאֵי אִית לְאִסְתַּכְּלָא בְּהוּ, וּבְרָזָא דְּחָכְמְתָא אִינּוּן, דְּאוֹלִיפְנָא מֵאַבָּא, וְהָכִי אוֹלִיפְנָא, וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה, מַאן בְּאֵר. דָּא הוּא דִּכְתִּיב, (במדבר כ״א:י״ח) בְּאֵר חֲפָרוּהָ שָׂרִים כָּרוּהָ נְדִיבֵי הָעָם. וְהִנֵה שָׁם שְׁלֹשָׁה עֶדְרֵי צֹאן רוֹבְצִים עָלֶיהָ, אִלֵּין אִינּוּן נֶצַח הוֹד יְסוֹד, דְּאִלֵּין אִינּוּן רְבִיעִין עָלָהּ, וְקַיְימִין עָלָהּ, וּמֵאִלֵּין אִתְמַלְּיָא בִּרְכָאן הַהִיא בְּאֵר.</p>\n<p>כִּי מִן הַבְּאֵר הַהִיא יַשְׁקוּ הָעֲדָרִים, דְּהָא מִן הַאי בְּאֵר אִתְּזָנוּ עִלָּאִין וְתַתָּאִין (נ\"א עלמין תתאין), וּמִתְבָּרְכָאן כֻּלְּהוּ כַּחֲדָא. וְהָאֶבֶן גְּדוֹלָה עַל פִּי הַבְּאֵר, דָּא הוּא דִּינָא קַשְׁיָא, דְּקַיְּימָא עָלָהּ מִסִּטְרָא אָחֳרָא לְיָנְקָא לָהּ (נ\"א מינה). וְנֶאֱסָפוּ שָׁמָּה כָל הָעֲדָרִים, אִלֵּין אִינּוּן שִׁית כִּתְרֵי מַלְכָּא, דְּמִתְכַּנְשֵׁי כֻּלְּהוּ, וְנַגְדֵּי בִּרְכָאן מֵרֵישָׁא דְּמַלְכָּא, וּמְרִיקָן בָּהּ. וְכַד אִתְחַבְּרָאן כֻּלְּהוּ כַּחֲדָא לְאַרְקָא בָּהּ, כְּתִיב וְגָלְלוּ אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר, מְנַדְּדִין (ס\"א מגנדרין) לְהַהוּא דִּינָא קַשְׁיָא, וּמְעַבְּרָן לֵיהּ מִינָּהּ.</p>\n<p>וְהִשְׁקוּ אֶת הַצֹּאן, מְרִיקִין בִּרְכָאן מֵהַהִיא בְּאֵר, לְעִלָּאִין וְתַתָּאִין לְבָתַר וְהֵשִׁיבוּ אֶת הָאֶבֶן עַל פִּי הַבְּאֵר לִמְקוֹמָהּ. תָּב הַהוּא דִּינָא לְאַתְרֵיהּ, בְּגִין דְּאִצְטְרִיךְ לֵיהּ לְבָשְׁמָא עָלְמָא, וּלְתַקְּנָא עָלְמָא. וְהַשְׁתָּא הָא קוּדְשָׁא בְּרִיךְ הוּא אָרִיק עָלַיְיכוּ בִּרְכָאן, מִמַּבּוּעָא דְּנַחֲלָא, וּמִנַּיְיכוּ כָּל בְּנֵי דָּרָא מִתְבָּרְכִין. זַכָּאָה חוּלָקֵיכוֹן בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי עָלַיְיכוּ כְּתִיב, (ישעיהו נ״ד:י״ג) וְכָל בָּנַיִךְ לִמּוּדֵי יְיָ' וְרַב שָׁלוֹם בָּנַיִךְ.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהילים קמ״ט:ה׳) יַעְלְזוּ חֲסִידִים בְכָבוֹד יְרַנְּנוּ עַל מִשְׁכְּבוֹתָם וְגוֹ', תָּאנָא בי\"ג מְכִילָן, אִתְקְשַׁר קִשְׁרָא דִּמְהֵימְנוּתָא, לְאִשְׁתַּכְּחָא בִּרְכָאן לְכֹלָּא. וְכָל מְהֵימְנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא בִּתְלָתָא אַסְתִּימוּ. וְעַל הַאי, בי\"ג מְכִילָן, אוֹרַיְיתָא מִתְעַטְּרָא, כְּמָה דְּאוֹקִימְנָא מִקַל וָחוֹמֶר וּמִגְּזֵרָה שָׁוָה וְכוּ', וְכַמָּה זִמְנִין אוֹקִימְנָא הַאי. וּשְׁמָא קַדִּישָׁא בְּהַאי מִתְעַטְּרָא.</p>"],[9520012119,"<p>תָּא חֲזֵי, בְּהַהִיא שַׁעֲתָא דְּבָעָא יַעֲקֹב, דְּיִתְבָּרְכוּן בְּנוֹי בִּשְׁמָא (ס\"א בקשרא) דִּמְהֵימְנוּתָא. מַה כְּתִיב, (בראשית מ״ט:כ״ח) כָּל אֵלֶּה שִׁבְטֵי יִשְׂרָאֵל שְׁנֵים עָשָׂר וְזֹאת, הָא תְּלֵיסַר, דְּאִשְׁתַּתֵּף עִמְּהוֹן שְׁכִינְתָּא, וְאִתְקְיָימוּ בִּרְכָאן. וְהַיְינוּ דִּכְתִּיב, אִישׁ אֲשֶׁר כְּבִרְכָתוֹ בֵּרַךְ אוֹתָם. מַאי כְּבִרְכָתוֹ. בְּהַהוּא דּוּגְמָא דִּלְעֵילָּא, כְּבִרְכָתוֹ דְּכָל מְכִילָא וּמְכִילָא.</p>\n<p>וְתָאנָא, כָּל אִינּוּן מְכִילִין סַלְּקִין, וּמִתְעַטְּרִין וְנַיְיחִין בְּרֵישָׁא חֲדָא, וְתַמָּן מִתְעַטְּרָא רֵישָׁא דְּמַלְכָּא, הַהוּא דְּאִקְרֵי בְּדַרְגָּא עִלָּאָה דַחֲסִידוּת. וַחֲסִידִים, יַרְתִין כָל הַהוּא כָבוֹד דִּלְעֵילָּא, דִּכְתִּיב יַעְלְזוּ חֲסִידִים בְכָבוֹד, בְּהַאי עָלְמָא. יְרַנְּנוּ עַל מִשְׁכְּבוֹתָם בְּעָלְמָא דְּאָתֵי. רוֹמְמוֹת אֵל בִּגְרוֹנָם, דְּיַדְעִין לְקַשְּׁרָא קִשְׁרָא דִּמְהֵימְנוּתָא כְּדְקָא יֵאוֹת, וּכְדֵין חֶרֶב פִּיפִיּוֹת בְּיָדָם. מַאן חֶרֶב פִּיפִיּוֹת. דָּא הוּא חֶרֶב לָה', חַרְבָּא דְּקוּדְשָׁא בְּרִיךְ הוּא. פִּיפִיּוֹת: לְהִיטָא בִּתְרֵין דִּינִין. וְלָמָּה. לַעֲשׂוֹת נְקָמָה בַּגּוֹיִם וְגוֹ'.</p>\n<p>וְהָא רִבִּי פִּנְחָס בֶּן יָאִיר, כִּתְרָא דְּחֶסֶד, רֵישָׁא עִלָּאָה. בְּגִין כָּךְ כָּבוֹד דִּלְעֵילָּא יָרִית, וְהוּא קָשִׁיר קִשְׁרָא עִלָּאָה, קִשְׁרָא קַדִּישָׁא, קִשְׁרָא דִּמְהֵימְנוּתָא. זַכָּאָה חוּלָקֵיהּ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי. עַל הַאי פָּתוֹרָא אִתְּמַר, (יחזקאל מ״א:כ״ב) זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי יְיָ'. קָם רִבִּי פִּנְחָס, וְנָשִׁיק לֵיהּ, וּבָרִיךְ לֵיהּ, וְנָשִׁיק לְרִבִּי אֶלְעָזָר, וּלְכֻלְּהוּ חַבְרַיָּיא, וּבָרִיךְ לוֹן, נָטַל כַּסָּא וּבָרִיךְ.</p>"],[9520012120,"<p>פָּתַח וְאָמַר, (תהילים כ״ג:ה׳) תַּעֲרוֹךְ לְפָנַי שֻׁלְחָן נֶגֶד צוֹרְרָי וְגוֹ', יָתְבוּ (ס\"א חדו) תַּמָּן, כָּל הַהוּא יוֹמָא, וַהֲווּ חַבְרַיָּא כֻּלְּהוּ חַדָּן <Nonei></i>בְּמִלֵּי דְּאוֹרַיְיתָא, וְחֶדְוָותָא דְּרַבִּי שִׁמְעוֹן הֲוָה סַגֵּי. נָטַל רִבִּי פִּנְחָס לְרִבִּי אֶלְעָזָר, וְלָא שַׁבְקֵיהּ כָּל הַהוּא יוֹמָא וְכָל לֵילְיָא, וַהֲוָה חַדֵּי עִמֵּיהּ, קָרָא עָלֵיהּ, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ', כָּל חֶדְוָותָא וְעִנּוּגָא יַתִּירָא דָּא דְּחוּלָקִי הוּא, (על דא דעמי הוא על דא כתיב (תהילים קמ״ד:ט״ו) אשרי העם שככה לו וגו') זְמִינִין בְּהַהוּא עָלְמָא לְאַכְרְזָא עָלַי, זַכָּאָה חוּלָקָךְ רִבִּי פִּנְחָס, דְּאַנְתְּ זָכִית לְכָל הַאי, (דברי הימים א י״ב:י״ט) שָׁלוֹם לְךָ וְשָׁלוֹם לְעוֹזְרֶךָ כִּי עֲזָרְךָ אֱלֹהֶיךָ. אַשְׁכִּימוּ לְמֵיזַל, קָם רִבִּי פִּנְחָס וְאָחִיד בֵּיהּ בְּרִבִּי אֶלְעָזָר, וְלָא שַׁבְקֵיהּ לְמֵיהַךְ. אוֹזִיף רִבִּי פִּנְחָס לְרַבִּי שִׁמְעוֹן וּבַרְכֵיהּ, וּלְכֻלְּהוּ חַבְרַיָּיא. עַד דַּהֲווּ אַזְלֵי אָמַר לְהוּ רִבִּי שִׁמְעוֹן לְחַבְרַיָּיא, (תהילים קי״ט:קכ״ו) עֵת לַעֲשׂוֹת לַיְיָ'.</p>"],[9520012121,"<p>אָתָא רִבִּי אַבָּא וְשָׁאִיל, כְּתִיב וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גּוֹרָלוֹת וְגוֹ'. הָנֵי עַדְבִין לָמָּה. וְאַהֲרֹן לָמָּה לֵיהּ לְמֵיהַב עַדְבִין. וּפַרְשְׁתָּא דָּא לָמָּה. וְהָא אוֹלִיפְנָא קַמֵּי דְּמַר סִדְרָא דְּיוֹמָא, וְהַאי בְּעֵינָא לְמִנְדַּע.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית מ״ב:כ״ד) וַיִקַּח מֵאִתָּם אֶת שִׁמְעוֹן וַיֶּאֱסוֹר אוֹתוֹ לְעֵינֵיהֶם. וְכִי מַה חָמָא יוֹסֵף לְמֵיסַב לְשִׁמְעוֹן עִמֵּיהּ יַתִּיר מֵאֲחוֹהִי. אֶלָּא, אָמַר יוֹסֵף, בְכָל אֲתַר שִׁמְעוֹן (ולוי) פְּתִיחוּתָא דְּדִינָא אִיהוּ (אינון), וְהַהִיא שַׁעֲתָא דַּאֲזִילְנָא מֵאַבָּא לְגַבַּיְיהוּ דְּאֶחָי, שִׁמְעוֹן פָּתַח בְּקַדְמִיתָא בְּדִינָא, הֲדָא הוּא דִכְתִיב, (בראשית ל״ז:י״ט-כ׳) וַיֹּאמְרוּ אִישׁ אֶל אָחִיו הִנֵּה בַּעַל הַחֲלוֹמוֹת הַלָּזֶה בָּא וְעַתָּה לְכוּ וְגוֹ'. לְבָתַר בִשְׁכֶם, (בראשית ל״ד:כ״ה) וַיִּקְחוּ שְׁנֵי בְּנֵי יַעֲקֹב שִׁמְעוֹן וְלֵוִי, כֻּלְּהוּ בְּדִינָא הֲווֹ. טַב לְמֵיסַב דָּא, וְלָא יִתְּעַר קְטָטוּתָא בְּכֻלְּהוּ שְׁבָטִין.</p>\n<p>וְתָנֵינָן, מַאי קָא חָמָא שִׁמְעוֹן לְאִזְדַּוְּוגָא בְּלֵוִי יַתִּיר מִכֹּלָּא. וְהָא רְאוּבֵן הֲוָה אָחוּהָּ וְסָמִיךְ לֵיהּ, אֶלָּא שִׁמְעוֹן חָמָא וְיָדַע דְּלֵוִי מִסִּטְרָא דְּדִינָא קָא אָתֵי, וְשִׁמְעוֹן מִסִּטְרָא דְּדִינָא קַשְׁיָא יַתִּיר אִתְאֲחָד. אָמַר נִתְעֲרָב חַד בְּחַד וַאֲנָן נֶחֱרִיב עָלְמָא. מָה עָבֵד קוּדְשָׁא בְּרִיךְ הוּא, נָטַל לֵיהּ לְחוּלָקֵיהּ לְלֵוִי, אָמַר מִכָּאן וּלְהָלְאָה שִׁמְעוֹן לֵיתִיב בְּקוּפְטִירָא בַּהֲדֵּיהּ בִּלְחוֹדוֹי.</p>\n<p>תָּאנָא בְּסִטְרָא דְּאִימָא, תְּרֵין גַּרְדִּינֵי טְהִירִין (ס\"א תריסין) אִתְאַחֲדָן בִּידָא שְׂמָאלָא, וְהָא אוֹקִימְנָא דְּאִינּוּן מְאַלְלֵי אַרְעָא בְכָל יוֹמָא וְיוֹמָא, וְהַיְינוּ רָזָא דִּכְתִּיב, (יהושע ב׳:א׳) שְׁנַיִם אֲנָשִׁים מְרַגְּלִים.</p>\n<p>וְתָאנָא, זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל יַתִּיר מִכָּל עַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְדַכְּאָה לְהוּ, וּלְרַחֲמָא עָלַיְיהוּ, דְּאִינּוּן חוּלָקֵיהּ וְעַדְבֵיהּ, הֲדָא הוּא דִכְתִיב (דברים לב) כִּי חֵלֶק יְיָ' עַמּוֹ וְגוֹ', וּכְתִיב (דברים לב) יַרְכִּיבֵהוּ עַל בָּמֳתֵי אָרֶץ. עַל בָּמֳתֵי אָרֶץ דַּיְיקָא. דְּהָא אִינּוּן אִתְאַחֲדָן לְעֵילָּא לְעֵילָּא. וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא רְחִימוּתָא דִּילֵיהּ אִתְדְּבָק בְּהוּ, הֲדָא הוּא דִכְתִיב, (מלאכי א׳:ב׳) אָהַבְתִּי אֶתְכֶם אָמַר יְיָ', וּכְתִיב (דברים ז׳:ח׳) כִּי מֵאַהֲבַת יְיָ' אֶתְכֶם וְגוֹ', וּמִגּוֹ רְחִימוּתָא יַתִּירָא דְּרָחִים לְהוּ, יָהַב לוֹן יוֹמָא חַד בְּשַׁתָּא לְדַכְאָה לְהוּ, וּלְזַכָּאָה לְהוּ מִכָּל חוֹבֵיהוֹן, דִּכְתִּיב, (ויקרא טז) כִּי בַיּוֹם הַזֶּה וְגוֹ'. בְּגִין דִּיהוֹן זַכָּאִין בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, וְלָא יִשְׁתְּכַּח בְּהוּ חוֹבָא. וְעַל דָּא בְּיוֹמָא דָּא, מִתְעַטְּרִין יִשְׂרָאֵל, וְשַׁלְטִין עַל כֻּלְּהוּ גַּרְדִּינִין, וְעַל כֻּלְּהוּ טְהִירִין.</p>\n<p>תָּאנָא (ויקרא ט״ז:ח׳) וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גּוֹרָלוֹת. וְנָתַן אַהֲרֹן, בְּגִין דְּאָתֵי מִסִּטְרָא דְּחֶסֶד. עַל שְׁנֵי הַשְּׂעִירִים, עַל דַּיְיקָא, בְּגִין דְּתִתְבֲּסַם מַטְרוֹנִיתָא. גּוֹרָל אֶחָד לַיְיָ' וְגוֹרָל אֶחָד לַעֲזָאזֵל וְהָא תְּרֵין שְׂעִירִין אִינּוּן, אֲמַאי חַד לַיְיָ'. אֶלָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא, יֵתִיב הַאי גַּבָּאי, וְחַד יֵזִיל וְיִשׁוֹט בְּעָלְמָא, דְּאִלְמָלֵי תַּרְוַיְיהוּ מִזְדַּוְּוגָן, לָא יָכִיל עָלְמָא לְמִסְבַּל.</p>\n<p>נָפַק הַאי, אָזִיל וְשָׁאט בְּעָלְמָא, וְאַשְׁכַּח לְהוּ לְיִשְׂרָאֵל, בְּכַמָּה פּוּלְחָנִין, בְּכַמָּה דַּרְגִּין, בְּכַמָּה נִמוּסִין טָבָן, לָא יָכִיל לְהוּ, כֻּלְּהוּ שְׁלָמָא בֵּינַיְיהוּ, לָא יָכִיל לְמֵיעָל בְּהוּ בְּדַלְטוֹרָא. (אזל ושאט בעלמא, ואשכח לישראל כהאי גוונא) (נ\"א ישראל לתתא אוף הכי כהאי גוונא) הַאי שְׂעִירָא שַׁלְחִין לֵיהּ בְּמַטוּלָא דְּכָל חוֹבַיְיהוּ דְּיִשְׂרָאֵל.</p>\n<p>תָּאנָא, כַּמָה חֲבִילֵי טְרִיקִין מִזְדַּוְּוגָן (נ\"א מזדמנן), דְּאִינּוּן תְּחוֹת יְדֵיהּ, וּמְמָנָן לְאַלְלָא אַרְעָא, עַל כָּל אִינּוּן <Nonei></i>דְּעַבְרִין עַל פִּתְגָּמֵי אוֹרַיְיתָא. וְהַהוּא יוֹמָא, לָא שְׁכִיחַ דַּלְטּוֹרָא (ס\"א פטרא) לְמַלְּלָא בְּהוּ בְּיִשְׂרָאֵל. כַּד מָטָא הַאי שְׂעִירָא לְגַבֵּי טוּרָא, כַּמָה חֵידוּ עַל חֵידוּ מִתְבַסְּמִין כֻּלְּהוּ בֵּיהּ. וְהַהוּא גַרְדִינָא דְּנָפִיק, אַהְדָּר וְאָמַר תּוּשְׁבַּחְתָּא דְּיִשְׂרָאֵל, קַטֵיגוֹרָא אִתְעָבִיד סַנֵיגוֹרָא.</p>\n<p>וְתָּא חֲזֵי, לָאו דָּא בִּלְחוֹדוֹי הוּא, אֶלָּא בְּכָל אֲתַר דְּבַעְיָין יִשְׂרָאֵל לְאִתְדַכְּאָה מֵחוֹבַיְיהוּ, קוּדְשָׁא בְּרִיךְ הוּא יָהִיב לוֹן עֵיטָא לְקַשְּׁרָא מָארֵי דְּדִינָא, וּלְבַסְּמָא לְהוּ בְּאִינּוּן קָרְבְּנִין וְעִלָּוָון, דִּקְרֵבִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וּכְדֵין לָא יַכְלִין לְאַבְאָשָׁא. וְהַהוּא יוֹמָא יַתִּיר עַל כֹּלָּא, כְּמָה דְּמְבַסְּמִין יִשְׂרָאֵל לְתַתָּא לְכֹלָּא, הָכִי מְבַסְּמִין לְכָל אִינּוּן דְּאִית לְהוּ דַּלְטּוֹרָא (ס\"א פטרא) וְכֹלָּא קָרְבְּנָא הוּא וּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>תָּאנָא, בְּהַהִיא שַׁעֲתָא דִּכְתִּיב, וְלָקַח אַהֲרֹן אֶת שְׁנֵי הַשְּׂעִירִים וְגוֹ', מִתְעָרִין אִינּוּן בְּהַהוּא יוֹמָא לְעֵילָּא, וּבַעְיָין לְשַׁלְּטָאָה (נ\"א לשטאה) וּלְמֵיפָּק בְּעָלְמָא. כֵּיוָן דְּכַהֲנָא מְקָרֵב אִלֵּין לְתַתָּא, מִתְקָרְבִין אִינּוּן לְעֵילָּא. כְּדֵין עַדְבִין סַלְּקִין בְּכָל סִטְרִין, כַּהֲנָא יָהַב עַדְבִין לְתַתָּא, כַּהֲנָא יָהִיב עַדְבִין לְעֵילָּא. כְּמָה דְּחַד אִשְׁתְּאַר בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא לְתַתָּא. וְחַד אַפְּקִין לֵיהּ לְהַהוּא מַדְבְּרָא, הָכִי נָמֵי לְעֵילָּא, חָד אִשְׁתְּאַר בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְחַד נָפִיק וְשָׁט בְּעָלְמָא, לְהַהוּא מַדְבְּרָא עִלָּאָה, וְחַד בְּחַד מִתְקַשָּׁר.</p>\n<p>כְּתִיב (ויקרא ט״ז:כ״א) וְסָמַךְ אַהֲרֹן אֶת שְׁתֵּי יָדָיו עַל רֹאשׁ הַשָּׂעִיר הַחַי וְהִתְוַדָּה עָלָיו וְגוֹ'. בְּגִין כָּךְ וְסָמַךְ אַהֲרֹן אֶת שְׁתֵּי יָדָיו, דְּקוּדְשָׁא בְּרִיךְ הוּא יִסְתְּכַּם עַל יְדוֹי. עַל רֹאשׁ הַשָּׂעִיר הַחַי, הַחַי דַּיְיקָא, לְאַכְלְלָא הַהוּא דִּלְעֵילָּא.</p>\n<p>(ויקרא ה) וְהִתְוַדָּה עָלָיו אֶת כָּל עֲוֹנוֹת, כְּמָה דִּכְתִּיב (ויקרא ה׳:ה׳) וְהִתְוַדָּה אֲשֶׁר חָטָא עָלֶיהָ. וְאוֹקִימְנָא עָלֶיהָ, דְּאִתְדָכֵּי בַּר נָשׁ וְאִשְׁתְּאַר עָלֶיהָ כָּל הַהוּא חוֹבָא. אוּף הָכִי וְהִתְוַדָּה עָלָיו, בָּתַר דְּאוֹדֵי כַּהֲנָא בְּגִינַיְיהוּ דְּיִשְׂרָאֵל, עָלָיו: כְּלוֹמַר, יִשְׁתַּאֲרוּן כֻּלְּהוּ עָלָיו.</p>\n<p>אָמַר לֵיהּ רִבִּי אַבָּא, אִי הָכִי וְהָא כְּתִיב וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם לַשְּׂעִירִים, אָמַר לֵיהּ שָׁאנֵי הָכָא, דְּהָתָם לַשְּׂעִירִים הֲווֹ קְרֵבִין קָרְבְּנָא, וּבְגִין כָּךְ לָא כְּתִיב וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם שְׂעִירִים, אֶלָּא לַשְּׂעִירִים, דְּהָתָם לַשְּׂעִירִים הֲווֹ עַבְדֵּי פּוּלְחָנָא, וְשׁוּלְטָנוּתָא. וְהָכָא וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲוֹנוֹתָם, וְקָרְבְּנָא לָא אִתְעָבִיד אֶלָּא לְּקוּדְשָׁא בְּרִיךְ הוּא. תָּא חֲזֵי, דִּבְגִינֵי קָרְבְּנָא מִתְבַּסְּמָן עִלָּאִין וְתַתָּאִין, וְדִינָא לָא שַׁרְיָא וְשַׁלְטָא עָלַיְיהוּ דְּיִשְׂרָאֵל.</p>"],[9520012122,"<p>תָּאנָא, וְשִׁלַּח בְּיַד אִישׁ עִתִּי הַמִּדְבָּרָה. מַהוּ אִישׁ עִתִּי. אֶלָּא רָזָא דְּמִלָּה הָכִי הוּא <Nonei></i>בְּכָל מַה דְּאִתְעָבִיד, בָּעֵי בַּר נָשׁ זַמִּין לְהַהִיא מִלָּה. אִית בַּר נָשׁ דְּבִרְכְתָא אִתְקַיָּים עַל יְדֵיהּ יַתִּיר מֵאָחֳרָא. תָּא חֲזֵי, מַה כְּתִיב בֵּיהּ בְּכַהֲנָא, (משלי כ״ב:ט׳) טוֹב עַיִן הוּא יְבוֹרָךְ, אַל תִּקְרֵי יְבוֹרָךְ, אֶלָּא יְבָרֵךְ, בְּגִין דְּהוּא זַמִּין דְּיִתְקַיָּים בִּרְכָתָא עַל יְדֵיהּ בְּהַאי. (ס\"א ושארי ברכתא באשגחותא דיליה).</p>\n<p>וְאִית בַּר נָשׁ דְּהוּא זַמִּין לְאִתְקַיְּימָא לְוָוטִין עַל יְדֵיהּ, וּבְכָל מַה דְּיַשְׁגַח לֵיתֵי לְוָוטַיָיא וּמְאֵרָה וּבְעִיתָא כְּגוֹן בִּלְעָם, דְּאִקְרֵי רַע עַיִן, דְּהֲוָה זַמִּין בְּכָל בִּישׁ, וְלָא הֲוָה זַמִּין לְטָב. וְאַף עַל גַּב דִבְרָךְ, בִּרְכָתֵיהּ לָא בִּרְכָתָא, וְלָא אִתְקְיָּים. וְכַד הֲוָה לָיִיט, כָּל מַאן דְּלָיִיט אִתְקְיָּים, וְאַפִילּוּ בְּרִגְעָא חֲדָא, וְעַל דָּא כְּתִיב, (במדבר כ״ד:ג׳) שְׁתֻם הָעָיִן. בְּכָל אֲתַר דְּעֵינֵיהּ שַׁלְטָא אִתְלַטְּיָיא.</p>\n<p>תָּא חֲזֵי מַה כְּתִיב. (במדבר כ״ד:א׳) וַיָּשֶׁת אֶל הַמִּדְבָּר פָּנָיו, בְּגִין דְּיִתְעַר מֵהַהוּא סִטְרָא הַהוּא דְּשַׁלְטָא תַּמָּן, וְיֵיתֵי בְּדַלְטוֹרְיָא עָלַיְיהוּ דְּיִשְׂרָאֵל. מַה כְּתִיב בְּהוּ בְּכַהֲנֵי, (משלי כ״ב:ט׳) טוֹב עַיִן הוּא יְבוֹרָךְ, דְּהוּא הֲוָה זַמִּין בְּהַאי, וְשָׁארִי בִּרְכָתָא בְּאַשְׁגָּחוּתָא דִּילֵיהּ. וְעַל דָּא תָּנֵינָן, יִסְטֵי בַּר נָשׁ אֲפִילּוּ מִמֵּאָה אָרְחִין, וְלָא יִאְרַע בְּבַּר נָשׁ דְּאִית לֵיהּ עֵינָא בִּישָׁא.</p>\n<p>אוּף הָכָא וְשִׁלַּח בְּיַד אִישׁ עִתִּי, דְּהוּא זַמִּין לְהַאי. וְרָשִׁים לְהַאי, וְכַהֲנָא הֲוָה אִשְׁתְּמוֹדַע בֵּיהּ, חַד עֵינָא יַתִיר מֵאָחֳרָא פּוּרְתָא. סוּרְטָא דְּעַל עֵינָא אִתְחַפְּיָא בְּשַׂעֲרִין סַגִיאִין. מְכַּחֲלָא עֵינָא, וְלָא מִסְתָּכַּל בְּמֵישָׁר. הַאי הוּא בַּר נָשׁ זַמִּין לְהַאי, וְכַדְקָא חֲזֵי לֵיהּ. וְעַל דָּא כְּתִיב בְּיַד אִישׁ עִתִּי.</p>\n<p>בְּגוּשׁ חֲלָבָא הֲוָה בַּר נָשׁ, דִּבְכָל אֲתַר דְּמָחֵי בִּידוֹי, הֲוָה מִית, וְלָא הֲווֹ בְּנֵי נָשָׂא מְקָרְבִין בַּהֲדֵיהּ. בְּסוּרְיָּא הֲוָה בַּר נָשׁ, דִּבְכָל אֲתַר דְּאִסְתָּכַּל אֲפִילּוּ לְטָב, כֹּלָּא אִתְהַפָּךְ לְבִישׁ. יוֹמָא חַד הֲוָה חַד בַּר נָשׁ אָזִיל בְּשׁוּקָא, וַהֲווּ אַנְפּוֹי נְהִירִין. אָתָא הַהוּא בַּר נָשׁ וְאִסְתָּכַּל בֵּיהּ, וְאִתְבָּקַע עֵינֵיהּ. בְּגִין כָּךְ, בְּכֹלָּא הֲוָה בַּר נָשׁ זַמִּין, לְהַאי וּלְהַאי. וְעַל דָּא כְּתִיב טוֹב עַיִן הוּא יְבוֹרָךְ, אַל תִּקְרֵי יְבוֹרָךְ אֶלָּא יְבָרֵךְ.</p>\n<p>וְתָאנָא, הַאי בַּר נָשׁ דְּהֲוָה אָזִיל לְמַדְבְּרָא, כַּד מָטָא בֵּיהּ בְּהַהוּא שְׂעִירָא הֲוָה סָלִיק לְטוּרָא, וְדָחֵי לֵיהּ בִּתְרֵין יְדוֹי. וְלָא הֲוָה נָחִית לְפַלְגוּת טוּרָא, עַד דְּאִתְעָבִיד שַׁיְיפִין שַׁיְיפִין. וְהַהוּא בַּר נָשׁ הֲוָה אָמַר, כַּךְ יִמָּחוּ עֲוֹנוֹת עַמְּךָ וְגוֹ'. וּבְגִין דְּסָלִיק הַהוּא קַטֵיגוֹרְיָא וְאִתְעָבִיד סַנֵיגוֹרְיָא דְּיִשְׂרָאֵל, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא, כָּל חוֹבַיְיהוּ דְּיִשְׂרָאֵל, וְכָל מַה דִּכְתִיב בְּאִינּוּן פִּתְקִין דִּלְעֵילָּא, לְאַדְכְּרָא חוֹבַיְיהוּ דִּבְנֵי נָשָׁא, נָטִיל לוֹן וּרְמֵי לוֹן כְּהַאי גַּוְונָא, לַאֲתַר דְּאִתְקְרֵי מְצוּלוֹת יָם. הֲדָא הוּא דִכְתִיב, (מיכה ז׳:י״ט) וְתַשְׁלִיךְ בִּמְצוּלוֹת יָם כָּל חַטֹּאתָם.</p>"],[9520012123,"<p>תָּאנָא, (ויקרא ט״ז:ה׳) וּמֵאֵת עֲדַת בְּנֵי יִשְׂרָאֵל יִקַּח שְׁנֵי שְׂעִירֵי עִזִּים לְחַטָּאת, וּמֵאֵת עֲדַת, בְּגִין דִּיְהֵא מִכֻּלְּהוּ, וְיִתְכַּפֵּר לְכֻלְּהוּ. דְּהָא כָּל חוֹבַיְיהוּ דִּבְנֵי יִשְׂרָאֵל הָכָא תַּלְיָין, וְכֻלְּהוּ מִתְכַּפְּרֵי בְּדָא. <Nonei></i>וְלָא סָגֵי מִבַּר נָשׁ חַד. וּמֵאָן אֲתַר אִתְנְסִיבוּ מֵאִינּוּן קוּפִּין דְּבַעֲזָרָה נַטְלִין אַגְרָא, וְאַיְיתֵי לְהוּ מֵאִינּוּן דָּמֵי דַּהֲווֹ מִכֻּלְּהוּ.</p>\n<p>וְהַהוּא שְׂעִירָא אָחֳרָא, דְּהֲוָה אִשְׁתְּאַר לְּקוּדְשָׁא בְּרִיךְ הוּא, עַבְדִּין לֵיהּ חַטָּאת בְּקַדְמִיתָא. וְהָא אוֹקִימְנָא בְּאָן אֲתַר הֲוָה מִתְקַשְּׁרָא. וּלְבָתַר דָּא מִתְקָרְבִין הָנֵי, וּמִתְבַּסְּמִין כֹּלָּא, וְאִשְׁתָּאָרוּ יִשְׂרָאֵל זַכָּאִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, מִכָּל חוֹבִין דְּעָבְדוּ וְחָבוּ קָמֵיהּ. הֲדָא הוּא דִכְתִיב כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם וְגוֹ'.</p>\n<p>תּוּ אָמַר רִבִּי שִׁמְעוֹן, (בראשית כ״ז:י״א) וַיֹּאמֶר יַעֲקֹב אֶל רִבְקָה אִמּוֹ הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר וְאָנֹכִי אִישׁ חָלָק. מַאי קָא רְמִיזָא, אֶלָּא וַדַּאי עֵשָׂו אִישׁ שָׂעִיר, הוּא מֵהַהוּא דְּאִקְרֵי שָׂעִיר, דְּהָא מֵהַהוּא סִטְרָא אָתֵי. וְאָנֹכִי אִישׁ חָלָק: גְּבַר מֵהַהוּא דְּפָלִיג לְכָל שְׁאָר עַמִּין רַבְרְבִין מְמָנָן. דִּכְתִּיב, (דברים ד׳:י״ט) אֲשֶׁר חָלַק יְיָ' אֱלֹהֶיךָ אוֹתָם, וּכְתִיב (דברים לב) כִּי חֵלֶק יְיָ' עַמּוֹ וְגוֹ'. תּוּ אִישׁ חָלָק, מִתְּרֵי שְׂעִירִים וְאִשְׁתְּאַר חֲדָא. דְּכַהֲנָא פָּלִיג לֵהּ, חַד לְחוּלָקֵיהּ, וְחַד לְּקוּדְשָׁא בְּרִיךְ הוּא. אֲמַאי. בְּגִין דְּיַטְעִין עַל כַּתְפּוֹי כָּל חוֹבוֹי דְּיַעֲקֹב, דִּכְתִּיב וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲוֹנוֹתָם, עֲוֹנוֹת תָּם.</p>\n<p>תָּאנָא, בְּהַהוּא יוֹמָא כַּמָה פִּתְחִין פְּתִיחָן לָקֳבְלֵיהוֹן דְּיִשְׂרָאֵל לְקַבְּלָא צְלוֹתֵיהוֹן. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְזַכָּאָה לוֹן, וּלְדַכְּאָה לוֹן, הֲדָא הוּא דִכְתִיב כִּי בַיּוֹם הַזֶּה יְכַפֵּר וְגוֹ'. בְּהַאי יוֹמָא אִתְעֲטָּר כַּהֲנָא בְּכַמָּה עִטְרִין. בְּהַאי יוֹמָא פּוּלְחָנָא דְּכַהֲנָא יַקִּירָא וְרַב מִכָּל פּוּלְחָנִין. לְכֹלָּא יָהַב חוּלָקָא בְּאִינּוּן קָרְבְּנִין דְּקוּדְשָׁא בְּרִיךְ הוּא. בְּהַאי יוֹמָא אִתְעֲטָּר (ס\"א אתער) חֶסֶד בְּעָלְמָא עַל יְדָא דְּכַהֲנָא, מְקָרֵב קָרְבְּנִין עַל חוֹבֵיהוֹן דְּעַמָּא. עַל חוֹבֵיהּ בְּקַדְמִיתָא, וּלְבָתַר עַל חוֹבֵיהוֹן דְּעַמָּא. מְקָרֵב עִלָּוָון עָלֵיהּ וְעַל עַמָּא וְהָא אוֹקִימְנָא מִלֵּי.</p>"],[9520012124,"<p><Nonei></i><Noneb>רעיא מהימנא</b> פִּקּוּדָא (מ\"ד) דָּא, לְמִפְלַח רַבָּא כַּהֲנָא פּוּלְחָנָא דְּהַהוּא יוֹמָא כְּמָה דְּאִצְּטְרִיךְ, וּלְמִשְׁלַח שָׂעִיר לַעֲזָאזִל. רָזָא דָּא כְּמָה דְאַתְּ אָמֵר, בְּגִין לְאִתְפָּרְשָׁא מֵעַמָּא קַדִּישָׁא, וְלָא יִתְבַּע חוֹבֵיהוֹן קָמֵי מַלְכָּא. וְלָא יְקַטְרֵג עָלַיְיהוּ, דְּהָא לֵית לֵיהּ תְּקִיפוּ וְשׁוּלְטָנוּ, (בה) בַּר כַּד אִתָּקַף רוּגְזָא מִלְּעֵילָּא, וּבְהַהוּא דּוֹרוֹנָא אִתְהַפָּךְ לְבָתַר אַפּוֹטְרוֹפוֹסָא עָלַיְיהוּ, וְעַל דָּא אִתְדַּחְיָיא מִקַּמֵּי מַלְכָּא. וְהָא אוֹקִימְנָא, בְּגִין דְּאִיהוּ קֵץ כָּל בָּשָׂר.</p>\n<p>וְעַמָּא קַדִּישָׁא יָהֲבִין לֵיהּ כְּמָה דְּאִצְּטְרִיךְ לֵיהּ שָׂעִיר, וְרָזָא דָּא (בראשית כ״ז:י״א) הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר. כְּמָה דְּאִיהוּ בִּסְטָר דִּקְדוּשָּׁה דְּכַר וְנוּקְבָּא, אוּף הָכִי בִּסְטָר מְסָאֲבוּ דְּכַר וְנוּקְבָּא. מַתְלָא אַמְרֵי, לְכַלְבָּא אַרְמֵי לֵיהּ גַּרְמָא, יְלַחֵךְ עַפְרָא דְּרַגְלָךְ.</p>\n<p>שָׁאֲלוּ לְבֶן זוֹמָא, מַהוּ לְסָרוּסֵי כַּלְבָא. אָמַר לָהֶם, (ויקרא כ״ב:כ״ד) וּבְאַרְצְּכֶם לֹא תַּעֲשׂוּ, כָּל שֶׁבְּאַרְצְּכֶם לֹא תַּעֲשׂוּ. כְּמָה דְּאִצְּטְרִיךְ עָלְמָא לְהַאי, הָכִי אִצְּטְרִיךְ עָלְמָא לְהַאי. וְעַל דָּא אִתְּמַר, (בראשית א׳:ל״א) וְהִנֵּה טוֹב מְאֹד דָּא מַלְאָךְ הַמָּוְת. לֵית לְבַטְלָא לֵיהּ מִן עָלְמָא, עָלְמָא אִצְּטְרִיךְ לֵיהּ, אַף עַל גַּב דִּכְתִּיב בֵּיהּ, (ישעיהו נ״ו:י״א) וְהַכְּלָבִים עַזֵּי נֶפֶשׁ לֹא יָדְעוּ שָׂבְעָה וְגוֹ', לָא יִתְבַטְלוּן מִן עָלְמָא. כֹּלָּא אִצְּטְרִיךְ טוֹב וָרָע.</p>\n<p>וּבְגִּינֵי כַּךְ אִית לָן בְּיוֹמָא דָּא לְמִרְמֵי לֵיהּ גַּרְמָא לְכַלְבָּא, עַד דְּאִיהוּ גָּרִיר, יֵיעוּל מַאן דְּיֵיעוּל לְגַבֵּי הֵיכָלָא דְּמַלְכָּא, וְלֵית מַאן דְּיִמְחֵי בִּידוֹי. לְבָתַר <Nonei></i>יְכָשְׁכֵּשׁ לֵיהּ בִּזְנָבֵיהּ.</p>\n<p>מַה כְּתִיב וְהִתְוַדָּה עָלָיו אֶת כָּל עֲוֹנוֹת בְּנֵי יִשְׂרָאֵל, וּכְתִיב וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲוֹנוֹתָם. כֵּיוָן דְּאִיהוּ חָמֵי הַאי שָׂעִיר. תִּיאוּבְתֵּיהּ לְגַבֵּיהּ, וּלְאִשְׁתַּכְלְּלָא בַּהֲדֵּיהּ, וְלָא יָדַע מֵאִינּוּן חוֹבִין דְּקָא נָטִיל שָׂעִיר. תָּב לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, חָמֵי לוֹן בְּלָא חוֹבִין, בְּלָא פְּשָׁעִין, דְּהָא כֻּלְּהוּ שָׁרָאן בְּרֵישָׁא דְּשָעִיר, סָלִיק לְעֵילָּא, וְשַׁבַּח לוֹן קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. וְקוּדְשָׁא בְּרִיךְ הוּא חָמֵי סַהֲדוּתָא דְּהַהוּא מְקַטְרְגָא, וְהוֹאִיל וְתִיאוּבְתֵיהּ לְרַחֲמָא עַל עַמֵּיהּ, אַף עַל גַּב דְּאִיהוּ יָדַע כָּל עוֹבָדָא, חָס עֲלֵייהוֹן דְּיִשְׂרָאֵל.</p>\n<p>וְכֹלָּא שַׁרְיָא בְּדָא, בְּגִין דְּלָא יִתְּעַר רָזָא דְּדִינָא מִלְּעֵילָּא, וְיִתְּקַף הַאי וְיִשְׁתֵּצּוּן בְּנֵי עָלְמָא, דְּהָא דָּא מִסִּטְרָא דְּדִינָא קַשְׁיָא קָא אָתֵי. וְאִי יִתְּעַר הַאי, בְּחוֹבֵי בְּנֵי אֵינָשָׁא אִתְּעַר. דְּהָא לֵית לֵיהּ אַתְּעֲרוּ לְסַלְּקָא לְעֵילָּא לְאִתְּעָרָא דִּינָא קַשְׁיָא בַּר בְּדִיל חוֹבֵי בְּנֵי נָשָׁא. דְּהָא בְּשַׁעֲתָא דְּבַּר נָשׁ עָבִיד חוֹבָא, אִתְכְּנַשׁ הַאי, וְכַמָּה אֶלֶף סַיְיעָן דִּילֵיהּ, וּמִתְכַּנְּפֵי תַּמָּן, וְנַטְלֵי לֵיהּ, וְסַלְקֵי לְעֵילָּא רַחֲמָנָא לִישֵׁזְבָן. וְעַל כֹּלָּא יָהַב קוּדְשָׁא בְּרִיךְ הוּא עֵיטָא לְיִשְׂרָאֵל לְאִשְׁתְּזָבָא מִכָּל סִטְרִין. וְעַל דָּא כְּתִיב, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לוֹ אַשְׁרֵי הָעָם שֶׁיְיָ' אֱלֹהָיו. (ע\"כ רעיא מהימנא)</p>"],[9520012125,"<p><Nonei></i>עַד דַּהֲווֹ אָזְלֵי, יָתְבוּ בְּחַד חֲקַל, וְצַלּוּ. נָחַת חַד עֲנָנָא דְּאֶשָּׁא, וְאַסְחַר לוֹן. אָמַר רִבִּי שִׁמְעוֹן, הָא חֲמֵינָא דְּקוּדְשָׁא בְּרִיךְ הוּא רְעוּתָא דִּילֵיהּ הָכָא. נֵיתִיב. יָתְבוּ וַהֲווּ אַמְרֵי מִלֵּי דְּאוֹרַיְיתָא. פָּתַח וְאָמַר, (משלי כ״ה:כ״ה) מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק, הָא אִסְתַּכַּלְנָא בְּמִלּוֹי דִּשְׁלֹמֹה מַלְכָּא, וְכֻלְּהוּ (ס\"א בחכמתא) בְּחָכְמָה אַמָרָן.</p>\n<p>תָּא חֲזֵי ג' סִפְרִין דְּחָכְמְתָא אַפִּיק שְׁלֹמֹה לְעָלְמָא, וְכֻלְּהוּ בְּחָכְמְתָא עִלָּאָה. שִׁיר הַשִּׁירִים חָכְמָה, קֹהֶלֶת תְּבוּנָה, וּמִשְׁלֵי דַּעַת. לָקֳבֵל ג' אִלֵּין, עֲבַד ג' סְפָרִים. שִׁיר הַשִּׁירִים כְּנֶגֶד חָכְמָה הָכֵי הוּא. קֹהֶלֶת לְקָבֵל תְּבוּנָה, הָכֵי הוּא. מִשְׁלֵי לְקָבֵל דַעַת. בְּמָאי אִתְחֲזֵי. אֶלָּא כָל אִינּוּן קְרַאֵי בִּתְרֵי גְּוָונֵי אִינּוּן, רֵישָׁא וְסֵיפָא תְּרֵי גְּוָונֵי אִתְחַזְיָיא. וְכַד מִסְתַּכְּלֵי קְרַאֵי, דָא כְּלִיל בְּדָא, וְדָא כְּלִיל בְּדָא, בְּגִין כָּךְ שָׁקִיל לָקֳבְלֵיהּ דְּדַעַת.</p>\n<p>הַאי קְרָא לָאו רֵישֵׁיהּ סֵיפֵיהּ וְלָאו סֵיפֵיהּ רֵישֵׁיהּ. וְכַד אִסְתַּכַּלְנָא בֵּיהּ, כֹּלָּא כָּלִיל חַד בְּחַד, בֵּין מִסֵיפֵיהּ לְרֵישֵׁיהּ, בֵּין מֵרֵישֵׁיהּ לְסֵיפֵיהּ. שְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה. מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק, וְדָא וְדָא נַיְיחָא דְּרוּחָא, כְּמָה דְּהַאי נַיְיחָא דְּרוּחָא, כַּךְ הַאי נַיְיחָא דְּרוּחָא.</p>\n<p>עַד דַּהֲווֹ יַתְבֵי, אָתָא חַד בַּר נָשׁ, אָמַר, אִנְתּוּ דְּרִבִּי שִׁמְעוֹן אַתְּסִיאַת מִמַּרְעָהָא. וְחַבְרַיָּיא שָׁמְעוּ קָלָא, דְּקוּדְשָׁא בְּרִיךְ הוּא שָׁבַק לְאִינּוּן חוֹבֵי דְּדָרָא. אָמַר רִבִּי שִׁמְעוֹן, הָא אִתְקַיָּים הָכָא קְרָא, וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק, הָכִי הוּא נַיְיחָא דְּרוּחָא, כְּמוֹ מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה. אָמַר לְהוּ נְקוּם וְנֵזִיל דְּקוּדְשָׁא בְּרִיךְ הוּא אַרְחִישׁ לָן בְּנִסִּין.</p>\n<p>פָּתַח וְאָמַר, מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה, דָּא אוֹרַיְיתָא. דְּכָל מַאן דְּזָכֵי לְמִלְעֵי בְּאוֹרַיְיתָא, וּמְרַוִי נַפְשָׁא מִנָּהּ, מַה כְּתִיב וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק. קוּדְשָׁא בְּרִיךְ הוּא אַכְרִיז עָלֵיהּ כַּמָה טָבָאן לְאוֹטָבָא לֵיהּ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי. הֲדָא הוּא דִכְתִיב, וּשְׁמוּעָה טוֹבָה, מַאן אֲתַר מֵאֶרֶץ מֶרְחָק, מֵאֲתַר דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה רָחִיק מִנֵּיהּ בְּקַדְמִיתָא, מֵאֲתַר דְּהֲוָה בַּר נָשׁ בִּדְבָבוּ עִמֵּיהּ בְּקַדְמִיתָא, דִּכְתִּיב, (איוב כ׳:כ״ז) וְאֶרֶץ מִתְקוֹמָמָה לוֹ, מֵהַהוּא אֲתַר <Nonei></i>מַקְדִּימִין לֵיהּ שְׁלָם, הֲדָא הוּא דִכְתִיב, מֵאֶרֶץ מֶרְחָק. וּכְתִיב (ירמיהו ל״א:ג׳) מֵרָחוֹק יְיָ' נִרְאָה לִי וְאַהֲבַת עוֹלָם אַהֲבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד.</p>"],[9520012126,"<p>(כאן חסר) (ויקרא ט״ז:י״ח) וְיָצָא אֶל הַמִּזְבֵּחַ אֲשֶׁר לִפְנֵי יְיָ' וְכִפֶּר עָלָיו. רִבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים נ׳:א׳) מִזְמוֹר לְאָסָף אֵל אֱלֹהִים יְיָ' דִּבֵּר וַיִּקְרָא אָרֶץ מִמִּזְרָח שֶׁמֶשׁ עַד מְבוֹאוֹ. תָּאנָא, אֶלֶף וַחֲמֵשׁ מְאָה וְחַמְשִׁין רִבּוֹא מָארֵי שִׁירָתָא, מְזַמְּרִין לְּקוּדְשָׁא בְּרִיךְ הוּא, כַּד נָהִיר יְמָמָא. וְאֶלֶף וַחֲמֵשׁ מְאָה וְאַרְבְּעִין וּתְמַנְיָא בְּטִיהֲרָא. וְאֶלֶף וַחֲמֵשׁ מְאָה וְתִשְׁעִין אֶלֶף רִבּוֹא בְּהַהִיא שַׁעֲתָא דְּאִקְרֵי בֵּין הָעַרְבַּיִם.</p>\n<p>רִבִּי יוֹסֵי אָמַר, כַּד נָהִיר יְמָמָא, כָּל אִינּוּן מָארֵי דִּיבָבָא, מְשַׁבְּחָן בְּמִלֵי תּוּשְׁבְּחָן, לָקֳבְלֵיהּ דְּהַאי בֹּקֶר. (ס\"א כד אתער, דכד) דְּכַד אִתְּעַר הַאי בֹּקֶר, כֻּלְּהוּ מִתְבַסְּמִין, וְדִינָא אִשְׁתְּכִיךְ, וְאָמְרִין תּוּשְׁבְּחָן. הֲדָא הוּא דִכְתִיב, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. וְהַהוּא זִמְנָא, (הימנותא) חֶדְוָותָא וּבִרְכָּאן מִשְׁתַּכְּחִין בְּעָלְמָא, וְקוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר לְאַבְרָהָם לְאַחֲיָיא לֵיהּ, וְאִשְׁתַּעֲשַׁע בֵּיהּ, וְאַשְׁלְטֵיהּ בְּעָלְמָא. וּמְנָא לָן דְּהַאי בֹּקֶר דְּאַבְרָהָם הוּא. דִּכְתִיב (בראשית י״ט:כ״ז) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר.</p>\n<p>בְּהַהוּא זִמְנָא דְּבֵין הָעַרְבָּיִם, כָּל אִינּוּן אֶלֶף וַחֲמֵשׁ מְאָה וְתִשְׁעִין אֶלֶף רִבּוֹא מָארֵי דִּילָלָה אִקְרוּן, וּמְזַמְּרִין בְּהַהִיא שַׁעֲתָא, וּקְטָטוּתָא שַׁרְיָא בְּעָלְמָא, וְהַהִיא שַׁעֲתָא אִתְּעָרוּתָא דְּאִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא לְיִצְחָק, וְקָם וְדָאִין לְחַיָּיבַיָּא דְּעַבְרִין עַל פִּתְגָּמֵי אוֹרַיְיתָא, וְשִׁבְעָה נַהֲרֵי אֶשָּׁא נַגְדִּין וְנָפְקִין וְחָלִין עַל רֵישֵׁיהוֹן דְּרַשִׁיעַיָּיא, וְשַׁלְהוֹבֵי גּוּמְרִין דְּנוּרָא מִתְעָרִין מֵעֵילָּא לְתַתָּא, וּכְדֵין תָּב אַבְרָהָם לְאַתְרֵיהּ. כְּמָה דְאַתְּ אָמֵר, (בראשית י״ח:ל״ג) וְאַבְרָהָם שָׁב לִמְקוֹמוֹ. וְיוֹמָא אִתְפְּנֵי, וְחַיָּיבֵי גֵּיהִנָּם צַוְוחִין וְאַמְרִין (ירמיהו ו׳:ד׳) אוֹי לָנוּ כִּי פָּנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. וְהַהִיא שַׁעֲתָא, בָּעֵי בַּר נָשׁ לְאִזְדַּהֲרָא, בִּצְלוֹתָא דְּמִנְחָה.</p>\n<p>בְּזִמְנָא דְּמָטֵי לֵילְיָא אִינּוּן אֶלֶף וְה' מְאָה וְאַרְבְּעִין וּתְמַנְיָא, אִקְרוּן מִבָּרָא לְפָרוֹכְתָּא, וְאָמְרִין שִׁירָתָא. כְּדֵין דִּינִין דִּלְתַתָּא מִתְעָרִין, וְאָזְלִין וְשָׁאטִין בְּעָלְמָא, וְאִלֵּין אַמְרִין שִׁירָתָא. עַד דְּיִתְפְּלִיג לֵילְיָא מִשְׁמָרָה וּפַלְגָּא. בָּתַר דְּיִתְפְּלִיג לֵילְיָא מִזְדַמְנֵי כֻּלְּהוּ אַחֲרִינֵי כַּחֲדָא, וְאַמְרֵי תְּהִלּוֹת, כְּמָה דְאַתְּ אָמֵר (ישעיה ס) וּתְהִלּוֹת יְיָ' יְבַשֵּׂרוּ. רִבִּי יְהוּדָה אָמַר כַּד רַעֲוָא אִשְׁתְּכַח בְּצַפְרָא, תְּהִלּוֹת יְיָ' מְבַשְּׂרִין.</p>\n<p>רִבִּי יוֹסֵי אָמַר, בָּתַר דְּרוּחָא דְּצָפוֹן אִתְּעַר בְּפַלְגוּת לֵילְיָא וְאָזִיל לֵיהּ, תְּהִלּוֹת מְבַשְּׂרֵי, עַד דְּיֵיתֵי צַפְרָא, וְאִתְּעַר הַאי בֹּקֶר, כְּדֵין חֶדְוָותָא וּבִרְכָּאן אִשְׁתְּכַח בְּעָלְמָא.</p>\n<p>תָּאנָא, אָמַר רִבִּי אַבָּא, כֻּלְּהוּ הָכִי, וְעֵילָּא מִנְּהוֹן סַרְכִין תְּלָתָא. בְּהַהִיא שַׁעֲתָא דְּאִתְּעַר הַאי בֹּקֶר, וּמִתְעָרִין תּוּשְׁבְּחָן, כָּל אִינּוּן אֶלֶף וַחֲמֵשׁ מְאָה וְחַמְשִׁין רִבּוֹא, אִתְמָנָא עָלַיְיהוּ חַד מְמָנָא, וְהֵימָן שְׁמֵיהּ לָקֳבְלֵיה דִּלְתַתָּא, וּתְחוֹת יְדֵיהּ סַרְכִין מְמָנָן עָלַיְיהוּ לְאַתְקְנָא שִׁירָתָא.</p>\n<p>בְּהַהִיא שַׁעֲתָא דְּאִתְּעַר זִמְנָא דְּבֵין הָעַרְבַּיִם, וְזַמְרִין כָּל אִינּוּן אֶלֶף וַחֲמֵשׁ מְאָה וְתִשְׁעִין אֶלֶף רִבּוֹא מָארֵי דִּילָלָה, אִתְמָנָא עָלַיְיהוּ חַד מְמָנָא וִידוּתוּן שְׁמֵיהּ, לָקֳבְלֵיהּ דִּלְתַתָּא, וּתְחוֹת יְדֵיהּ סַרְכִין מְמָנָן עָלַיְיהוּ, לְאַתְקְנָא הַהוּא זִמְרָא, כְּמָה דְאַתְּ אָמֵר (ישעיהו כ״ה:ה׳) זְמִיר עָרִיצִים.</p>\n<p>בְּהַהִיא שַׁעֲתָא דְּמָטֵי לֵילְיָא, מִתְעָרִין כָּל אִינּוּן דְּמִבָּרָא לְפָרוֹכְתָּא, כְּדֵין שָׁכִיךְ כֹּלָּא, וּפִטְרָא לָא אִשְׁתְּכַח, וְדִינִין דִּלְתַּתָּא מִתְעָרִין, כֻּלְּהוּ אִתְמָנָן כַּחֲדָא, אִלֵּין עַל אִלֵּין, עַד דְּאִתְפְּלִיג לֵילְיָא. בָּתַר דְּאִתְפְּלִיג לֵילְיָא, וּמִתְכַּנְּשֵׁי כֻּלְּהוּ, אִתְמָנָא עָלַיְיהוּ חַד מְמָנָא וְכָנִישׁ לְכָל מַשִּׁרְיָין, כְּמָה דְאַתְּ אָמֵר (במדבר י׳:כ״ה) מְאַסֵּף לְכָל הַמַּחֲנוֹת וְגוֹ', וְאָסָף שְׁמֵיהּ, לָקֳבְלֵיהּ דִּלְתַתָּא, וּתְחוֹת יְדֵיהּ כָּל אִינּוּן סַרְכִין מְמָנָן, וּמְבַשְּׂרֵי תְּהִלּוֹת.</p>\n<p>עַד דְּאָתֵי צַפְרָא, כֵּיוָן דְּאָתֵי צַפְרָא, קָם הַהוּא נַעַ\"ר, יוֹנֵק מִשְּׁדֵי אִמֵּיהּ, לְדַכְּאָה לְהוּ, וְעָאל לְשַׁמְּשָׁא. כַּד אִתְּעַר בֹּקֶר, כְּדֵין הִיא שַׁעֲתָא דְּרַעֲוָא, דְּאִשְׁתָּעֵי מַטְרוֹנִיתָא בְּמַלְכָּא, וּמַלְכָּא מָשִׁיךְ מִנֵּיהּ חַד <Nonei></i>חוּטָא דְּבִרְכָּאן וּפָרִיס עַל מַטְרוֹנִיתָא, וְעַל אִינּוּן דְּמִזְדַוְּוגֵי לֵהּ. מַאן אִינּוּן דְּמִזְדַוְּוגֵי עִמֵּהּ. אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא בְּלֵילְיָא, כַּד אִתְפְּלַג.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, זַכָּאָה חוּלָקֵיהּ מַאן דְּאָתֵי עִם מַטְרוֹנִיתָא, בְּשַׁעֲתָא דְּאָתַת לְקַבְּלָא אַנְפֵּי מַלְכָּא, לְאִשְׁתָּעֵי בֵּיהּ. וְאִשְׁתְּכַח עִמָּהּ. בְּשַׁעֲתָא דְּאוֹשִׁיט מַלְכָּא יְמִינָא, לְקַבְּלָא לְמַטְרוֹנִיתָא. הֲדָא הוּא דִכְתִיב, (תהילים קל״ט:ט׳) אֶשָּׂא כַּנְפֵי שָׁחַר אֶשְׁכְּנָה בְּאַחֲרִית יָם. מַאי אַחֲרִית יָם. הַהִיא שַׁעֲתָא אַחֲרִית דְּהַהוּא יַם הוּא. דְּכַד אִתְפְּלַג, שֵׁירוּתָא הֲוָה, וְדִינָא הֲוָה, וְהַשְׁתָּא אַחֲרִית הוּא דִּילָהּ, דְּמִסְתַּלְּקִין דִּינָהָא. וְעָאלַת בְּגַדְפּוֹי דְּמַלְכָּא, הִיא וְכָל אִינּוּן דְּמִזְדַּוְּוגִין לֵהּ, הֲדָא הוּא דִכְתִיב אֶשְׁכְּנָה בְּאַחֲרִית יָם.</p>\n<p>וְתָאנָא, כָּל אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא בְּשַׁעֲתָא דְּאִתְפְּלִיג לֵילְיָא. אִשְׁתְּתַּף בִּשְׁכִינְתָּא. וְכַד אָתֵי צַפְרָא, וּמַטְרוֹנִיתָא אִתְחַבְּרַת עִם מַלְכָּא, הוּא אִשְׁתְּכַח עִמָּהּ עִם מַלְכָּא. וּמַלְכָּא פְּרֵיס עַל כֻּלְּהוּ גַּדְפּוֹי, הֲדָא הוּא דִכְתִיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוְּה יְיָ' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי וְגוֹ'.</p>\n<p>תָּאנָא, בְּהַהִיא שַׁעֲתָא, אֲבָהָן מִזְדַּמְּנִין בְּמַטְרוֹנִיתָא, וְקַדְּמִין לְאִשְׁתָּעֵי בַּהֲדָהּ, וּלְאִתְחַבְּרָא עִמָּהּ. וְקוּדְשָׁא בְּרִיךְ הוּא מַלִּיל עִמָּהּ בְּהוּ. וְהוּא קָארֵי לָהּ לְפָרְסָא לָהּ גַּדְפּוֹי, הֲדָא הוּא דִכְתִיב, (תהילים נ׳:א׳) מִזְמוֹר לְאָסָף אֵל אֱלֹהִים יְיָ' דִּבֶּר וַיִקְרָא אָרֶץ וְגוֹ'. אֵל: דָּא נְהִירוּ דְּחָכְמְתָא, וְאִקְרֵי חֶסֶד. אֱלֹהִים: דָּא גְּבוּרָה. יְדִֹוִ\"ד: דָא שְׁלִימוּ דְּכַלָּא, רַחֲמֵי. וְעַל דָא, דִּבֶּר וַיִקְרָא אָרֶץ וְגוֹ'.</p>"],[9520012127,"<p>רִבִּי אֶלְעָזָר הֲוָה יָתִיב קָמֵיהּ דְּרַבִּי שִׁמְעוֹן אֲבוֹי, אָמַר לֵיהּ, הָא תָּנֵינָן אֱלֹהִים בְּכָל אֲתַר דִּינָא הוּא. יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. אִית אֲתַר דְּאִקְרֵי אֱלֹהִים, כְּגוֹן (בראשית טו) אֲדֹנָ\"י יִהוְֹ\"ה. אֲמַאי אִקְרֵי אֱלֹהִים, וְהָא אַתְוָון רַחֲמֵי אִינּוּן בְּכָל אֲתַר.</p>\n<p>אָמַר לֵיהּ, הָכִי הוּא כְּתִיב בַּקְּרָא, דִּכְתִּיב, (דברים ד׳:ל״ט) וְיָדַעְתָּ הַיּוֹם וְהֲשֵׁבוֹתָ אֶל לְבָבֶךָ כִּי יְיָ' הוּא הָאֱלֹהִים, וּכְתִיב (מלכים א י״ח:ל״ט-מ׳) יְיָ' הוּא הָאֱלֹהִים. אָמַר לֵיהּ מִלָּה דָּא יְדַעְנָא, דְּבַאֲתַר דְּאִית דִּינָא, אִית רַחֲמֵי. וּלְזִמְנָא, בַּאֲתַר דְּאִית רַחֲמֵי, אִית דִּינָא, אָמַר לֵיהּ תָּא חַזֵי דְּהָכִי הוּא, יְדוָֹ\"ד בְּכָל אֲתַר רַחֲמֵי. וּבְשַׁעֲתָא דִּמְהַפְּכֵי חַיָּיבַיָּא רַחֲמֵי לְדִינָא, כְּדֵין כְּתִיב יִהוְֹ\"ה, וְקָרֵינָן לֵיהּ אֱלֹהִים.</p>\n<p>אֲבָל תָּא חֲזֵי רָזָא דְּמִלָּה, ג' דַּרְגִּין אִינּוּן, וְכָל דַּרְגָּא וְדַרְגָּא בִּלְחוֹדוֹי, וְאַף עַל גַּב דְּכֹלָּא חַד, וּמִתְקַשְּׁרֵי בְּחַד, וְלָא מִתְפָּרְשֵׁי דָּא מִן דָּא. תָּא חֲזֵי, כֻּלְּהוּ נְטִיעָן, וְכָל אִינּוּן בּוּצִינִין דְּמִתְלַהֲטִין כֻּלְּהוּ נְהִירִין וּמִתְלַהֲטָן וּמִשְׁתַקְיָין וּמִתְבָּרְכָאן, מֵהַהוּא נַהֲרָא דְּנָגִיד וְנָפִיק, דְּכֹלָּא כָּלִיל בֵּיהּ, (תרי נוסחי) וּכְלָלָא דְּכֹלָּא בֵּיהּ.</p>\n<p>וְהַאי נַהֲרָא אִתְקְרֵי אֵ\"ם לְגִנְתָּא, וְעֵילָּא מִגִּנְתָּא, בְּגִין דְּעֵדֶן מִשְׁתַּתֵּף בַּהֲדָהּ, וְלָא פָּרִישׁ (ס\"א ע\"ב) מִנָּהּ. וּבְגִין כַּךְ, כָּל מַבּוּעִין נָפְקִין וְנַגְדִּין וְאִשְׁתַקְיָין לְכָל עִיבָר. וּפַתְחִין בָּהּ פְּתִיחָן, וְעַל דָּא רַחֲמֵי מִנָּהּ מִשְׁתַּכְּחִין, וְרַחֲמִין פְּתִיחִין בָּהּ.</p>\n<p>וּבְגִין דְּקָרֵינָן לָהּ אֵם, נוּקְבָּא גְּבוּרָה, וְדִינָא מִנָּהּ נָפִיק. אִקְרֵי רַחֲמֵי בִּלְחוֹדָהָא, הָא מִסִּטְרָהָא דִּינִין מִתְעָרִין. וּבְגִין כַּךְ כְּתִיב בְּרַחֲמֵי, וְנָקוּד בְּדִינָא. אַתְוָון בְּרַחֲמֵי, וְאִתְנְגִיד דִּינָא מִסִּטְרָהָא, כְּגַוְונָא דָּא יְהֶ\"וִֹה, הַאי דַּרְגָּא חַד.</p>\n<p>דַּרְגָּא תִּנְיָינָא, מִסִּטְרָא דְּהַאי קַדְמָאָה, נָפִיק וְאִתְּעַר דַּרְגָּא אָחֳרָא אִקְרֵי גְּבוּרָה, וְהַאי אִקְרֵי אֱלֹהִים, בְּאִלֵּין אַתְוָון מַמָּשׁ. וְשִׁירוּתָא (חד) מִזְּעֵיר אַנְפִּין הוּא, וּבֵיהּ אִתְאֲחִיד. וּבְגִין דְּאִתְאֲחִיד (האי) בְּהַאי, כְּתִיב יְיָ' הָאֱלֹהִים, כִּי יְיָ' הוּא הָאֱלֹהִים, בְּאִלֵּין אַתְוָון, וְהוּא חַד, וְדָא הוּא דַּרְגָּא תִּנְיָינָא.</p>\n<p>דַּרְגָּא תְּלִיתָאָה, צֶדֶק. כִּתְרָא בַּתְרָאָה, הַאי בֵּי דִּינָא דְּמַלְכָּא. וְתָאנָא אֲדֹנָ\"י הָכִי כְּתִיב, וְהָכִי אִקְרֵי, וּכְּנֶסֶת יִשְׂרָאֵל בְּהַאי שְׁמָא אִתְקְרֵי. וְהַאי שְׁמָא בַּאֲתַר דָּא אִשְׁתְּלִים. וְאִלֵּין אִינּוּן ג' דַּרְגִּין, דְּאִקְרוּן בִּשְׁמֵהוֹן דְּדִינָא. וְכֹלָּא מִתְקַשָּׁר חַד בְּחַד בְּלָא פִּרוּדָא, כְּמָה דְּאוֹקִימְנָא.</p>"],[9520012128,"<p>אָמַר לֵיהּ, אִי נִיחָא קַמֵּיהּ דְּאַבָּא, הָא שְׁמַעְנָא בְּהַאי, (ח\"י ע\"א) דִּכְתִּיב, (שמות ג׳:י״ד) אֶהְיֶה אֲשֶׁר אֶהְיֶה, וְלָא קַיְימָא בֵּיהּ. אָמַר לֵיהּ אֶלְעָזָר בְּרִי, הָא אוֹקְמוּהָ חַבְרַיָּיא, וְהַשְׁתָּא בְּחַד מִלָּה אִתְקְשַׁר כֹּלָּא.</p>\n<p><Nonei></i>וְרָזָא דְּמִלָּה הָכִי הוּא. אֶהְיֶה, דָּא כְּלָלָא דְּכֹלָּא. דְּכַד שְׁבִילִין סְתִימִין וְלָא מִתְפָּרְשָׁן, וּכְלִילָן בְּחַד אֲתַר. כְּדֵין אִקְרֵי אֶהְיֶה, כְּלָלָא כֹּלָּא, סָתִים וְלָא אִתְגַּלְיָיא.</p>\n<p>בָּתַר דְּנָפַק מִנֵּיהּ שֵׁירוּתָא, וְהַהוּא נָהָר אִתְעַבָּר לְאַמְשָׁכָא כֹּלָּא, כְּדֵין אִקְרֵי אֲשֶׁר אֶהְיֶה. כְּלוֹמַר, עַל כֵּן אֶהְיֶה, אֶהְיֶה זַמִּין לְאַמְשָׁכָא וּלְאוֹלָדָא כֹּלָּא. אֶהְיֶה: כְּלוֹמַר, הַשְׁתָּא אֲנָא הוּא כְּלַל כֹּלָּא, כְּלָלָא דְּכָל פְּרָטָא. אֲשֶׁר אֶהְיֶה: דְּאִתְעַבְּרַת אִימָּא, וְזַמִינַת לְאַפָּקָא פְּרָטִין כֻּלְּהוּ, וּלְאִתְגַּלְיָיא שְּׁמָא עִלָּאָה.</p>\n<p>לְבָתַר בָּעָא מֹשֶׁה לְמִנְדַּע פְּרָטָא דְּמִלָּה מַאן הוּא, עַד דְּפָרִישׁ וְאָמַר אֶהְיֶה (ס\"א יהוה), דָּא הוּא פְּרָטָא, וְהָכָא לָא כְּתִיב אֲשֶׁר אֶהְיֶה. (ויחי קל\"ה) וְאַשְׁכַּחְנָא בְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא, אֲשֶׁר: בְּקִיטוּרָא דְּעִדּוּנָא קַסְטִירָא בְּחַבְרוּתָא עִלָּאָה אִשְׁתְּכַח. כְּמָה דְאַתְּ אָמֵר, (בראשית ל׳:י״ג) בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת, אֶהְיֶה זְמִינָא לְאוֹלָדָא.</p>\n<p>תָּא חֲזֵי הֵיךְ נָחִית מִדַּרְגָּא לְדַרְגָּא, לְאוֹדָעָא רָזָא דִּשְׁמָא קַדִּישָׁא (לאחזאה קודשא בריך הוא) לְמֹשֶׁה. בְּקַדְמִיתָא אֶהְיֶה, כְּלָלָא דְּכֹלָּא, סָתִים דְּלָא אִתְגַּלְיָיא כְּלַל, כְּמָה דַּאֲמֵינָא. וְסִימָן, (משלי ח׳:ל׳) וָאֶהְיֶה אֶצְלוֹ אָמוֹן וְגוֹ', וּכְתִיב (איוב כ״ח:י״ג) לֹא יָדַע אֱנוֹשׁ עֶרְכָּהּ וְגוֹ'. לְבָתַר אַפִּיק (רזא דשירותא עילאה, ראשיתא דכלא ו) הַהוּא נַהֲרָא, אִימָּא עִלָּאָה, אִתְעַבְּרַת, וּזְמִינָא לְאוֹלָדָא. וְאָמַר אֲשֶׁר אֶהְיֶה, זְמִינָא לְאוֹלָדָא, וּלְתַקְּנָא כֹּלָּא. לְבָתַר שָׁארֵי לְאוֹלָדָא, וְלָא כְּתִיב אֲשֶׁר, אֶלָּא אֶהְיֶה: כְּלוֹמַר, הַשְׁתָּא יָפִיק וְיִתְתָּקַן כֹּלָּא.</p>\n<p>בָּתַר דְּנָפִיק כֹּלָּא, וְאִתְתָּקַּן כָּל חַד וְחַד בְּאַתְרֵיהּ, שָׁבַק כֹּלָּא, וְאָמַר יְהוָֹ\"ה. דָּא פְּרָטָא, וְדָא קִיוּמָא. וּבְהַהִיא שַׁעֲתָא יָדַע מֹשֶׁה, רָזָא דִּשְׁמָא קַדִּישָׁא, סָתִים וְגַלְיָא וְאִתְדַּבָּק מַה דְּלָא אִתְדָּבָקוּ שְׁאָר בְּנֵי עָלְמָא, זַכָּאָה חוּלָקֵיהּ. אָתָא רִבִּי אֶלְעָזָר וְנָשִׁיק יְדוֹי.</p>"],[9520012129,"<p>אָמַר לֵיהּ, אֶלְעָזָר בְּרִי, מִכָּאן וּלְהָלְאָה, אִזְדְּהַר דְּלָא לְמִכְתַּב שְׁמָא קַדִּישָׁא, אֶלָּא כְּדְקָא יֵאוֹת. דְּכָל מַאן דְּלָא יָדַע לְמִכְתַּב שְׁמָא קַדִּישָׁא כְּדְקָא יֵאוֹת, וּלְקַשְּׁרָא קִשְׁרָא דִּמְהֵימְנוּתָא קִשְׁרָא דְּחַד בְּחַד, בְּגִין לְיַחֲדָא שְׁמָא קַדִּישָׁא. עָלֵיהּ כְּתִיב, (במדבר ט״ו:ל״א) כִּי דְּבַר יְיָ' בָּזָה וְאֶת מִצְוָתוֹ הֵפַר הִכָּרֵת תִּכָּרֵת וְגוֹ'. אֲפִילּוּ דְּגָרַע חַד דַּרְגָּא, אוֹ חַד קִשְׁרָא, מֵאָת חַד מִנַּיְיהוּ.</p>\n<p>תָּא חֲזֵי, י' בְּקַדְמִיתָא, כְּלָלָא דְּכֹלָּא, סָתִים מִכָּל סִטְרִין, שְׁבִילִין לָא מִתְפַתְּחִין, כְּלָלָא דִּדְכַר וְנוּקְבָּא. קוֹצָא דְּיוֹ\"ד דִּלְעֵילָּא, רְמִיזָא לְאַיִן. לְבָתַר, י' דְּאַפִּיק הַהוּא נַהֲרָא דְּנָגִיד וְנָפִיק מִנֵיהּ, וּלְאִתְעַבְּרָא מִנֵּיהּ ה', בְּהַאי כְּתִיב (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן. (שמות פ\"ג ע\"א) יוֹצֵא וְלָא יָצָא. בְּגִין כָּךְ לָא בַּעְיָא לְאִתְפָּרְשָׁא מִנֵיהּ. וּבְגִין כָּךְ כְּתִיב רַעְיָתִי.</p>\n<p>וְאִי תֵּימָא נָהָר כְּתִיב, מַשְׁמַע חַד, וְהָא הָכָא ג'. הָכִי הוּא ודַּאי, י' אַפִּיק תְּלָתָא, וּבִתְלָתָא אִתְכְּלַל כֹּלָּא. י' אַפִּיק לְקַמֵּיהּ הַהוּא נָהָר, וּתְרֵין בְּנִין דְּיַנְקָא לְהוּ אִימָּא, וְאִתְעַבְּרַת מִנַּיְיהוּ, וְאַפִּיק לוֹן לְבָתַר. ה': כְּגַוְונָא דָּא ה', וְאִינּוּן בְּנִין תְּחוֹת אַבָּא וְאִימָא.</p>\n<p>בָּתַר דְּאוֹלִידַת, אַפִּיקַת בֶּן דְּכַר, וְשַׁוְיֵיהּ לְקַמָּהּ, וּבָעֵי לְמִכְתַּב ו', וְהַאי יָרִית אַחֲסַנְתָּא דְּאַבָּא וְאִימָא, וְיָרִית תְּרֵין חוּלָקִין, וּמִנֵּיהּ אִתְּזָן בְּרָתָא. וְעַל דָּא, בָּעֵי לְמִכְתַּב לְבָתַר, ו\"ה כַּחֲדָא כְּמָה דְּהֵ\"א קַדְמָאָה י\"ה כַּחֲדָא, וְלָא בָּעֵי לְאַפְרְשָׁא לוֹן, אוּף הָכָא ו\"ה כַּחֲדָא, וְלָא בָּעֵי לְאַפְרְשָׁא לוֹן. וְהָא אוֹקִימְנָא מִלֵּי. וְלַאֲתַר אָחֳרָא סַלְּקִין הָנֵי מִלֵי. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, דְּיַדְעִין רָזִין עִלָּאִין דְּמַלְכָּא קַדִּישָׁא, וְיִתְחֲזוּן לְאוֹדָאָה לֵיהּ, הֲדָא הוּא דִכְתִיב, (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ.</p>\n<p>תָּאנָא אָמַר רִבִּי יְהוּדָה, (תהילים נ׳:א׳) אֵל אֱלֹהִים יְיָ' דִּבֶּר וַיִקְרָא אָרֶץ. שְׁלִימוּ דְּכֹלָּא, שְׁלִימוּ דַּאֲבָהָן קַדִּישֵׁי. דִּבֶּר וַיִּקְרָא אָרֶץ, לְאִשְׁתַּכְּחָא בִּכְּנֶסֶת יִשְׂרָאֵל בִּשְׁלִימוּ בְּחֶדְוָותָא. וּמֵאָן אֲתַר הוּא אִשְׁתְּכַח עִמָּהּ. הָדָר וְאָמַר, מִצִּיּוֹן מִכְלַל יוֹפִי אֱלֹהִים הוֹפִיעַ.</p>"],[9520012130,"<p>תָּאנָא כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי עָלְמָא דִּלְתַתָּא, כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא עֲבַד לֵיהּ. עֲבַד יְרוּשְׁלֵים, אֶמְצָעִיתָא דְּכָל אַרְעָא. וַאֲתַר חַד דְּאִקְרֵי צִיּוֹן, עָלָה. וּמֵהַאי אֲתַר מִתְבָּרְכָא. וּבְהַאי אֲתַר דְּצִיּוֹן שָׁארֵי עָלְמָא לְאִתְבָּנָאָה, וּמִנֵּיהּ אִתְבְּנֵי. הֲדָא הוּא דִכְתִיב, אֵל אֱלֹהִים יְיָ' דִּבֶּר וַיִּקְרָא אָרֶץ מִמִּזְרָח שֶׁמֶשׁ עַד מְבוֹאוֹ. וּמֵאָן אֲתַר. מִצִּיּוֹן מִכְלַל יוֹפִי <Nonei></i>אֱלֹהִים הוֹפִיעַ. כְּלוֹמַר, מִצִיּוֹן דְּהוּא שְׁלִימוּ דְּיוֹפִי דְּעָלְמָא, אֱלֹהִים הוֹפִיעַ. תָּא חֲזֵי, לָא אִתְבָּרְכָא יְרוּשָׁלַם, אֶלָּא מִצִּיּוֹן. וְצִיּוֹן מֵעֵילָּא, וְכֹלָּא חַד בְּחַד אִתְקְשַׁר.</p>\n<p>תָּאנָא, אָמַר רִבִּי יְהוּדָה, (ויקרא ט״ז:י״ח) וְיָצָא אֶל הַמִּזְבֵּחַ אֲשֶׁר לִפְנֵי יְיָ' וְכִפֶּר עָלָיו. אֶל הַמִּזְבֵּחַ סְתָם. (כביכול) כְּמָה דְּאִתְעָבִיד לְתַתָּא, אִתְעָבִיד לְעֵילָּא, וְכֹלָּא אִתְקְשַׁר חַד בְּחַד. וְתָאנָא, כְּמָה דִּבְהַאי יוֹמָא מְכַפֵּר כַּהֲנָא לְתַתָּא, הָכִי נָמֵי לְעֵילָּא. וְכַד כַּהֲנָא דִּלְתַתָּא מְסַדֵּר פּוּלְחָנֵיהּ, כַּהֲנָא דִּלְעֵילָּא הָכִי נָמֵי, (כביכול) לָא אִשְׁתְּכַח לְעֵילָּא, עֵד דְּאִשְׁתְּכַח לְתַתָּא. וּמִתַּתָּא שָׁארֵי לְסַלְּקָא קְדוּשָּׁה דְּמַלְכָּא עִלָּאָה, וּמִשְׁתַּכְחִין כֻּלְּהוּ עָלְמִין חַד קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>אָמַר רִבִּי יְהוּדָה, אִלְמָלֵא הֲווֹ יַדְעִי יִשְׂרָאֵל אֲמַאי קוּדְשָׁא בְּרִיךְ הוּא פָּקִיד עָלַיְיהוּ דְּיִשְׂרָאֵל, לְאוֹכָחָא לְהוּ יַתִּיר מִכָּל שְׁאָר עַמִּין, יִנְדְּעוּן דְּהָא קוּדְשָׁא בְּרִיךְ הוּא שָׁבִיק דִּידֵיהּ, וְלָא גָּבֵי מִנְּהוֹן חַד מִמֵּאָה. תָּאנָא, קוּדְשָׁא בְּרִיךְ הוּא כַּמָה רְתִיכִין, כַּמָה חַיָּילִין אִית לֵיהּ, כַּמָה שׁוּלְטָנִין מְמָנָן מִשְׁתַּכְּחִין בְּפוּלְחָנֵיהּ, כַּד זַמִּין לְהוּ לְיִשְׂרָאֵל בְּהַאי עָלְמָא, אַכְתַּר לוֹן בְּכִתְרִין קַדִּישִׁין כְּגַוְונָא דִּלְעֵילָּא, אַשְׁרֵי לוֹן בְּאַרְעָא קַדִּישָׁא, בְּגִין דְּיִשְׁתְּכָחוּ בְּפוּלְחָנֵיהּ, קָשִׁיר לְכֻלְּהוּ עִלָּאֵי בְּהוּ בְּיִשְׂרָאֵל.</p>\n<p>וְחֶדְוָון לָא עָאלִין קַמֵּיהּ, וּפוּלְחָנָא לָא אִתְעָבִיד קָמֵיהּ לְעֵילָּא, עַד דְּיִשְׂרָאֵל עַבְדִּין לְתַתָּא. כָּל זִמְנָא דְּיִשְׂרָאֵל מִשְׁתַּכְּחִין בְּפוּלְחָנֵיהּ דְּמָארֵיהוֹן לְתַתָּא, הָכִי נָמֵי לְעֵילָּא. (כביכול) בְּזִמְנָא דְּיִשְׂרָאֵל בְּטַלֵּי פּוּלְחָנָא לְתַתָּא. בְּטַלֵּי לְעֵילָּא, וּפוּלְחָנָא לָא אִשְׁתְּכַח לָא לְעֵילָּא וְלָא לְתַתָּא. וְעַל דְּיִשְׂרָאֵל בַּטְלוּ פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא כַּד שָׁארָן בְּאַרְעָא, הָכִי נָמֵי לְעֵילָּא, כָּל שֶׁכֵּן לְבָתַר.</p>\n<p>אָמַר קוּדְשָׁא בְּרִיךְ הוּא, יִשְׂרָאֵל אִי אַתּוּן יַדְעִין, כַּמָה אוּכְלוּסִין, כַּמָה חַיָּילִין, מִתְעַכְּבִין בְּגִינַיְיכוּ, תִּנְדְּעוּן דְּלֵית אַתּוּן כְּדַאי לְמֵיקָם בְּעָלְמָא, אֲפִילּוּ שַׁעֲתָא חֲדָא. וְעִם כָּל דָּא מַה כְּתִיב, (ויקרא כ״ו:מ״ד) וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים וְגוֹ', (בגין כך) וְיָצָא אֶל הַמִּזְבֵּחַ, אֶל הַמִּזְבֵּחַ סְתָם, אֲשֶׁר לִפְנֵי יְיָ' סְתָם. וְכִפֶּר עָלָיו לְבָתַר, וְיָצָא וְעָשָׂה אֶת עוֹלָתוֹ וְאֶת עוֹלַת הָעָם וְגוֹ'. וְכִפֵּר עָלָיו מַאי קָא מַיְירֵי. אָמַר רִבִּי יוֹסֵי, לְאִתְּעָרָא חֶסֶד בְּעָלְמָא בְּקַדְמִיתָא.</p>\n<p>תָּאנָא, כְּתִיב וְכִפֶּר עַל הַקֹּדֶשׁ מִטֻּמְאוֹת בְּנֵי יִשְׂרָאֵל. מַאי וְכִפֶּר עַל הַקֹּדֶשׁ. אֶלָּא אָמַר רִבִּי אֶלְעָזָר, הָא תָּנֵינָן, חַיָּיבַיָּא עַבְדִּין פְּגִימוּתָא לְעֵילָּא, וּמִתְעָרִין דִּינִין, וְגַרְמִין לְאִסְתַּאֲבָא מַקְדְּשָׁא. וְחִוְיָא תַּקִּיפָא שָׁארֵי לְאִתְגַּלָּאָה. וּכְדֵין דִּינִין מִתְעָרִין בְּעָלְמָא, וּבְהַאי יוֹמָא, בָּעֵי כַּהֲנָא לְדַכְּאָה כֹּלָּא, וּלְאִתְעַטְּרָא (ס\"א ולאתערא) כִּתְרָא קַדִּישָׁא דִּילֵיהּ, דְּהִיא רֵישָׁא דְּמַלְכָּא. בְּגִין דְּיֵיתֵי מַלְכָּא לְאַשְׁרָאָה בְּמַטְרוֹנִיתָא, וְכַד רֵישָׁא דְּמַלְכָּא נָטִיל, כֹּלָּא נָטִיל, וְיֵיתֵי לְאִזְדַּוְּוגָא בְּמַטְרוֹנִיתָא וּלְאַתְעֲרָא חֵידוּ וּבִרְכָּאן בְּעָלְמָא. (ס\"א בגין דייתי מלכא לאזדווגא במטרוניתא ולאתערא חדו וברכאן בעלמא, וכד רישא דמלכא נטיל כלא נטיל)</p>\n<p>אִשְׁתְּכַח דְּכָל שְׁלָמָא (נ\"א שלימו) דְּעֵילָּא וְתַתָּא, בְּכַהֲנָא תַּלְיָיא. דְּאִי אִתְּעַר כִּתְרָא דִּילֵיהּ, כֹּלָּא אִתְּעַר וְכֹלָּא בִּשְׁלִימוּ אִשְׁתְּכַח. וְעַל דָּא כְּתִיב וְכִפֶּר עַל הַקֹּדֶשׁ. בְּקַדְמִיתָא וְכִפֶּר עַל הַקֹּדֶשׁ. לְאַסְגָּאָה שְׁלָמָא בְּעָלְמָא, וּלְאַסְגָּאָה חֵידוּ בְּעָלְמָא. וְכַד חֵידוּ דְּזִוּוּגָא אִשְׁתְּכַח בְּמַלְכָּא וּבְּמַטְרוֹנִיתָא, כָּל שַׁמָּשִׁין, וְכָל בְּנֵי הֵיכָלָא, כֻּלְּהוּ אִשְׁתְּכָחוּ בְּחֵידוּ (וכד חידו דעלמא). וְכָל חוֹבִין דְּחָבוּ קָמֵי מַלְכָּא, אִתְכַּפָּר לְהוּ. הֲדָא הוּא דִכְתִיב, מִכֹּל חַטֹּאתֵיכֶם לִפְנֵי יְיָ' תִּטְהָרוּ. וּבְגִין כָּךְ כְּתִיב וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד בְּבֹאוֹ לְכַפֵּר בַּקֹּדֶשׁ עַד צֵאתוֹ. בְּשַׁעֲתָא דְּעָאל לְזַוְּוגָא לְהוּ, וּבְשַׁעֲתָא דְּמִזְדַּוְּוגִין מַלְכָּא וּמַטְרוֹנִיתָא, הַהִיא שַׁעֲתָא וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ.</p>"],[9520012131,"<p>תָּאנָא, (ויקרא ט״ז:י״ז) וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד, רִבִּי יִצְחָק פָּתַח, (ויקרא כ״ו:מ״ב) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקֹב וְאַף אֶת בְּרִיתִי יִצְחָק וְגוֹ', וְהַאי קְרָא אוּקְמוּהָ. תָּא חֲזֵי, בְּשַׁעֲתָא דְּיִשְׂרָאֵל בְּגָלוּתָא, כִּבְיָכוֹל קוּדְשָׁא בְּרִיךְ הוּא עִמְּהוֹן בְּגָלוּתָא, דְּהָא שְׁכִינְתָּא לָא אִתְעָדֵי מִנַּיְיהוּ לְעָלְמִין. תָּא חֲזֵי, בְּזִמְנָא דְּיִשְׂרָאֵל אִשְׁתְּכָחוּ בְּגָלוּתָא דְּבָבֶל, שְׁכִינְתָּא בֵּינַיְיהוּ שַׁרְיָא, וְתָאבָת עִמְּהוֹן מִן גָּלוּתָא. וּבִזְכוּת אִינּוּן צַדִּיקַיָּיא <Nonei></i>דְּאִשְׁתָּאָרוּ בְּאַרְעָא, שָׁארַת בְּאַרְעָא, וְלָא אַעְדֵּי מִנַּיְיהוּ לְעָלְמִין. אָמַר רִבִּי יְהוּדָה, דְּאִתְהַדְּרַת מַטְרוֹנִיתָא בְּמַלְכָּא, וְאִתְהַדָּר כֹּלָּא בְּהִלּוּלָא דְּמַלְכָּא, בְּגִין כָּךְ אִקְרוּן אַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה, כְּנֶסֶת הַגְּדוֹלָה וַדַּאי.</p>\n<p>תָּאנָא, בְּכָל זִמְנָא דְּיִשְׂרָאֵל בְּגָלוּתָא, אִי אִינּוּן זַכָּאִין, קוּדְשָׁא בְּרִיךְ הוּא אַקְדִּים לְרַחֲמָא עָלַיְיהוּ, וּלְאַפָּקָא לוֹן מִגָּלוּתָא. וְאִי אִינּוּן לָא זַכָּאִין, מְעַכֵּב לוֹן בְּגָלוּתָא, עַד הַהוּא זִמְנָא דְּאִתְגְּזַר. וְכַד מָטָא זִמְנָא, וְאִינּוּן לָא אִתְחַזְיָין, קוּדְשָׁא בְּרִיךְ הוּא אַשְׁגַּח לִיקָרָא דִּשְׁמֵיה, וְלָא אַנְשֵׁי לְהוּ בְּגָלוּתָא, הֲדָא הוּא דִכְתִיב וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְגוֹ'. אִלֵּין אֲבָהָן דְּכֹלָּא, רָזָא דִּשְׁמָא קַדִּישָׁא.</p>\n<p>רִבִּי חִיָּיא אָמַר, מַאי טַעֲמָא יַעֲקֹב קַדְמָאָה הָכָא. אֶלָּא, בְּגִין דְּיַעֲקֹב כְּלָלָא דַּאֲבָהָן, וְהוּא אִילָנָא קַדִּישָׁא. בְּגִין כָּךְ, ו' דִּשְׁמָא קַדִּישָׁא בֵּיהּ אֲחִידָא, וְהָכִי קָרֵינָן יַעֲקוֹב בְּו'. רִבִּי יִצְחָק, אָמַר וָא\"ו בְּאַתְווֹי י\"ג מְכִילָן, דְּיָרִית יְרוּתָא דְּי\"ג מַבּוּעִין דְּמַבּוּעָא סְתִימָא קַדִּישָׁא.</p>"],[9520012132,"<p>רִבִּי אַבָּא אָמַר, וָא\"ו אֲמַאי כָּלִיל ו' א' ו'. אֶלָּא, ו' דְּיָתִיב עַל כּוּרְסְיָיא, כְּמָה דְאַתְּ אָמֵר (יחזקאל א׳:כ״ו) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. א' סָתִים בְּגַוִּיהּ וְלָא אִתְגַּלְיָיא, וְדָא הוּא דִּכְתִּיב, (בראשית כ״ב:ט״ז) בִּי נִשְׁבַּעְתִּי (ק\"ל ע\"א) נְאֻם יְיָ', בְּגִין כָּךְ כְּתִיב, וְלָא אִקְרֵי, בַּתְרָאָה, כְּלָלָא דְּקַדְמָאָה. בַּתְרָאָה, הָא אוֹקִימְנָא (נ\"א בתראה כללא דו' קדמאה ו' בתראה) דָּא יְסוֹד, דְּאִיהוּ סִיּוּמָא דְּגוּפָא, וּכְלָלָא דִּילֵיהּ. וְעַל דָּא כְּלִילָן אַתְוָון דָּא בְּדָא, וָא\"ו, רֵישָׁא וְסִיּוּמָא, כְּמָה דְּאוֹקִימְנָא.</p>\n<p>וְתָאנָא, תְּרֵין אַתְוָון אִינּוּן, כְּהַאי גַּוְונָא וָא\"ו דַּאֲמֵינָא, נוּ\"ן אוּף הָכִי. וְאַף עַל גַּב דְּאוּקְמוּהָ מִלָּה, נוּ\"ן הָכִי מִתְפָּרְשָׁא: נ' כְּפוּפָה, דָּא מַטְרוֹנִיתָא. וּסְמִיכָא לָהּ ו', דְּאִיהוּ יְסוֹד, בְּגִין לְאִתְבָּרְכָא מִנֵּיהּ. ן' פְּשׁוּטָה, אִתְפַּשְּׁטוּתָא דְּתִפְאֶרֶת. וְעַל דָּא כְּלִילָן אַתְוָון, וּמִתְאַחֲדָן דָּא בְּדָא. וְאִי תֵּימָא, אֲמַאי אַהְדָּר ו' אַנְפּוֹי מִנּוּ\"ן כְּפוּפָה, וְאַהְדָּר אַנְפּוֹי לְגַבֵּי ן' פְּשׁוּטָה. אֶלָּא בְּגִין יְקָרָא דְּמַלְכָּא, אַהְדָּר אַנְפּוֹי לָקֳבְלֵיהּ דְּמַלְכָּא.</p>\n<p>וְתָאנָא, מֵ\"ם לָא כָּלִיל בְּגַוָּיהּ אָת אָחֳרָא, (בגין) אֶלָּא מ' פְּתוּחָה, ם' סְתוּמָה. מ' פְּתוּחָה: דְּהוּא כַּד דְּכַר אִתְחַבָּר עִמָּהּ. ם' סְתוּמָה: יוֹבְלָא. דְּהָא סְתִימִין אֲרְחָהָא וְאַף עַל גַּב דְמִתְפַשְׁטִין לְזִמְנִין, וְאִית דְמַתְנֵי בְהַאי כְּמָה דְאַתְּ אָמֵר (שיר השירים ד׳:י״ב) גַּן נָעוּל אֲחוֹתִי כַלָּה גַּל נָעוּל מַעְיָן חָתוּם.</p>\n<p>אָמַר רִבִּי יִצְחָק, בְּשַׁעֲתָא דְּמַלְכָּא קַדִּישָׁא אַדְכַּר לְהוּ לְיִשְׂרָאֵל בְּגִין שְׁמֵיהּ, וְאָהַדְרַת מַטְרוֹנִיתָא לְאַתְרָהָא, (כדין) כְּתִיב, וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד בְּבֹאוֹ לְכַפֵּר בַּקֹּדֶשׁ. כַּךְ כַּהֲנָא, בְּשַׁעֲתָא דְּעָאל לְיַחֲדָא שְׁמָא קַדִּישָׁא, וּלְכַפְּרָא בְּקוּדְשָׁא, לְזַוְּוגָא לְמַלְכָּא בְּמַטְרוֹנִיתָא. כְּתִיב וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד וְגוֹ'.</p>\n<p>תָּאנָא, רִבִּי יְהוּדָה אָמַר, כַּהֲנָא אִתְּעַר שְׁלָמָא בְּעָלְמָא, לְעֵילָּא וְתַתָּא. וְתַנְיָא עָאל בְּדַרְגָּא חַד, אַסְחֵי גּוּפֵיהּ. נָפִיק מֵהַאי דַּרְגָּא, לְדַרְגָּא אָחֳרָא אַסְחֵי גּוּפֵיהּ. אָחִיד שְׁלָמָא בְּהַאי וּבְהַאי, קִדֵּשׁ יְדוֹי, וּמִתְבָּרְכָאן כַּחֲדָא. וּבְכֹלָּא בָּעֵי לְאַחֲזָאָה עוֹבָדָא, וּבָעֵי לְאַחֲזָאָה לְבוּשׁוֹי, דְּיִתְלַבָּשׁ כְּגַוְונָא דְּעוֹבָדָא דְּיִתְכַּוָּון, עַד דִּיסַדֵּר כֹּלָּא כְּמָה דְּאִצְטְרִיךְ, וְיִתְבָּרְכוּן עִלָּאֵי וְתַתָּאֵי.</p>"],[9520012133,"<p>תָּאנָא רִבִּי שִׁמְעוֹן, פָּתַח (ד') יוֹ\"ד בִּגְלִיפוֹי, אַתְוָון בְּסִטְרִין, אִתְקַשְּׁרָן בְּיוֹ\"ד. יוֹ\"ד אָזִיל לְיוֹ\"ד. (לוי\"ו) יוֹ\"ד סָלִיק בְּיוֹ\"ד. יוֹ\"ד אָזִיל לְוָי\"ו, מִתְכַּנְּשֵׁי בה'. וּמְכַוִּון דַּעְתָּא, אִתְחַבָּר ה' בְּוָא\"ו.</p>\n<p>ה' עִלָּאָה אָחִיד תַּרְעוֹי (ס\"א בתרעוי) בְּגִלּוּפֵי תַּכְסִיסִין, אַחֲדָא בִּנְהִירוּ אֶלֶף וַחֲמֵשׁ מְאָה וְשִׁבְעִין אַכְסַדְרִין סְתִימִין. סָלִיק ה', וְאִתְעַטָּר חַמְשִׁין זִמְנִין, לָן' תַּרְעִין קַיְימִין דְּקַיְימִין, כַּד אִתְגְּלָף בְּעִטְרוֹי, נַהֲרִין אַנְפִּין דְּמַלְכָּא, וָא\"ו אִתְפְּשָׁט לְע\"ב גְּלִיפִין.</p>\n<p>מְעַטֵּר ה' לְו', (נ\"א מתעטר ביו\"ד, ה' לו') בְּע' אֶלֶף וְה' מְאָה כִּתְרִין, דְּמִתְעַטְּרָן בְּחַד כִּתְרָא, הֲדָא הוּא דִכְתִיב, (שיר השירים ג׳:י״א) בַּעֲטָרָה, שֶׁעִטְּרָה לּוֹ אִמּוֹ. ו' בִּתְרֵין רֵישִׁין, רֵישָׁא דְּגּוּלְגְלָתָא גְּלִיפָא רֵישָׁא, קוֹצָא חַד לְעֵילָּא, וְקוֹצָא חַד לְתַתָּא, וְי' נָחִית לְו', (ס\"א וא\"ו נחית לוא\"ו) גְּלִיפָא דְּגִלּוּפִין בְּגַּוַּיְיהוּ, שִׁבְעִין אַנְפִּין דְּעִטְרִין מֵעֵילָּא לְתַתָּא. בֵּיהּ טָאסִין גְּבִיעִין וּפַרְחִין, דָּא סָלִיק, וְדָא נָחִית מִתְגַּלְּפִין חַד בְּחַד.</p>\n<p>אִתְקְשַּׁר י' בְּה', ה' בְּו', ו' בְּה'. (ס\"א ו' בה', ה' בו', ו' בו', ו' בה') דָּא אָחִיד בְּדָא, כְּמָה דְּאַתְּ אָמֵר, (בראשית מ״ט:כ״ד) וַתֵּשֶׁב בְּאֵיתָן קַשְׁתּוֹ וַיָּפֹזּוּ זְרוֹעֵי יָדָיו מִידֵי אֲבִיר יַעֲקֹב. וּכְתִיב, (במדבר כ״ד:כ״א) אֵיתָן מוֹשָׁבֶךָ וְשִׂים בַּסֶּלַע קִנֶּךָ. כְּדֵין אִתְקְשַּׁר <Nonei></i>כֹּלָּא חַד בְּחַד, דָא בְּדָא, נַהֲרִין מַפְתְּחָן, וְנַהֲרִין אַנְפִּין כֻּלְּהוּ, כְּדֵין כֻּלְּהוּ נַפְלִין עַל אַנְפַּיְיהוּ, וּמִזְדַּעְזְעָן, וְאַמְרֵי בְּרִיךְ שְׁמָא יְקָרָא מַלְכוּתֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמִין.</p>"],[9520012134,"<p>קָלָא מִתְקַשָּׁר עִמֵּיהּ דְּכַהֲנָא, וְהוּא אָתִיב לְגַבַּיְיהוּ. וְאָמַר תִּטְהָרוּ. תִּטְהָרוּ לָא אַמְרִין שְׁאַר כַּהֲנֵי וְעַמָּא, בַּר כַּהֲנָא רַבָּא, כַּד אִתְקְשַּׁר בֵּיהּ הַהוּא קָלָא.</p>\n<p>תָּאנָא, מִכֹּל חַטֹּאתֵיכֶם לִפְנֵי יְיָ', כֵּיוָן דִּכְתִּיב מִכֹּל חַטֹּאתֵיכֶם, אֲמַאי לִפְנֵי יְיָ'. אֶלָּא אָמַר רִבִּי יִצְחָק, (שמות ק\"ע ע\"ב) לִפְנֵי יְיָ' מַמָּשׁ.</p>\n<p>דְּתַנְיָא, מֵרֵישָׁא דְּיַרְחָא סִפְרִין פְּתִיחִין, וְדַיְינֵי דַּיָּינִין. בְּכָל יוֹמָא וְיוֹמָא בָּתֵּי דִּינִין אִתְמַסְרָן, לְאִתְּפַתְחָא בְּדִינָא, עַד הַהוּא יוֹמָא דְּאִקְרֵי תִּשְׁעָה לְיַרְחָא. בְּהַהוּא יוֹמָא, סַלְּקִין דִּינִין כֻּלְּהוּ לְמָארֵי דְּדִינָא, וּמְתַקְּנֵי כּוּרְסְיָיא עִלָּאָה דְּרַחֲמֵי, לְמַלְכָּא קַדִּישָׁא. בְּהַהוּא יוֹמָא בָּעָאן יִשְׂרָאֵל לְתַתָּא, לְמֶחְדֵּי בְּחֶדְוָותָא לְקַדְמוּת מָארֵיהוֹן, דְּזַמִּין לְיוֹמָא אָחֳרָא, לְמֵיתַב עָלַיְיהוּ בְּכוּרְסְיָיא קַדִּישָׁא דְּרַחֲמֵי, בְּכוּרְסְיָיא דְּוַותְּרָנוּתָא.</p>\n<p>וְכָל אִינּוּן סִפְרִין דִּפְתִּיחִין קָמֵיהּ, וּכְתִיבִין קָמֵיהּ כָּל אִינּוּן חוֹבִין, הוּא מְזַכֵּי לוֹן, וּמַדְכֵּי לוֹן מְכֻּלְּהוּ, הֲדָא הוּא דִכְתִיב מִכֹּל חַטֹּאתֵיכֶם לִפְנֵי יְיָ' תִּטְהָרוּ. לִפְנֵי יְיָ' מַמָּשׁ, אִינּוּן דְּאַמְרֵי קְרָא, עַד הָכָא אַמְרִין, וְלָא יַתִּיר. וְלֵית רְשׁוּ לְאָחֳרָא דְּלִימָא תִּטְהָרוּ, אֶלָּא כַּהֲנָא רַבָּא, דְּפָלַח פּוּלְחָנָא, וְקָשַׁר שְׁמָא קַדִּישָׁא בְּפוּמֵיהּ, וְכַד הֲוָה אִתְקְשַׁר וּמִתְבָּרֵךְ בְּפוּמֵיהּ, הַהוּא קָלָא נָחִית וּבָטַשׁ בֵּיהּ, וְאִתְנְהִיר מִלָּה בְּפוּמֵיהּ דְּכַהֲנָא, וְאוֹמֵר תִּטְהָרוּ. פָּלַח פּוּלְחָנָא, וּמִתְבָּרְכִין כָּל אִינּוּן עִלָּאִין דְּאִשְׁתָּאָרוּ.</p>\n<p>וּלְבָתַר אַסְחֵי גּוּפֵיהּ, וְקִדֵּשׁ יְדוֹי, לְאַעֲלָא בְּפוּלְחָנָא אָחֳרָא קַדִּישָׁא. עַד דְּיִתְכַּוָּון לְמֵיעַל לַאֲתַר אָחֳרָא עִלָּאָה, קַדִּישָׁא מִכֹּלָּא. ג' שׁוּרִין סָחֲרִין לֵיהּ, כַּהֲנֵי אָחוֹי, וְלֵיוָאֵי, וּמִכָּל שְׁאָר עַמָּא כֻּלְּהוּ. (ברכאן קמיה) זַקְפִין יְדִין עָלֵיהּ בִּצְלוֹתָא וְקִטְרָא דְּדַהֲבָא זַקְפָא בְּרַגְלֵיהּ. נָטִיל ג' פְּסִיעָן, וְכֻלְּהוּ קַיְימִין בְּקִיּוּמַיְיהוּ, וְלָא נַטְלִין בַּתְרֵיהּ (הוה אקטיר קטורת).</p>\n<p>נָטִיל ג' פְּסִיעָן אָחֳרָן, (רשימא בלבא) אַסְחַר לְדוּכְתֵּיהּ. נָטִיל ג' פְּסִיעָן, אַסְתִּים עַיְינִין, וְאִתְקְשַׁר לְעֵילָּא. עָאל לַאֲתַר דְּעָאל, שָׁמַע קוֹל גַּדְפֵּי דִּכְרוּבַיָּיא מְזַמְּרִין, וְאָקִישָׁן גַּדְפִּין פְּרִישָׂאן לְעֵילָּא. הֲוָה אַקְטִיר קְטוֹרֶת, מִשְׁתַּכְּכָא קוֹל גַּדְפַּיְיהוּ וּבִלְחִישׁוּ אִתְדַּבְּקָן.</p>\n<p>אִי כַּהֲנָא זָכֵי, דְּהָא לְעֵילָּא בְּחֵידוּ אִשְׁתְּכַח, אוּף הָכָא בְּהַהִיא שַׁעֲתָא נָפִיק רַעֲוָא דִּנְהוֹרָא, מִתְבַּסְּמָא מֵרֵיחִין דְּטוּרֵי אֲפַרְסְמוֹנָא דַּכְיָא דִּלְעֵילָּא, וְאַזְלָא בְּכָל הַהוּא אֲתַר, אָעִיל רֵיחָא בִּתְרֵי נוּקְבֵי דְּחוּטָמֵיהּ, וְאִתְיָישְׁבָא לִבָּא. כְּדֵין כֹּלָּא הוּא בִּלְחִישׁוּ, וּפִטְרָא לָא אִשְׁתְּכַח תַּמָּן. פָּתַח כַּהֲנָא פּוּמֵיהּ בִּצְלוֹתָא בִּרְעוּתָא בְּחֶדְוָותָא, וְצַלֵּי צְלוֹתֵיהּ.</p>\n<p>בָּתַר דְּסִיֵּים, זַקְפִין כְּרוּבְיָיא כְּמִלְּקַדְּמִין גַּדְפַּיְיהוּ, וּמְזַמְּרִין. כְּדֵין יָדַע כַּהֲנָא דִּרְעוּתָא הֲווֹ, וְעִידָּן חֶדְוָותָא לְכֹלָּא, וְעַמָּא יַדְעִין דְּאִתְקַבֵּל צְלוֹתֵיהּ, כְּמָה דִּכְתִּיב, (ישעיהו א׳:י״ח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וְהוּא תָּב לַאֲחוֹרֵיהּ, וְצַלֵּי צְלוֹתֵיהּ. זַכָּאָה חוּלָקֵיהּ דְּכַהֲנָא, דְּהָא עַל יְדוֹי חֵידוּ עַל חֵידוּ אִשְׁתְּכַח הַהוּא יוֹמָא לְעֵילָּא וְתַתָּא, עַל הַהִיא שַׁעֲתָא כְּתִיב, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ, אַשְׁרֵי הָעָם שֶׁיְיָ' אֱלֹהָיו.</p>"],[9520012135,"<p>(ויקרא ט״ז:כ״ט) וְהָיְתָה לָכֶם לְחֻקַּת עוֹלָם בַּחֹדֶשׁ הַשְּׁבִיעִי בֶּעָשׂוֹר לַחֹדֶשׁ תְּעַנּוּ אֶת נַפְשׁוֹתֵיכֶם וְגוֹ'. רִבִּי חִיָּיא פָּתַח, (ישעיהו כ״ו:ט׳) נַפְשִׁי אִוִּיתִיךָ בַּלַיְלָה אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ וְגוֹ'. נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה. נַפְשִׁי בַּלַּיְלָה מִבָּעֵי לֵיהּ, מַאי נַפְשִׁי אִוִּיתִיךָ. אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, יְשַׁחֲרֶךָ מִבָּעֵי לֵיהּ. אֶלָּא הָכִי תָּאנָא, קוּדְשָׁא בְּרִיךְ הוּא רוּחָא וְנַפְשָׁא דְּכֹלָּא, וְיִשְׂרָאֵל אַמְרֵי נַפְשִׁי וְרוּחִי אַנְּתְּ. בְּגִין כַּךְ אִוִּיתִיךָ לְאַדְבְּקָא בָּךְ, וַאֲשַׁחֲרֶךָ לְאַשְׁכְּחָא רְעוּתָךְ.</p>\n<p>רִבִּי יוֹסֵי אָמַר, בְּשַׁעֲתָא דְּבַּר נָשׁ נָאִים בְּעַרְסֵיהּ. נָפְקָא נַפְשֵׁיהּ, סַלְקָא וְאַסְהִידַת בֵּיהּ בְּבַּר נָשׁ, עַל כָּל מַה דַּעֲבַד בְּכָל יוֹמָא. גּוּפָא אָמַר לְנַפְשָׁא, נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה, <Nonei></i>אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ.</p>\n<p>דָּבָר אַחֵר נַפְשִׁי אִוִּיתִיךָ, אָמְרָה כְּנֶסֶת יִשְׂרָאֵל קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה, בְּעוֹד דַּאֲנָא בְּגָלוּתָא בֵּינֵי עֲמַמְיָא, וּמְנִיעָא נַפְשִׁי מִכָּל בִּישָׁתָא (נ\"א ורוינא נפשי מכל פיסתא) דְּקוּטְרָא בְּנֵי עֲמַמְיָא, נַפְשִׁי אִוִּיתִיךָ, בְּגִין לְאָתָבָא לְאַתְרִי. אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, כְּלוֹמַר, אַף עַל גַּב דְּאִינּוּן מְשַׁעְבְּדִין לְבָנַי, בְּכָל שִׁעְבּוּדָא, רוּחָא קַדִּישָׁא לָא אִתְעָדֵי מִנַּאי, בְּגִין לְמִשְׁחַר לָךְ, וּלְמֶעְבַּד פִּקּוּדֶיךָ.</p>\n<p>רִבִּי יִצְחָק אָמַר, אָמְרוּ יִשְׂרָאֵל קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, בְּעוֹד דְּנַפְשִׁי בִּי, אִוִּיתִיךָ בַּלַּיְלָה. מַאי טַעֲמָא בַּלַּיְלָה, אֶלָּא בְּגִין דְּהַאי נֶפֶשׁ בְּהַאי שַׁעֲתָא, אִצְטְרִיךְ לְחַמְדָּא לָךְ. אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, כַּד אִתְּעַר בִּי רוּחָא קַדִּישָׁא, אֲשַׁחֲרֶךָּ בְּאִתְעָרוּתָא לְמֶעְבַּד רְעוּתָךְ. כִּי כַּאֲשֶׁר מִשְׁפָּטֶיךָ לָאָרֶץ בְּזִמְנָא דְּמִשְׁפָּט נָחִית בְּאַרְעָא, לְבַשְׂמָא עָלְמָא, כְּדֵין צֶדֶק לָמְדוּ יוֹשְבֵי תֵבֵל. כְּלוֹמַר יַכְלִין לְמִסְבַּל דִּינָא דְּצֶדֶק, וְלָא יִשְׁתְּצֵי עָלְמָא מִנֵּיהּ. אֵימָתַי צֶדֶק לָמְדוּ יוֹשְבֵי תֵבֵל, כַּאֲשֶׁר מִשְׁפָּטֶיךָ לָאָרֶץ. רַבִּי חִזְקִיָּה אָמַר, נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה, דָּא כְּנֶסֶת יִשְׂרָאֵל. אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, דָּא קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>רִבִּי אַבָּא הֲוָה יָתִיב קָמֵיהּ דְּרִבִּי שִׁמְעוֹן, קָם רִבִּי שִׁמְעוֹן בְּפַלְגּוּ לֵילְיָא, לְמִלְעֵי בְּאוֹרַיְיתָא. קָמוּ רִבִּי אֶלְעָזָר וְרִבִּי אַבָּא עִמֵּיהּ. פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר, (תהילים מ״ב:ב׳) כְּאַיָּל תַּעֲרוֹג עַל אֲפִיקֵי מָיִם כֵּן נַפְשִׁי תַעֲרוֹג אֵלֶיךָ אֱלֹהִים. הַאי קְרָא אוּקְמוּהָ חַבְרַיָּיא, זַכָּאִין אִינּוּן יִשְׂרָאֵל מִכָּל עַמִּין, דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לוֹן אוֹרַיְיתָא קַדִּישָׁא, וְאוֹרִית לוֹן נִשְׁמָתִין קַדִּישִׁין מֵאֲתַר קַדִּישָׁא, בְּגִין לְמֶעְבַּד פִּקּוּדוֹי, וּלְאִשְׁתַּעֲשְׁעָא בְּאוֹרַיְיתָא, דְּכָל מַאן דְּאִשְׁתַּעֲשָׁע בְּאוֹרַיְיתָא, לָא דָּחִיל מִכֹּלָּא. דִּכְתִּיב, (תהילים קי״ט:צ״ב) לוּלֵי תּוֹרָתְךָ שַׁעֲשׁוּעָי אָז אָבַדְתִּי בְעָנְיִי.</p>\n<p>מַאן אִינּוּן שַׁעֲשׁוּעָי. אוֹרַיְיתָא. דְּאוֹרַיְיתָא שַׁעֲשׁוּעִים אִקְרֵי, דִּכְתִּיב, (משלי ח׳:ל׳) וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. וְדָא הוּא דְּתָנֵינָן, קוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא בְּגִנְתָא דְּעֵדֶן. מַאי לְאִשְׁתַּעְשְׁעָא. בְּגִין לְמֶחְדֵּי בְּהוּ. דְּתָנֵינָן, זַכָּאִין אִינּוּן צַדִּיקַיָּא, דִּכְתִיב בְּהוּ, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ', בְּגִין לְאִתְעַנְּגָא מֵהַהוּא שַׁקְיוּ דְּנַחֲלָא, כְּמָה דְאַתְּ אָמֵר (ישעיהו נ״ח:י״א) וְהִשְׁבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךָ. כִּבְיָכוֹל, קוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעֲשָׁע בְּהוּ, מֵהַהוּא שַׁקְיוּ דְּנַחֲלָא, דְּמִתְעַנְּגֵי בְּהוּ צַדִּיקַיָּיא. וְעַל דָּא אָתֵי לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא. וְכָל מַאן דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא, זָכֵי לְאִשְׁתַּעְשְׁעָא עִם <Nonei></i>צַדִּיקַיָּיא, מֵהַהוּא שַׁקְיוּ דְּנַחֲלָא.</p>"],[9520012136,"<p>תָּאנָא, כְּאַיָּל תַּעֲרוֹג עַל אֲפִיקֵי מָיִם, דָּא כְּנֶסֶת יִשְׂרָאֵל. כְּמָה דְאַתְּ אָמֵר, (תהילים כ״ב:כ׳) אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה. תַּעֲרוֹג עַל אֲפִיקֵי מָיִם, וַדַאי לְאִשְׁתַּקְּיָא מִשַּׁקְיוּ דְּמַבּוּעֵי דְּנַחֲלָא, עַל יְדֵי דְּצַדִיק. תַּעֲרוֹג: כְּמָה דְאַתְּ אָמֵר, (שיר השירים ו) לַעֲרוּגֹת הַבּוֹשֶׂם, כֵּן נַפְשִׁי תַעֲרוֹג אֵלֶיךָ אֱלֹהִים. לְאִשְׁתַּקְּיָיא מִנָךְ, בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.</p>\n<p>מַבּוּעֵי נַחֲלָא מַאן אִינּוּן. מַבּוּעָא חַד לְעֵילָּא, דִּכְתִּיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ'. וּמִתַּמָּן נָגִיד וְנָפִיק, וּמַשְׁקֵי גִּנְתָּא, וְכָל אִינּוּן נַחֲלִין, נַגְדִּין וְנָפְקִין וּמִתְכַּנְּשִׁין בִּתְרֵי מַבּוּעִין, דְּאִקְרוּן נֶצַח וְהוֹד, וְאִלֵּין אִקְרוּן אֲפִיקֵי מַיִם, בְּהַהוּא דַּרְגָא דְּצַדִיק, דְּמִנֵיהּ נָגִיד וְנָפִיק וּמִשְׁתַּקְיָא גִּנְתָּא. בְּגִין כַּךְ אַיָּל וּצְבִי כַּחֲדָא מִשְׁתַּכְחֵי, (נ\"א איל וצבי אקרון עטרת ויסוד) צֶדֶק וְצַדִּיק.</p>"],[9520012137,"<p>תָּאנָא, כְּתִיב (תהילים כ״ט:ט׳) קוֹל יְיָ' יְחוֹלֵל אַיָּלוֹת, אַיָּלוֹת, אַיֶּלַת כְּתִיב חָסֵר, דָּא אַיְלוֹת הַשָּׂדֶה (נ\"א דא אילת דשחר). (דבר אחר אילות השדה), דְּתַנְיָא, בְּפַלְגוּת לֵילְיָא, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא עָאל לְגִנְתָּא דְּעֵדֶן לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא, הַאי קוֹל נָפִיק, וְכָאִיב כָּל אִינּוּן אַיַּלְתָּא דְּסַחֲרָנֵי כּוּרְסְיָיא יַקִּירָא קַדִּישָׁא, הֲדָא הוּא דִכְתִיב, (שיר השירים ג׳:ז׳) שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ. דָּבָר אַחֵר יְחוֹלֵל אַיָּלוֹת, כְּמָה דְאַתְּ אָמֵר (איוב כ״ו:י״ג) חוֹלְלָה יָדוֹ נָחָשׁ בָּרִיחַ. וַיֶּחשׂוֹף יְעָרוֹת כְּמָה דְאַתְּ אָמֵר. (שמואל א יב) בְּיַעְרַת הַדְּבָשׁ, וּכְתִיב (שיר השירים ה׳:א׳) אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי, וְיַנְקָא לְהוּ כְּאִמָּא דְּיָנְקָא לִבְנִין.</p>"],[9520012138,"<p><Nonei></i><Noneb>רעיא מהימנא</b> אָמַר רַעְיָא מְהֵימָנָא, בְּהַהוּא זִמְנָא, אִלֵּין מָארֵי מַתְנִיתִין מָארֵי חָכְמְתָא עִלָּאָה, מָארֵי קַבָּלָה, מָארֵי רָזֵי תּוֹרָה, שַׁעֲתָא דְּחִיקַת לוֹן. וְהַאי אִיהוּ דְּאָמַר כְּאַיָּל תַּעֲרוֹג עַל אֲפִיקֵי מָיִם, דְּאִינּוּן אֲפִיקֵי מַיִם דְּאוֹרַיְיתָא לְגַבֵּי שְׁכִינְתָּא. וְלֵית תּוֹרָה, אֶלָּא עַמּוּדָא דְּאֶמְצָּעִיתָא. דִּיהוֹן אִלֵּין אֲפִיקֵי מַיִם, בְּצַּעֲרָא בִּיגוֹנָא בְּעַנְיוּתָא, וְאִלֵּין אִינּוּן חֲבָלִים צִּירִין דְּיוֹלֵדָה, דְּאִיהִי שְׁכִינְתָּא, דְּאִתְּמַר בָּהּ, (משלי כ״ג:כ״ה-כ״ו) וְתָגֵל יוֹלַדְתֶּךָ. וּבְאִינּוּן חֲבָלִים, תְּהֵא בְּצַּעֲרָא דִּלְהוֹן.</p>\n<p>וּבְאִינּוּן חֲבָלִים דְּצַּוְוחַת בְּהוֹן, אִתְּעָרַת שִׁבְעִין סַנְהֶדְרִין דִּלְעֵילָּא, עַד דְּיִתְּעַר קוֹל דִּילָהּ עַד יְהוָֹ\"ה, וּמִיַּד (תהילים כ״ט:ט׳) קוֹל יְיָ' יְחוֹלֵל אַיָּלוֹת, דְּאִינּוּן מָארֵי מַתְנִיתִין, (תהילים מ״ה:ט״ו) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ, כֻּלְּהוֹן יִהוֹן לוֹן חִיל כַּיּוֹלֵדָה מַמָּשׁ, בְּדַחֲקִין, דְּדַחֲקָא לוֹן שַׁעֲתָא, בְּכַמָּה נְשִׁיכִין דְּיִצֶּר הָרָע, דְּחִוְיָא דְּנָשִׁיךְ לוֹן בְּכַמָּה דַּחֲקִין.</p>\n<p>בְּהַהוּא זִמְנָא אִתְפַּתְּחַת לְאוֹלָדָא מְשִׁיחָא, בְּגִין חֲבָלִים וְדוֹחֲקִים דְּצַּדִּיקִים, וּמָארֵי מִדּוֹת, וּמָארֵי רָזִין דְּאוֹרַיְיתָא, מָארֵי בּוֹשֶת וַעֲנָוָה, מָארֵי יִרְאָה וְאַהֲבָה, מָארֵי חֶסֶד, אַנְשֵׁי חַיִל יִרְאֵי אֱלֹהִים, אַנְשֵׁי אֱמֶת, שׂוֹנְאֵי בָצַּע, דְּדַחֲקָא לוֹן שַׁעֲתָא. וְהַאי הוּא דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, דּוֹר שֶׁבֶּן דָּוִד בָּא, אַנְשֵׁי חַיִל יְסוֹבְבוּ מֵעִיר לָעִיר וְלָא יְחוֹנָנוּ, וְיִרְאֵי חֵטְא יִמָּאֲסוּ, וְחָכְמַת סוֹפְרִים תִּסְרַח, וּתְּהִי הָאֱמֶת נֶעְדֶּרֶת, וְהַגֶּפֶן תִּתֵּן פִּרְיָה, וְהַיַּיִן בְּיוֹקֶר.</p>\n<p>וּמֵאִינּוּן קָלִין דְּיָהִיבַת, דְּאִינּוּן שִׁבְעִין, לָקֳבֵל שִׁבְעִין תֵּיבִין <Nonei></i>דְּיַעַנְךָ יְיָ' בְּיוֹם צָּרָה, אִתְפַּתְּחַת רַחְמָהּ, דְּאִיהִי ב', כְּלִילָא מִתְּרֵין בֵּיתִין, לְאוֹלָדָא ב' מְשִׁיחִין, וְאָעִילַת רֵישָׁהּ בֵּין בִּרְכָּהָא, דְּאִיהוּ רֵישָׁא דִּילָהּ, עַמּוּדָא דְּאֶמְצָּעִיתָא. תְּרֵין שׁוֹקָהָא, נֶצַּח וְהוֹד, תְּרֵין נְבִיאִים. מִתַּמָּן אוֹלִידַת תְּרֵין מְשִׁיחִין. בְּהַהִיא זִמְנָא וַיֶּחֱשׂוֹף יְעָרוֹת, יִתְעַבָּר נָחָשׁ מֵעָלְמָא (ע\"כ רעיא מהימנא)</p>"],[9520012139,"<p>אָמַר לֵיהּ רִבִּי אַבָּא, (ישעיהו כ״ו:ט׳) נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, נַפְשִׁי בַּלַּיְלָה מִבָּעֵי לֵיהּ. אֲשַׁחֲרֶךָּ, יְשַׁחֲרֶךָ מִבָּעֵי לֵיהּ. אָמַר לֵיהּ הָא אוּקְמוּהָ, (בראשית כ\"ג) כְּמָה דְאַתְּ אָמֵר (איוב י״ב:י׳) אֲשֶׁר בְּיָדוֹ נֶפֶשׁ כָּל חָי וְרוּחַ כָּל בְּשַׂר אִישׁ.</p>\n<p>תָּא חֲזֵי נַפְשָׁא וְרוּחָא אִשְׁתְּמוֹדָע (ס\"א אשתעי) (ס\"א אשתתפי) כַּחֲדָא לְעָלְמִין. תָּנָא פּוּלְחָנָא שְׁלֵימָתָא דְּבָעֵי בַּר נָשׁ לְמִפְלַח לְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּתַנִּינָן (דברים ו׳:ה׳) וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ וְגוֹ'. דְּיַרְחִים לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא רְחִימוּתָא דְּנֶפֶשׁ מַמָּשׁ, וְדָא הוּא רְחִימוּתָא שְׁלֵימָתָא, רְחִימוּתָא דְּנַפְשֵׁיהּ וְרוּחֵיהּ. כְּמָה דְּאִתְדְּבָּקוּ אִלֵּין בְּגוּפָא, וְגוּפָא רָחִים לוֹן. (ס\"א כדין) כַּךְ יִתְדָּבָק בַּר נָשׁ לְרַחֲמָא לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, רְחִימוּתָא דְּנַפְשֵׁיהּ וְרוּחֵיהּ, לְאַדְבְּקָא בֵּיהּ. הֲדָא הוּא דִכְתִיב נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה (כלומר) נַפְשִׁי מַמָּשׁ.</p>\n<p>אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, אִתְדַּבְּקָא בָּךְ בִּרְחִימוּתָא סַגִיאָה, בַּלַּיְלָה. דְּבָעֵי בַּר נָשׁ מֵרְחִימוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, לְמֵיקָם בְּכָל לֵילְיָא, לְאִשְׁתַּדְלָא בְּפוּלְחָנֵיהּ, עַד דְּיִתְעַר צַפְרָא, וְיִתְמְשַׁךְ עָלֵיהּ חוּטָא דְּחֶסֶד. דְּתַנְיָא, זַכָּאָה חוּלָקֵיהּ דְּהַהוּא בַּר נָשׁ דִּרְחִימוּתָא דָּא רָחִים לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְהָנֵי זַכָּאֵי קְשׁוֹט דִּמְרַחֲמִין לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא הָכִי, עָלְמָא מִתְקַיְימָא בְּגִינֵיהוֹן, וְשַׁלְטִין עַל כָּל גְּזִירִין קָשִׁין דִּלְעֵילָּא וְתַתָּא. (נ\"א היא) (בגין דיתקיים עלמא בגיניהון)</p>\n<p>תָּאנָא, הַהוּא זַכָּאָה דְּאִתְדַּבָק בְּרוּחֵיהּ וְנַפְשֵׁיהּ לְעֵילָּא, בְּמַלְכָּא קַדִישָׁא, בִּרְחִימוּתָא כְּדְקָא יֵאוֹת. שַׁלִּיט בְּאַרְעָא דִּלְתַתָּא, וְכָל מַה דְּגָזַר עַל עָלְמָא אִתְקַיָּים. מְנָא לָן, מֵאֵלִיָּהוּ. דִּכְתִּיב, (מלכים א י״ז:א׳) חַי יְיָ' אֲשֶׁר עָמַדְתִּי לְפָנָיו אִם יִהְיֶה הַשָּׁנִים הָאֵלֶּה טַל וּמָטָר כִּי אִם לְפִי דְּבָרִי.</p>\n<p>תָּא חֲזֵי, בְּשַׁעֲתָא דְּאַתְיָין נִשְׁמָתִין קַדִישִׁין מֵעֵילָּא לְתַתָּא, וְאִינּוּן זַכָּאֵי עָלְמָא מְשַׁלְּפֵי לְהוּ מִמַּלְכָּא וּמַטְרוֹנִיתָא, זְעִירִין אִינּוּן, דִּבְהַהוּא שַׁעֲתָא דְּנָחִית, קַיְּימָא קָמֵי מַלְכָּא, וּרְעוּתָא דְּמַלְכָּא לְאִסְתַּכְּלָא בָּהּ, כְּמָה דְּאוֹקִימְנָא, בְּשַׁעֲתָא דְּנָשַׁב קוּדְשָׁא בְּרִיךְ הוּא רוּחָא בְּכָל חֵילָא וְחֵילָא דִּשְׁמַיָּא, כֻּלְּהוּ חַיָּילִין אִתְעָבִידוּ, וְקַיְימֵי בְּקִיּוּמַיְיהוּ, הֲדָא הוּא דִכְתִיב (תהילים ל״ג:ו׳) וּבְרוּחַ פִּיו כָּל צְבָאָם. וּמִנַּיְיהוּ אִתְעַכְּבוּ עַד דְּקוּדְשָׁא בְּרִיךְ הוּא <Nonei></i>אָחִית לְהוּ לְתַתָּא.</p>\n<p>וְתָאנָא, מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא, קַיְימֵי קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִתְעַכָּבוּ עַד דְּמָטָא זִמְנָא לְאַחֲתָא לוֹן בְּאַרְעָא, וְאִלֵּין שְׁלִיטוּ לְעֵילָּא וְתַתָּא, הֲדָא הוּא דִכְתִיב חַי יְיָ' אֲשֶׁר עָמַדְתִּי לְפָנָיו, אֲשֶׁר אֲנִי עוֹמֵד לָא כְּתִיב, אֶלָּא אֲשֶׁר עָמַדְתִּי. לְבָתַר אַהְדָר לְאַתְרֵיהּ, וְסָלִיק לְאִדָּרֵיהּ, וְאִינּוּן אָחֳרָנִין לָא סַלְּקִין עַד דִּימוּתוּן. בְּגִין דְּלָא קַיְימוּ קוֹדֶם לָכֵן כְּאִינּוּן אָחֳרָנִין. וּבְגִין כַּךְ אֵלִיָּהוּ אִתְעָבִיד שְׁלִיחָא, מַלְאָכָא לְעֵילָּא, וְאִלֵּין דְּמִתְדַּבְּקָן יַתִיר לְמַלְכָּא.</p>\n<p>אַשְׁכַּחְנָא בְּסִפְרָא דְּאָדָם קַדְמָאָה דְּכָל רוּחִין קַדִישִׁין דִּלְעֵילָּא, עָבְדִין שְׁלִיחוּתָא, וְכֻלְּהוּ אַתְיָין מֵאֲתַר חַד. דְּנִשְׁמָתְהוֹן דְּצַדִיקַיָּיא מִתְּרֵי דַּרְגִּין דִּכְלִילָן בְּחַד, וּבְגִין כַּךְ סַלְּקִין יַתִיר, וְדַרְגֵּיהוֹן יַתִיר, וְהָכִי הוּא. וְכָל אִינּוּן דַּהֲווֹ טְמִירִין תַּמָּן, נַחְתּוּ וּסְלִיקוּ בְּחַיֵּיהוֹן, כְּגוֹן חֲנוֹךְ דְּלָא אִשְׁתְּכַח בֵּיהּ מִיתָה. וְהָא אוֹקִימְנָא מִלָּה דָּא, בַּחֲנוֹךְ וְאֵלִיָּהוּ.</p>\n<p>וְתָאנָא מְאָה וְעֶשְׂרִין וַחֲמֵשׁ אֶלֶף דַּרְגִּין (לצדיקייא) לְנִשְׁמָתְהוֹן דְּצַדִּיקַיָּיא, סְלִיקוּ בִּרְעוּתָא, עַד לָא אִתְבְּרֵי עָלְמָא, דְּקוּדְשָׁא בְּרִיךְ הוּא מְזַמְּנָא לְהוּ בְּעָלְמָא דֵּין, בְּכָל דָּרָא וְדָרָא, וְסַלְּקִין וְטָאסִין עָלְמָא, וּמִתְקַשְּׁרֵי בִּצְרוֹרָא דְּחַיֵּי, וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְחַדְּתָּא עָלְמָא בְּהוּ, עָלַיְיהוּ כְּתִיב, (ישעיהו ס״ו:כ״ב) כִּי כַאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה וְגוֹ'.</p>\n<p>(ויקרא ט״ז:כ״ט) תְּעַנּוּ אֶת נַפְשׁוֹתֵיכֶם, נַפְשׁוֹתֵיכֶם קָאָמַר, בְּגִין דְּיִשְׂרָאֵל מִשְׁתַּכְחִין קָמֵי מַלְכָּא קַדִישָׁא זַכָּאִין, וִיהֵא רְעוּתָא דִּלְהוֹן לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וּלְאִתְדַּבְקָא בֵּיהּ, בְּגִין דְּיִתְכַּפֵּר לְהוּ חוֹבַיְיהוּ. וְעַל דָּא, מַאן דְּאָכַל וְשָׁתֵי בִּתְשִׁיעָאָה, וּמְעַנְּגָא נַפְשֵׁיהּ בְּמֵיכְלָא וּמִשְׁתְּיָיא, אִשְׁתְּכַח בַּעֲשִׂירָאָה עִנּוּיָא דְּנַפְשָׁא בִּתְרֵין חוּלָקִין, וְאִשְׁתְּכַח כְּאִלּוּ אִתְעַנֵּי תְּשִׁיעָאָה וַעֲשִׂירָאָה. אֶת נַפְשׁוֹתֵיכֶם: לְאַכְלְלָא כֹּלָּא, גּוּפָא וְנַפְשָׁא, וּלְאִתְכַּנְּעָא בְּהַאי יוֹמָא, לְאִתְכַּפְּרָא עַל חוֹבֵיהוֹן.</p>\n<p>תָּאנָא כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם. בַּיוֹם הַזֶּה. הַיּוֹם הַזֶּה מִבָּעֵי לֵיהּ. אֶלָּא בַּיוֹם הַזֶּה דַּיְיקָא, דְּבֵיהּ אִתְגְלֵי עַתִּיקָא קַדִּישָׁא, לְכַפָּרָא עַל חוֹבֵיהוֹן דְּכֹלָּא.</p>"],[9520012140,"<p>דָּבָר אַחֵר תְּעַנּוּ אֶת נַפְשׁוֹתֵיכֶם. רִבִּי אַבָּא פָּתַח וְאָמַר, (קהלת ט׳:י״ד) עִיר קְטַנָּה וַאֲנָשִׁים בָּהּ מְעָט וְגוֹ', עִיר קְטַנָּה, הָא אוּקְמוּהָ. אֲבָל עִיר קְטַנָּה, כְּמָה דְאַתְּ אָמֵר, (ישעיהו כ״ו:א׳) עִיר עָז לָנוּ יְשׁוּעָה יָשִׁית חוֹמוֹת וַחֵיל וְגוֹ'. וּכְתִּיב (הושע י״א:ט׳) וְלֹא אָבֹא בְּעִיר. עִיר קְטַנָּה, זְעֵירָא הִיא, דְּהִיא בַּתְרָאָה מִכֹּלָּא, תַּתָּאָה מִכֹלָּא, שׁוּרוֹי רַבְרְבִין, תַּקִּיפִין, קַדִּישִׁין, עִיר הַקֹּדֶשׁ אִקְרֵי. וַאֲנָשִׁים בָּהּ מְעָט, זְעִירִין אִינּוּן דְּזַכָּאן לְסַלְּקָא לְגַוָּוהּ, וּלְמִשְׁרֵי בָּהּ, כְּמָה דְאַתְּ אָמֵר (תהילים כ״ד:ג׳) מִי יַעֲלֶה בְהַר יְיָ' וּמִי יָקוּם בִּמְקוֹם קָדְשׁוֹ וְגוֹ'. וְעַל דָּא אֲנָשִׁים בָּהּ מְעָט.</p>\n<p>וּבָא אֵלֶיהָ מֶלֶךְ גָּדוֹל, דָּא קוּדְשָׁא בְּרִיךְ הוּא. לְאִזְדַוְּוגָא בָּהּ, וּלְמִשְׁרֵי בָּהּ, וְסָבַב אוֹתָהּ, כְּמָה דְאַתְּ אָמֵר (זכריה ב׳:ט׳) וַאֲנִי אֶהְיֶה לָּהּ נְאֻם יְיָ' חוֹמַת אֵשׁ סָבִיב וְגוֹ'. וּבָנָה עָלֶיהָ מְצוֹדִים גְּדוֹלִים, דְּבָנָה שׁוּרוֹי, רַבְרְבִין תַּקִּיפִין יֶאֱיָאן וְשַׁפִּירִין (ס\"א מכל אבנין יקירין) קַדִּישִׁין. עִיר הַקֹּדֶשׁ אִקְרֵי, וְכָל יְקָרָא דְּמַלְכָּא עַיִּיל בְּגַוָּוהּ. וּבְגִין כָּךְ, הִיא בִּלְחוֹדָהָא כְּלִילָא מִכָּל עִטְרֵי דְּמַלְכָּא, וְכָל עִטְרֵי מַלְכָּא בָּהּ מִתְעַטְּרִין. בְּגִין כָּךְ, וַאֲנָשִׁים בָּהּ מְעָט כְּתִיב.</p>\n<p>וּמָצָא בָהּ אִישׁ מִסְכֵּן וְחָכָם, הֲדָא הוּא דִכְתִיב, (תהלים טו) נְקִי כַפַּיִם וּבַר לֵבָב. מִסְכֵּן: כְּמָה דְאַתְּ אָמֵר (שמות א׳:י״א) וַיִּבֶן עָרֵי מִסְכְּנוֹת לְפַרְעֹה, מִתְעַטָּר בְּעִטְרִין תַּקִּיפִין, בְּעִטְרֵי אוֹרַיְיתָא, בְּעִטְרֵי פִּקּוּדֵי אוֹרַיְיתָא דְּמַלְכָּא. וְחָכָם, דְּזָכֵי בָּהּ בְּהַאי חָכְמָה. וְחָכָם, דְּהוּא חַכִּים יַתִיר מִכֹּלָּא לְעַיְּינָא בְּפוּלְחָנָא דְּמָארֵיהּ, בְּגִין לְמִזְכֵּי בָּהּ, וּלְאַעֲלָא בָּהּ. הֲדָא הוּא דִּכְתִיב, וּמִלַּט הוּא אֶת הָעִיר בְּחָכְמָתוֹ. וּמִלַּט: כְּמוֹ (שמואל א כ׳:כ״ט) אִמָּלְטָה נָּא וְאֶרְאֶה אֶת אֶחָי, (בראשית י״ט:כ׳) אִמָּלְטָה נָא שָׁמָּה. אוּף הָכָא וּמִלַּט הוּא אֶת הָעִיר בְּחָכְמָתוֹ.</p>\n<p>וְאָדָם לֹא זָכַר אֶת הָאִישׁ הַמִּסְכֵּן הַהוּא, וְאָדָם לָא זָכַר, לְמֶעְבַּד פִּקּוּדֵי אוֹרַיְיתָא, לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, כְּהַהוּא גְּבַר מִסְכְּנָא דְּאִתְחַבָּר בְּכֹלָּא, <Nonei></i>בְּגִין לְמִזְכֵּי בָּהּ. (קהלת ט׳:ט״ז) וְאָמַרְתִּי אָנִי טוֹבָה חָכְמָה מִגְּבוּרָה. דְּהָא בְּהַהוּא עָלְמָא, לָא יָהֲבִין רְשׁוּ לְמֵיעַל, בַּר הָנֵי זַכָּאֵי קְשׁוֹט, הָנֵי דְּמִשְׁתַּדְּלֵי בָּהּ בְּאוֹרַיְיתָא יוֹמָא וְלֵילֵי, וּמִתְעַטְּרֵי בְּפִקּוּדֵי אוֹרַיְיתָא בְּהַאי עָלְמָא, לְמֵיעַל בְּהוּ לְעָלְמָא דְּאָתֵי.</p>\n<p>וְחָכְמַת הַמִּסְכֵּן בְּזוּיָה וּדְבָרָיו אֵינָם נִשְׁמָעִים. דְּהָא בְּנֵי נָשָׁא לָא מִסְתַּכְּלִין בֵּיהּ, וְלָא בָּעָאן לְאִתְחַבְּרָא בֵּיהּ, וּלְאָצִית לְמִלּוֹי. דְּתָנָא, כָּל מַאן דְּאָצִית לְמִלּוֹי דְּאוֹרַיְיתָא, זַכָּאָה הוּא בְּהַאי עָלְמָא, וּכְאִלּוּ קַבִּיל תּוֹרָה מִסִּינַי. וַאֲפִילּוּ מִכָּל בַּר נָשׁ נָמֵי בָּעֵי לְמִשְׁמַע מִלּוֹי דְּאוֹרַיְיתָא. וּמַאן דְּאַרְכִין אוּדְנֵיהּ לָקֳבְלֵיהּ, יָהִיב יְקָרָא לְמַלְכָּא קַדִּישָׁא, וְיָהִיב יְקָרָא לְאוֹרַיְיתָא. עָלֵיהּ כְּתִיב, (דברים כ״ז:ט׳) הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם לַיְיָ' אֱלֹהֶיךָ.</p>"],[9520012141,"<p>תָּאנָא, יוֹמָא חַד הֲווֹ אַזְלֵי חַבְרַיָּיא עִמֵּיהּ דְּרִבִּי שִׁמְעוֹן, אָמַר רַבִּי שִׁמְעוֹן, חֲמֵינָא אִלֵּין עַמִּין כֻּלְּהוּ עִלָּאֵי, וְיִשְׂרָאֵל תַּתָּאֵי מִכֻּלְּהוּ, מַאי טַעֲמָא. בְּגִין דְּמַלְכָּא אַשְׁדַר מַטְרוֹנִיתָא מִינֵּהּ, וְאָעִיל אַמָּהוּ בְּאַתְרָהָא (כלומר שפחה). כְּמָה דְאַתְּ אָמֵר, (משלי ל׳:כ״ג) תַּחַת שָׁלֹשׁ רָגְזָה אֶרֶץ וְגוֹ'. תַּחַת עֶבֶד כִּי יִמְלוֹךְ וְגוֹ'. וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ. מַאן שִׁפְחָה. הִיא כִּתְרָא נוּכְרָאָה, דְּקָטַל קוּדְשָׁא בְּרִיךְ הוּא בּוּכְרָא דִּלְהוֹן בְּמִצְרַיִם. דִּכְתִיב (שמות י״א:ה׳) עַד בְּכוֹר הַשִּׁפְחָה אֲשֶׁר אַחַר הָרֵחָיִם. אַחַר הָרֵחָיִם הֲוַת יָתְבָא בְּקַדְמִיתָא, וְהַשְׁתָּא, הַאי שִׁפְחָה תִּירַשׁ גְּבִירְתָּהּ.</p>\n<p>בָּכָה רַבִּי שִׁמְעוֹן וְאָמַר, מַלְכָּא בְּלָא מַטְרוֹנִיתָא, לָא אִקְרֵי מַלְכָּא. מַלְכָּא דְּאִתְדַּבָק בְּשִׁפְחָה בְּאֲמָּהוּ דְּמַטְרוֹנִיתָא, אָן הוּא יְקָרָא דִּילֵיהּ. וּזְמִינָא קָלָא לְבַשְּׂרָא לְמַטְרוֹנִיתָא, וְלֵימָא (זכריה ט׳:ט׳) גִּילִי מְאֹד בַּת צִיּוֹן הָרִיעִי בַּת יְרוּשָׁלַ ם הִנֵּה מַלְכֵּךְ יָבֹא לָךְ צַדִּיק וְנוֹשָׁע הוּא. כְּלוֹמַר, צַדִּיק הוּא נוֹשָׁע, בְּגִין דְּהֲוָה רָכִיב עַד הַשְׁתָּא בַּאֲתַר דְּלָאו דִּילֵיהּ, בַּאֲתַר נוּכְרָאָה, וְיָנִיק לֵיהּ.</p>\n<p>וְעַל דָּא כְּתִיב עָנִי וְרוֹכֵב עַל חֲמוֹר, עָנִי (דלא) הֲוָה בְּקַדְמִיתָא, וְרוֹכֵב עַל חֲמוֹר, כְּמָה דְּאוֹקִימְנָא, אִינּוּן כִּתְרִין תַּתָּאִין דְּעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, דְּקָטִיל קוּדְשָׁא בְּרִיךְ הוּא בּוּכְרָא דִּלְהוֹן בְּמִצְרַיִם, הֲדָא הוּא דִכְתִיב, (שמות י״א:ה׳) וְכָּל בְּכוֹר בְּהֵמָה, וְהָא אוֹקִימְנָא מִלֵּי. כִּבְיָכוֹל צַדִיק וְנוֹשָׁע הוּא, הוּא וַדַּאי יַתִּיר מִכֹּלָּא. בְּגִין דְּעַד הַשְׁתָּא שָׁארֵי צַדִּיק בְּלָא צֶדֶק. וְהַשְׁתָּא דְּיִזְדַּוְּוגוּן כַּחֲדָא, צַדִיק וְנוֹשָׁע הוּא, דְּהָא לָא יָתִיב בְּסִטְרָא אָחֳרָא. תָּאנָא, (ישעיהו נ״ז:א׳) הַצַּדִיק אָבָד וְאֵין אִישׁ שָׂם עַל לֵב וְגוֹ', הַאי קְרָא קַשְׁיָא, הַצַּדִיק אָבָד, נֶאֱבַד מִבָּעֵי לֵיהּ, מַהוּ אָבָד. אֶלָּא אָבָד מַמָּשׁ, וּמַאי אָבָד. אָבַד לְמַטְרוֹנִיתָא, וְאִתְדַּבָק בַּאֲתַר אָחֳרָא, דְּאִקְרֵי שִׁפְחָה.</p>\n<p>אָמַר רִבִּי יִצְחָק לְרִבִּי שִׁמְעוֹן, אִי נִיחָא קָמֵי דְּמֹר, הָא דְּתָנֵינָן, דִּכְתִיב (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם, מַאן דְּאָמַר, דְּעַל שִׁבְעָה קַיְימִין קַיְּימָא עָלְמָא. וּמַאן דְּאָמַר, עַל חַד קַיְּימָא עָלְמָא, הֵיךְ מִתְיַישְּׁבָן מִלֵּי. אָמַר לֵיהּ, כֹּלָּא מִלָּה חַד הוּא, דְּהָא ז' אִינּוּן וּבְהוּ אִית חַד קַיְּימָא, דְּאִקְרֵי צַדִּיק, וְקַיְימֵי עָלֵיהּ, וְעָלְמָא בְּהַאי אִתְקַיְּימָא. וְכַד אִתְקַיְּימָא עָלְמָא עָלֵיהּ, כְּאִלּוּ אִתְקַיָּים עַל כֻּלְּהוּ שִׁבְעָה. וְעַל דָּא כְּתִיב, וְצַדִּיק יְסוֹד עוֹלָם. וְהָא אוֹקִימְנָא מִלֵּי בְּכַמָּה אֲתַר.</p>\n<p>וְתָאנָא, הַאי שִׁפְחָה זְמִינָא לְשַׁלְּטָאָה בְּאַרְעָא קַדִּישָׁא דִּלְתַּתָּא, כְּמָה דַּהֲוַת מַטְרוֹנִיתָא שַׁלְטָא בְּקַדְמִיתָא, דִּכְתִיב (ישעיהו א׳:כ״א) צֶדֶק יָלִין בָּהּ, וְהַשְׁתָּא שִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ בְּכֹלָּא. וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא, לְאָתָבָא לְמַטְרוֹנִיתָא לְאַתְרָהָא כְּקַדְמֵיתָא, וּכְדֵין מִמַּאן הוּא חֶדְוָותָא, הֲוִי אֵימָא חֶדְוָותָא דְּמַלְכָּא, וְחֶדְוָותָא דְּמַטְרוֹנִיתָא. חֶדְוָותָא דְּמַלְכָּא, בְּגִין דְּיֵתוּב לָהּ וְיִתְפְּרַשׁ מִשִּׁפְחָה, כַּדְקָא אֲמֵינָא. וְחֶדְוָותָא דְּמַטְרוֹנִיתָא, בְּגִין דְּתֵיתוּב לְאִזְדַּוְּוגָא בְּמַלְכָּא, הֲדָא הוּא דִכְתִיב גִּילִי מְאֹד בַּת צִיּוֹן וְגוֹ'.</p>\n<p>תָּא חֲזֵי, כְּתִיב וְהָיְתָה זֹּאת לָכֶם לְחֻקַּת עוֹלָם. וְהָיְתָה לָכֶם מִבָּעֵי לֵיהּ, מַאי זֹאת. הָא דְּאַמָרָן, לְחֻקַּת עוֹלָם. בְּכָל אֲתַר וַאֲתַר חֻקַּת עוֹלָם אִתְקְרֵי, גְּזֵרַה דְּמַלְכָּא, דְּעַיִּיל כָּל נִמוּסוֹי בַּאֲתַר דָּא, וְאַסְתִּים לוֹן, כְּמָאן דְּסָתִים כֹּלָּא, בְּאַסְקוּפָא חֲדָא. (ק\"פ) חֻקַּת עוֹלָם וַדַאי. בְּהַאי זֹאת <Nonei></i>רָשִׁים וְחָקַק כָּל גְּנִיזִין דִּילֵיהּ, וְכָל טְמִירִין דִּילֵיהּ.</p>"],[9520012142,"<p>(ויקרא ט״ז:כ״ט) בַּחֹדֶשׁ הַשְּׁבִיעִי בֶּעָשׂוֹר לַחֹדֶשׁ. בֶּעָשׂוֹר דַּיְיקָא, כְּמָה דְּאוֹקִימְנָא. תְּעַנּוּ אֶת נַפְשׁוֹתֵיכֶם, וַדַּאי הָכִי הוּא, וְהָא אִתְּמַר נַפְשׁוֹתֵיכֶם וַדַּאי. דְּהָא בְּנַפְשָׁא תַּלְיָא מִלְּתָא, וּבְגִין כַּךְ, אֲכִילָה וּשְׁתִיָּה מִתְּשִׁיעָאָה, יַתִיר מִיּוֹמָא אָחֳרָא. וְאַף עַל גַּב דְּהַאי מִלָּה אִתְּמַר בְּגַוְונָא אָחֳרָא, וְכֹלָּא שַׁפִּיר, וְהַאי וְהַאי מִלָּה חֲדָא, וְכָל חַד בְּאַתְרֵיהּ, וְהָכִי הוּא.</p>\n<p>וְתָאנָא, בְּהַאי יוֹמָא, כָּל חֵידוּ, וְכָל נְהִירוּ, וְכָל וַותְּרָנוּתָא דְּעָלְמִין, כֻּלְּהוּ תַּלְיָין בְּאִימָּא עִלָּאָה, דְּכָל מַבּוּעִין נַגְדִּין וְנָפְקִין מִנָּהּ. וּכְדֵין נְהִירִין כָּל אִינּוּן בּוּצִינִין, וְנַהֲרִין בִנְהִירוּ בְּחֶדְוָותָא, עַד דְּמִתְבְּסַם כֹּלָּא. וּכְדֵין כָּל אִינּוּן דִּינִין אִשְׁתְּכָחוּ בִּנְהִירוּ, וְדִינָא לָא אִתְעָבִיד, וְעַל דָּא תְּעַנּוּ אֶת נַפְשׁוֹתֵיכֶם.</p>\n<p>אָמַר רִבִּי אַבָּא, הָא אוֹקִים לָהּ מֹר, מִן גּוּפָא דְּמַתְנִיתָא, לָא גָּלוּ יִשְׂרָאֵל מֵאַרְצָם, עַד שֶׁכָּפְרוּ בְּקוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִּיב, (שמואל ב כ׳:א׳) אֵין לָנוּ חֵלֶק בְּדָוִד וְלֹא נַחֲלָה בְּבֶן יִשַׁי, וְהָא אִתְּמַר. קְרָא אַחֲרִינָא אַשְׁכַּחְנָא בְּהַאי, דִּכְתִּיב, (מלכים א י״ב:ט״ז) רְאֵה בֵיתְךָ דָּוִד. אָמַר לֵיהּ, הָכִי הוּא וַדַּאי, בֵּית דָּוִד אִקְרֵי, כְּמָה דִּכְתִּיב, (ישעיהו ב׳:ה׳) בֵּית יַעֲקֹב לְכוּ וְנֵלְכָה בְּאוֹר יְיָ'. בֵּית יַעֲקֹב, כְּמָה דְאַתְּ אָמֵר (ישעיהו ס׳:ז׳) וּבֵית תִּפְאַרְתִּי אֲפָאֵר. לְכוּ וְנֵלְכָה בְּאוֹר יְיָ', דִּכְתִּיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן, וְנָטַע הַאי גַּן לְאִשְׁתַּעְשְׁעָא בֵּיהּ עִם צַדִּיקַיָּיא, דְּבֵיהּ שַׁרְיָין.</p>\n<p>תָּאנָא, כְּתִיב אַךְ בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה יוֹם הַכִּפּוּרִים הוּא וְגוֹ' וְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם. וּכְתִיב וְהָיְתָה לָכֶם לְחֻקַּת עוֹלָם בַּחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ'. אַךְ דִּכְתִּיב, מַאי קָא בָּעֵי הָכָא. אָמַר לֵיהּ, לְמִעוּטָא קָא אַתְיָא. דְּכֵיוָן דְּאָמַר וְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם בְּתִשְׁעָה לַחֹדֶשׁ, אָמַר לְבָתַר אַךְ בֶּעָשׂוֹר. אַךְ עָשׂוֹר מִבָּעֵי לֵיהּ, דְּבֶעָשׂוֹר תַּלְיָא מִלְּתָא.</p>\n<p>אָמַר לֵיהּ אִי הָכִי, (שמות י״ב:ט״ו) אַךְ בַּיוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְּׂאוֹר מִבָּתֵּיכֶם, וְתָנֵינָן אַךְ חִלֵּק, חֶצְיוֹ אָסוּר בַּאֲכִילַת חָמֵץ, וְחֶצְיוֹ מוּתָּר. אוּף הָכָא אַךְ בֶּעָשׂוֹר לַחֹדֶשׁ, אֵימָא דְּחֶצְיוֹ אָסוּר בַּמְּלָאכָה (נ\"א באכילה), וְחֶצְיוֹ מוּתָּר. אָמַר לֵיהּ אוּף הָכָא בִּוְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם תַּלְיָא, דְּהָא עִנּוּי לָא אִשְׁתְּכַח אֶלָּא מִפַּלְגּוּת יוֹמָא וּלְהָלְאָה, וְשַׁפִּיר הוּא אַךְ חִלֵּק בִּוְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, כְּתִיב, (ויקרא ט״ז:ל׳) כִּי בַּיוֹם הַזֶה יְכַפֵּר עֲלֵיכֶם וְגוֹ'. אֲכַפֵּר עַלֵיכֶם מִבָּעֵי לֵיהּ. אֶלָּא יְכַפֵּר עֲלֵיכֶם, לְאַכְלְלָא יוֹבְלָא, דְּנָגִיד מַבּוּעֵי לְאַשְׁקָאָה בְּהַאי יוֹמָא לְכָל עִיבָר, לְאַרְוָאָה כֹּלָּא, וּלְאַשְׁקָאָה כֹּלָּא. וְדָא עֲלֵיכֶם, כְּלוֹמַר, בְּגִינֵיכוֹן לְדַכְּאָה לְכוֹן בְּהַאי יוֹמָא, דִּכְתִּיב לִפְנֵי יְיָ' תִּטְהָרוּ. וְלָא יִשְׁלוֹט עָלַיְיכוּ דִּינָא.</p>\n<p>רִבִּי יְהוּדָה, אָמַר זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ, וּבָעֵי לְדַכְּאָה לְהוּ, דְּלָא יִשְׁתְּכַּח בְּהוּ חוֹבָה, בְּגִין דִּיהוֹן בְּנֵי הֵיכָלֵיהּ, וִידוּרוּן בְּהֵיכָלֵיהּ. וּלְזִמְנָא דְּאָתֵי כְּתִיב, (יחזקאל ל״ו:כ״ה) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וְגוֹ'.</p>"],[9520012143,"<p>רִבִּי יְהוּדָה פָּתַח, (תהילים ק״ל:א׳) שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים קְרָאתִיךָ יְיָ'. תָּנֵינָן, בְּשַׁעֲתָא דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, בָּעָא לְמִבְרֵי בַּר נָשׁ, אַמְלִיךְ בְּאוֹרַיְיתָא, אָמְרָה קַמֵּיהּ, תִּבְעֵי לְמִבְרֵי הַאי בַּר נָשׁ, זַמִּין הוּא לְמֶחֱטֵי קַמָּךְ, זַמִּין הוּא לְאַרְגָּזָא קַמָּךְ. אִי תַּעֲבִיד לֵיהּ כְּעוֹבָדוֹי, הָא עָלְמָא לָא יָכִיל לְמֵיקָם קַמָּךְ, כָּל שֶׁכֵּן הַהוּא בַּר נָשׁ. אָמַר לֵיהּ, וְכִי לְמַגָּנָא אִתְקָרִינָא, (שמות ל״ד:ו׳) אֵל רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם.</p>\n<p>וְעַד לָא בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, בָּרָא תְּשׁוּבָה, אָמַר לָהּ לִתְשׁוּבָה, אֲנָא בָּעֵינָא לְמִבְרֵי בַּר נָשׁ בְּעָלְמָא, עַל מְנָת דְּכַד יְתוּבוּן לָךְ מֵחוֹבֵיהוֹן, דְּתֶהֱוִי זְמִינָא לְמִשְׁבַּק חוֹבֵיהוֹן, וּלְכַפְּרָא עָלַיְיהוּ. וּבְכָל שַׁעֲתָא וְשַׁעֲתָא תְּשׁוּבָה זְמִינָא לְגַבֵּי בְּנֵי נָשָׁא, וְכַד בְּנֵי נָשָׁא תַּיְיבִין מֵחוֹבַיְיהוּ, הַאי תְּשׁוּבָה תָּבַת לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְכִפֵּר עַל כֹּלָּא, וְדִינִין אִתְכַּפְיָין, וּמִתְבַּסְּמָן כֻּלְּהוּ, וּבַר נָשׁ אִתְדָּכֵי מֵחוֹבֵיהּ.</p>\n<p>אֵימָתַי אִתְדָּכֵי בַּר נָשׁ מֵחוֹבֵיהּ בְּשַׁעֲתָא דְּעָאל בְּהַאי תְּשׁוּבָה כַּדְקָא חֲזֵי. רִבִּי יִצְחָק אָמַר, דְּתָב קָמֵי מַלְכָּא עִלָּאָה, וְצַלֵּי <Nonei></i>צְלוֹתָא מֵעוּמְקָא דְּלִבָּא, הֲדָא הוּא דִכְתִיב מִמַּעֲמַקִּים קְרָאתִיךָ יְיָ'.</p>\n<p>רִבִּי אַבָּא אָמַר, מִמַּעֲמַקִּים קְרָאתִיךָ יְיָ', אֲתַר גָּנִיז הוּא לְעֵילָּא, וְהוּא עַמִיקָא (שמות ס\"ג ע\"ב) דְּבֵירָא, וּמֵהַאי נָפְקִין נַחֲלִין וּמַבּוּעִין לְכָל עִיבָר, וְהַהוּא עֲמִיקָא דַּעֲמִיקְתָא אִקְרֵי תְּשׁוּבָה. וּמַאן דְּבָעֵי לְאָתָבָא וּלְאִתְדַכְּאָה מֵחוֹבוֹי, בְּהַאי עוּמְקָא אִצְטְרִיךְ לְמִקְרֵי לְּקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב מִמַּעֲמַקִּים קְרָאתִיךָ יְיָ'.</p>\n<p>תָּאנָא, בְּשַׁעֲתָא דְּהֲוָה בַּר נָשׁ חָב קָמֵי מָארֵיהּ, וְקָרִיב קָרְבָּנֵיהּ עַל מַדְבְּחָא, וְכַהֲנָא מְכַפֵּר עָלֵיהּ, וּבָעֵי בָּעוּתֵיהּ עָלֵיהּ, מִתְעָרִין רַחֲמֵי, וְדִינִין מִתְבַּסְּמָן, וּתְשׁוּבָה אָרִיק בִּרְכָאן, בְּמַבּוּעִין דְּנַגְדִּין וְנָפְקִין, וּמִתְבָּרְכִין כֻּלְּהוּ בּוּצִינִין כַּחֲדָא, וּבַר נָשׁ אִתְדָּכֵי מֵחוֹבֵיהּ.</p>\n<p>תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא, אַפִּיק עֶשֶׂר כִּתְרִין, עִטְרִין קַדִּישִׁין לְעֵילָּא, דְּאִתְעַטָּר בְּהוּ, וּמִתְלַבָּשׁ בְּהוּ, וְהוּא אִינּוּן, וְאִינּוּן הוּא, כְּשַׁלְהוֹבָא דַּאֲחִידָא בְּגוּמְרָא, וְלֵית תַּמָּן פִּרוּדָא. לָקֳבֵיל דְּנָא, אִית עֶשֶׂר כִּתְרִין דְּלָא קַדִּישִׁין לְתַתָּא, וְאִינּוּן אֲחִידָן בְּזוּהֲמָא דְּטוּפְרָא דְּחַד עִטְרָא קַדִּישָׁא, דְּאִקְרֵי חָכְמָה. וְעַל דָּא אִקְרוּן חָכְמוֹת.</p>"],[9520012144,"<p>וְתָאנָא, עֲשְׂרָה זִינֵי חָכְמוֹת אִלֵּין נַחְתּוּ לְעָלְמָא. וְכֻלְּהוּ אִסְתְּאָבוּ (ס\"א אשתאבו) בְּמִצְרַיִם, בַּר מֵחַד דְּאִתְפְּשַׁט בְּעָלְמָא, וְכֻלְּהוּ זִינֵי חַרְשֵׁי אִינּוּן, וּמִנַּיְיהוּ יַדְעֵי מִצְרַיִם חַרְשִׁין, עַל כָּל בְּנֵי עָלְמָא. וְכַד מִצְרָאֵי בָּעָאן לְמֶעְבַּד כְּנוּפְיָיא בְּחַרְשַׁיְיהוּ לְעוֹבָדֵיהוֹן, הֲווֹ נַפְקֵי לְחַקְלָא לְטוּרֵי רָמַאֵי, וְדַבְחִין דְּבָחִין, וְעַבְדִין גּוּמִּין בְּאַרְעָא, וְסַחֲרִין הַהוּא דָּמָא סוֹחֲרָנֵיהּ דְּהָנֵי גּוּמִּין, וּשְׁאָר דָּמָא מִתְכַּנְּפֵי בְּהַנְהוּ גּוּמִּין, וּבִשְׂרָא שָׁוִין עָלַיְיהוּ. וּקַרְבִין קָרְבְּנֵיהוֹן, לְאִינּוּן זִינִין בִּישִׁין, וְאִינּוּן זִינִין בִּישִׁין מִתְכַּנְּשִׁין וּמִתְקָרְבִין כַּחֲדָא, וּמִתְפַּיְּיסִין בַּהֲדַיְיהוּ בְּהַהוּא טוּרָא.</p>\n<p>יִשְׂרָאֵל דַּהֲווֹ בְּשִׁעְבּוּדֵיהוֹן, הָווֹ מִתְקָרְבִין לְהוֹן, וְאוֹלְפוּ מִנַּיְיהוּ, וַהֲווּ טָעָאן בַּתְרַיְיהוּ, וְהַיְינוּ דִּכְתִּיב כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם אֲשֶׁר יְשַׁבְתֶּם בָּהּ לֹא תַעֲשׂוּ וּכְמַעֲשֵׂה אֶרֶץ כְּנַעַן וְגוֹ', וּכְתִיב וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם לַשְּׂעִירִים וְגוֹ'. תָּאנָא, בְּשַׁעֲתָא דַּהֲווֹ מְקָרְבִין לְהוֹן עַל גַּבֵּי חַקְלָא, וַהֲווּ מְזַמְּנֵי הַהוּא דָּמָא, וּמְקָרְבֵי קָרְבְּנַיְיהוּ, הֲווֹ מִתְכַּנְּפֵי כָּל אִינּוּן זִינִין בִּישִׁין, וְחָמָאן לְהוֹן כְּגַוְונָא דִשְׂעִירִים, כֻּלְּהוּ מַלְיָין שַׂעֲרָא, וּמוֹדָעֵי לְהוּ מַה דְּאִינּוּן בַּעְיָין.</p>\n<p>תָּא חֲזֵי, יִצְחָק מַה כְּתִיב בֵּיהּ, (בראשית כ״ז:כ״ב) וַיִּגַּשׁ יַעֲקֹב אֶל יִצְחָק אָבִיו וַיְמֻשֵּׁהוּ, אָמַר, דָּא לָא אִתְעָדֵי (ס\"א הכא לא אתער), אֶלָּא מִטַּלָּא דִּשְׁמַיָּא דְּנָגִיד עַל אַרְעָא. אָמַר רִבִּי יוֹסֵי, וּמִשְׁמַנֵּי הָאָרֶץ, בְּכֹלָּא בְּרָכֵיהּ. מַאי טַעְמָא. בְּגִין דְּחָמָא לֵיהּ בְּשַׂעְרָא, אָמַר לְמֶעְבַּר דָּא, וּמִשְׁמַנֵּי הָאָרֶץ אִצְטְרִיךְ, וְלָא זוּהֲמָא דְּאַרְעָא, דְּהַאי זוּהֲמָא הוּא דְּאַרְעָא, וְכַד טַלָּא דִּשְׁמַיָּא וּמִגְדָּא דְּאַרְעָא מִתְחַבְּרָאן אִתְעַבָּר הַאי זוּהֲמָא.</p>"],[9520012145,"<p>אָמַר רִבִּי חִיָּיא, בַּתְרַיְיתָא דְּאִינּוּן כִּתְרִין תַּתָּאִין דְּלָא קַדִּישִׁין הַאי הוּא, הֲדָא הוּא דִכְתִיב, (דברים י״ח:י״א) וְדוֹרֵשׁ אֶל הַמֵּתִים, וְדָּא הוּא עֲשִׁירָאָה דְּכֹלָּא. דְּתַנְיָא אָמַר רִבִּי יִצְחָק אָמַר רִבִּי יְהוּדָה, נַפְשָׁתָא דְּרַשִׁיעַיָּיא אִלֵּין אִינּוּן מַזִּיקִין דְּעָלְמָא.</p>\n<p>אָמַר רִבִּי יוֹסֵי, אִי הָכִי טַב לְהוּ לְחַיָּיבַיָּא דְּאִתְעַבְּדִין מַזִּיקִין בְּעָלְמָא, אָן הוּא עוֹנְשָׁא דְּגֵיהִנָּם. אָן הוּא בִּישָׁא דִּזְמִינָא לְהוּ בְּהַהוּא עָלְמָא. אָמַר רִבִּי חִיָּיא, הָכִי תָּנֵינָן, וְהָא אוֹקִימְנָא מִלֵּי, נַפְשָׁתָא דְּרַשִׁיעַיָּיא בְּשַׁעֲתָא דְּנָפְקִין מֵעָלְמָא, כַּמָה גַּרְדִּינֵי נִמוּסִין מִזְדַּמְּנֵי לְקַבְּלָא לְהוּ, וּלְאַעְלָאָה לְהוּ לְגֵּיהִנָם, וְעָאלִין לְהוּ בִּתְלַת דִּינִין בְּכָל יוֹמָא, בַּגֵיהִנָּם. לְבָתַר מִזְדַּוְּוגֵי בְּהוּ, וְאַזְלִין וְשָׁאטִין בְּעָלְמָא, וּמַטְעָן לְהוּ לְרַשִׁיעַיָּיא, לְאִינּוּן דְּקָא אַסְתִּים תְּשׁוּבָה מִקַּמַּיְיהוּ. לְבָתַר תַּיְיבִין לְהוּ לְגֵּיהִנָם, וְאִתְסָאבִין (נ\"א ואתדנון) תַּמָּן, וְכַךְ בְּכָל יוֹמָא.</p>\n<p>לְבָתַר דְּאַזְלִין בְּהוּ, וְשָׁאטִין בְּהוּ בְּעָלְמָא, מְהַדְּרִין לְקִבְרַיְיהוּ, וְחַמָּן תּוֹלַעְתָּא דְּגוּפָא מְנַקְּרֵי בִּשְׂרָא וּמִתְאַבְּלָן עָלַיְיהוּ, וְאִינּוּן חַרְשִׁין הֲווֹ אַזְלֵי לְבֵי קִבְרֵי, וְחַרְשֵׁי בְּחַרְשַׁיְיהוּ, וְעַבְדִין חַד צַלְמָא דְּבַר נָשׁ, וְדַבְחִין קַמֵּיהּ חַד צְפִירָא. לְבָתַר עָאלִין לְהַהוּא <Nonei></i>צְפִירָא, בְּהַהוּא קִבְרָא, וְהַהוּא צַלְמָא מְתַּבְּרִין (ס\"א מדברין) לֵיהּ לְאַרְבַּע סִטְרִין, וּמַעֲלִין לֵיהּ לְאַרְבַּע זִיוְויָין דְּקִבְרָא. כְּדֵין מְחָרְשֵׁי בְּחַרְשַׁיְיהוּ, וּמִתְכַּנְּפֵי אִינּוּן כִּנּוּפֵי, וְאִינּוּן זִינִין בִּישִׁין, וּמַיְיתִין הַהִיא נַפְשָׁתָא, וְעָאל בְּקִבְרָא וּמִשְׁתָּעֵי בַּהֲדַיְיהוּ.</p>"],[9520012146,"<p>אָמַר רִבִּי יִצְחָק, זַכָּאִין אִינּוּן צַדִּיקַיָּיא בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, דְּהָא כֻּלְּהוּ קַדִּישִׁין. גּוּפָא דִּלְהוֹן קַדִּישָׁא. נַפְשָׁא דִּלְהוֹן קַדִּישָׁא. רוּחָא דִּלְהוֹן קַדִּישָׁא. נִשְׁמְתָא דִּלְהוֹן קֹדֶשׁ קֳדָשִׁים. תְּלַת דַּרְגִּין אִינּוּן, כְּגַוְונָא דִּלְעֵילָּא. דְּתַנְיָא אָמַר רִבִּי יְהוּדָה, כְּתִיב (בראשית א׳:כ״ד) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, דָּא הִיא נִשְׁמְתָא (עלאה) דְּאָדָם קַדְמָאָה (עלאה). תָּא חֲזֵי, תְּלַת דַּרְגִּין אִינּוּן, וְאִתְדְּבָקוּ כְּחַד, נֶפֶשׁ, רוּחַ, נְשָׁמָה. וְעִלָּאָה מִנַּיְיהוּ, נְשָׁמָה.</p>\n<p>דְּאָמַר רִבִּי יוֹסֵי, בְּכֻלְּהוּ בְּנֵי נָשָׁא אִית נֶפֶשׁ, וְאִית נֶפֶשׁ עִלָּאָה מִנֶּפֶשׁ. זָכָה בַּר נָשׁ בְּהַאי נֶפֶשׁ, מְרִיקִין עָלֵיהּ עִטְרָא חַד, דְּאִקְרֵי רוּחַ. הֲדָא הוּא דִכְתִיב, (ישעיהו ל״ב:ט״ו) עַד יֵעָרֶה עָלֵינוּ רוּחַ מִמָּרוֹם. כְּדֵין אִתְּעַר בַּר נָשׁ בְּאִתְעָרוּתָא אָחֳרָא עִלָּאָה, לְאִסְתַּכְּלָא בְּנִמוּסֵי מַלְכָּא קַדִּישָׁא. זָכָה בַּר נָשׁ בֵּיהּ בְּהַהוּא רוּחָא, מְעַטְּרִין לֵיהּ בְּכִתְרָא קַדִּישָׁא עִלָּאָה, דְּכָלִיל כֹּלָּא, דְּאִקְרֵי נְשָׁמָה. דְּאִתְקְרֵי נִשְׁמַת אֱלוֹהַּ.</p>\n<p>וְתָאנָא בְּרָזָא דְּרָזִין, בְּגוֹ רָזִין דְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא. הַאי קְרָא, דִּכְתִּיב, (קהלת ד׳:ב׳) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, כֵּיוָן דִּכְתִּיב וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים, אֲמַאי שְׁכְּבָר מֵתוּ. אֶלָּא שְׁכְּבָר מֵתוּ בְּהַאי עָלְמָא, בְּפוּלְחָנָא דְּמָארֵיהוֹן. (בראשית רכ\"ד ע\"ב)</p>\n<p>וְתַמָּן כְּתִיב, תְּלָת מָדוֹרִין עֲבַד קוּדְשָׁא בְּרִיךְ הוּא לְצַדִּיקַיָּיא, חַד (ס\"א דזכו אינון צדיקייא דלא אישתציאו מהאי עלמא וכד אצטריך) לְנַפְשָׁאן דְּאִינּוּן צַדִּיקַיָּיא, דְּלָא אִסְתְּלָקוּ מֵהַאי עָלְמָא, וּשְׁכִיחִין בְּהַאי עָלְמָא. וְכַד אִצְטְרִיךְ עָלְמָא רַחֲמִין, וְאִינּוּן חַיִּין יַתְבִין בְּצַעֲרָא, אִינּוּן מְצָלוּ צְלוֹתָא עָלַיְיהוּ, וְאַזְלִין וּמוֹדְעִין מִלָּה לְאִינּוּן דְּמִיכִין דְּחֶבְרוֹן, וּמִתְעָרִין, וְעַאלִין לְגַּן עֵדֶן דְּאַרְעָא, דְּתַמָּן רוּחֵיהוֹן דְּצַדִּיקַיָּיא, מִתְלַבְּשָׁן בְּעִטְרִין דִּנְהוֹרָא, וְאִתְיַיעֲטוּ בְּהוּ, וְגַזְרִין גְּזֵרָה, וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד רְעוּתָא דִּלְהוֹן, וְחָס עַל עָלְמָא.</p>\n<p>וְאִינּוּן נַפְשָׁן דְּצַדִּיקַיָּיא, מִשְׁתַּכְּחִין בְּהַאי עָלְמָא, לְאַגָּנָא עַל חַיַּיָא, וְהַאי אִקְרֵי נֶפֶשׁ, וְדָא לָא אִסְתָּלְקָא (ס\"א אשתצי) מֵהַאי עָלְמָא, וּשְׁכִיחָא בְּהַאי עָלְמָא, לְאִסְתַּכְּלָא וּלְמִנְדַּע וּלְאַגָּנָא עַל דָּרָא. וְהַאי הוּא דְּאָמְרוּ חַבְרַיָּיא, דְּמֵתֵי יַדְעֵי בְּצַעֲרָא דְּעָלְמָא. וְעוֹנְשָׁא דְּחַיָּיבִין דִּי בְּאַרְעָא, בְּהַאי הוּא, דִּכְתִּיב וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מֵעַמֶּיהָ.</p>\n<p>וּמָדוֹרָא תִּנְיָינָא הוּא גַּן עֵדֶן דִּי בְּאַרְעָא. בֵּיהּ עָבֵד קוּדְשָׁא בְּרִיךְ הוּא מָדוֹרִין עִלָּאִין יַקִּירִין, כְּגַוְונָא דְּהַאי עָלְמָא, וּכְגַוְונָא דְּעָלְמָא עִלָּאָה. וְהֵיכָלִין בִּתְרֵין גַּוְונִין, דְּלֵית לְהוֹן חוּשְׁבָּנָא, וְאִילָנִין וַעֲשָׂבִין וְרֵיחִין דְּסַלְּקִין בְּכָל יוֹמָא. וּבְהַאי אֲתַר שָׁארֵי הַהוּא דְּאִקְרֵי רוּחַ דְּאִינּוּן צַדִּיקַיָּיא, וּמָדוֹרָא דְּהַהוּא רוּחָא בֵּיהּ שָׁארֵי. וְכָל רוּחַ וְרוּחַ מִתְלַבְּשָׁא בִּלְבוּשׁ יַקִּירָא, כְּגַוְונָא דְּהַאי עָלְמָא, וּכְגַוְונָא דְּהַהוּא עָלְמָא עִלָּאָה.</p>\n<p>מָדוֹרָא תְּלִיתָאָה, הַהוּא מָדוֹרָא עִלָּאָה קַדִּישָׁא דְּאִיתְקְרֵי צְרוֹרָא דְּחַיֵּי. דְּתַמָּן מִתְעַדְּנָא הַהוּא דַּרְגָּא עִלָּאָה קַדִּישָׁא, דְּאִקְרֵי נְשָׁמָה. וְהַאי אִתְדְּבַק לְאִתְעַנְּגָא בְּעִדּוּנָא עִלָּאָה. עָלֵיהּ כְּתִיב, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ' וְהִרְכַּבְתִּיךָ וְגוֹ'.</p>\n<p>וְתָאנָא, בְּשַׁעֲתָא דְּאִצְטְרִיךְ עָלְמָא רַחֲמֵי, וְאִינּוּן צַדִּיקַיָּיא זַכָּאִין. הַהוּא נֶפֶשׁ דְּאִשְׁתַּכְּחָא בְּעָלְמָא, לְאַגָּנָא עַל עָלְמָא. נֶפֶשׁ סָלִיק וְאָזִיל וְשָׁאט בְּעָלְמָא, וּמוֹדַע לְרוּחַ. וְרוּחַ סָלִיק וְאִתְעַטָּר, וּמוֹדַע לַנְשָׁמָה. וּנְשָׁמָה לְּקוּדְשָׁא בְּרִיךְ הוּא. וּכְדֵין חָס קוּדְשָׁא בְּרִיךְ הוּא עַל עָלְמָא. כְּדֵין נַחְתָּא מֵעֵילָּא לְתַתָּא, נְשָׁמָה אוֹדַע לְרוּחַ, וְרוּחַ אוֹדַע לְנַפְשָׁא.</p>\n<p>וּבְכָל שַׁבְּתָא וְשַׁבְּתָא, וְרֵישׁ יַרְחָא, כֻּלְּהוּ, מִתְחַבְּרָן וּמִתְעַטְּרָן כְּחַד, עַד דְּאִזְדְּוָּוגוּ לְמֵיתֵי לְסַגְּדָא לְמַלְכָּא עִלָּאָה. וּלְבָתַר תַּיְיבִין לְאַתְרַיְיהוּ. הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ו:כ״ג) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתוֹ יָבֹא כָל בָּשָׂר וְגוֹ'.</p>\n<p>וּבְשַׁעֲתָא דְּאִצְטְרִיךְ עָלְמָא רַחֲמֵי, וְחַיַיָא אַזְלֵי וּמוֹדָעֵי לְהוּ לְנַפְשַׁיְיהוּ דְּצַדִּיקַיָּיא, וּבָכָאן עַל קִבְרַיְיהוּ, אִינּוּן דְּאִתְחָזוֹ לְאוֹדָעָא לְהוּ. מַאי טַעְמָא. דְּשַׁוְיָין רְעוּתָא דִּלְהוֹן לְאִתְדַּבְּקָא נַפְשָׁא בְּנַפְשָׁא, <Nonei></i>כְּדֵין אִתְּעָרִין נַפְשַׁיְיהוּ דְּצַדִּיקַיָּיא, וּמִתְכַּנְּפֵי וְאַזְלִין וְשָׁאטִין לִדְמִיכֵי חֶבְרוֹן, וּמוֹדִיעֵי לְהוּ צַעֲרָא דְּעָלְמָא. וְכֻלְּהוּ עָאלִין בְּהַהוּא פִּתְחָא דְגַּן עֵדֶן, וּמוֹדִיעֵי לְרוּחַ. וְאִינּוּן רוּחִין דְּמִתְעַטְּרָן בְּגַּן עֵדֶן, מַלְאֲכֵי עִלָּאִין אַזְלֵי בֵּינַיְיהוּ. וְכֻלְּהוּ מוֹדִיעִין לַנְשָׁמָה. וּנְשָׁמָה אוֹדָעַת לְּקוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ בָּעָאן רַחֲמֵי עַל חַיִּין, וְחָס קוּדְשָׁא בְּרִיךְ הוּא עַל עָלְמָא בְּגִינֵיהוֹן. וְעַל דָּא אָמַר שְׁלֹמֹה, וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ וְגוֹ'.</p>\n<p>אָמַר רִבִּי חִיָּיא, תַּוַּוהְנָא אִי אִית מַאן דְּיָדַע לְאוֹדָעָא לְהוּ לְמֵתַיָּיא, בַּר אֲנָן. אָמַר רִבִּי אַבָּא, צַעֲרָא מוֹדְעָא לְהוּ. אוֹרַיְיתָא מוֹדְעָא לְהוּ. דְּהָא בְּשַׁעֲתָא דְּלֵית מַאן דְּיָדַע בְּהַאי, (בראשית רכ\"א ע\"א) אַפְקֵי אוֹרַיְיתָא סָמוּךְ לְקִבְרִי, וְאִינּוּן מִתְעָרֵי, עַל אוֹרַיְיתָא עַל מַה אִתְגַּלְיָיא לְהַהוּא אֲתַר, כְּדֵין דּוּמָה אוֹדַע לְהוֹן.</p>\n<p>אָמַר רִבִּי יוֹסֵי, וְאִינּוּן יַדְעֵי דְּהָא עָלְמָא בְּצַעֲרָא, וְחַיַיָא לָא אִתְחָזוּן, וְלָא יַדְעֵי לְאוֹדָעָא לְהוּ. בֵּיהּ שַׁעֲתָא כֻּלְּהוּ צַוְוחִין עַל אוֹרַיְיתָא דְּאִתְקְלָנָא וְאִתְגַּלְיָיא לְהַהוּא אֲתַר. אִי בְּנֵי נָשָׁא תַּיְיבִין וּבָכָאן בְּלִבָּא שְׁלִים, וְתַיְיבִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, כֻּלְּהוּ מִתְכַּנְּשֵׁי, וּבָעָאן רַחֲמֵי, וּמוֹדִיעִין לְאִינּוּן דְּמִיכֵי חֶבְרוֹן, וְעָאלִין וּמוֹדְעִין לְרוּחַ דבְּגַּן עֵדֶן, כְּמָה דְּאַמָרָן.</p>\n<p>וְאִי אִינּוּן לָא תַּיְיבִין בְּלִבָּא שְׁלִים לְמִבָּעֵי וּלְמִבְכֵּי עַל צַעֲרָא דְּעָלְמָא. וַוי לְהוֹן, דְּכֻלְּהוּ מִתְכַּנְּפֵי לְרֵיקָא אַמְרֵי מַאן גָּרַם לְאוֹרַיְיתָא קַדִּישָׁא דְּאִתְגַּלְיָיא עַל יְדַיְיהוּ בְּלָא תְּשׁוּבָה. וְכֻלְּהוּ אָתָאן לְאִתְחַדְתָּא (ס\"א לאדכרא) חוֹבַיְיהוּ בְּגִינֵי כַּךְ לָא יַהֲכוּן תַּמָּן בְּלָא תְּשׁוּבָה וּבְלָא תַּעֲנִיתָא לְמִבָּעֵי בָּעוּתָא קַמַּיְיהוּ. רִבִּי אַבָּא אָמַר, (ס\"א כלא אתלת) בְּלָא תְּלַת תַּעֲנִיתָא. רִבִּי יוֹסֵי אָמַר, אֲפִילּוּ חַד, וּבְהַהוּא יוֹמָא, וּבִלְבַד דְּעָלְמָא יָתִיב בְּצַעֲרָא טְפֵי, כְּדֵין כֻּלְּהוּ מִזְדַּוְּוגֵי לְמִבָּעֵי רַחֲמִין עַל עָלְמָא.</p>"]]});
